insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-363', 'Liaison: the nurse whose wounds will not heal', 'Ms Jessy, 34, a nurse from Kollam, has had a leg wound that keeps getting infected despite many treatments. A syringe was found in her locker and cultures show gut bacteria. The surgical team asks you to talk with her.', 600, '[{"item":"Planned the conversation with the team beforehand","weight":1},{"item":"Was non-confrontational and supportive","weight":2},{"item":"Shared the concerns honestly without accusing","weight":2},{"item":"Allowed her to save face","weight":2},{"item":"Offered ongoing psychological help","weight":2},{"item":"Considered her risk, including suicide, after the conversation","weight":2},{"item":"Considered confidentiality and patient safety duties as a nurse with senior advice","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-364', 'Liaison: is he depressed after the stroke if he cannot find words?', 'Mr Ravindra, 66, from Satara, has expressive aphasia after a stroke. The rehab team wonders if he is depressed because he refuses therapy. Assess his mood.', 420, '[{"item":"Checked comprehension before choosing a method","weight":2},{"item":"Used yes or no questions, gestures or visual scales","weight":2},{"item":"Took a history from his wife on behaviour, eating, crying and interest","weight":2},{"item":"Asked about suicidal thoughts in a way he could answer","weight":2},{"item":"Concluded likely post-stroke depression","weight":1},{"item":"Planned treatment and communication support","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-365', 'Liaison: more and more painkillers after a back operation', 'Mrs Neeta, 46, from Vadodara, had spinal surgery four months ago. She now takes tramadol many times a day and asks for ''stronger'' tablets. The orthopaedic surgeon asks you to see her.', 420, '[{"item":"Validated the pain and avoided labelling","weight":2},{"item":"Took a detailed use history including extra supplies","weight":2},{"item":"Asked about withdrawal symptoms","weight":1},{"item":"Asked about the jerking spell and other risks","weight":2},{"item":"Asked about mood and anxiety","weight":1},{"item":"Explained dependence without blame","weight":1},{"item":"Planned a slow, supported reduction and other pain treatments","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-366', 'Liaison: explaining the gut and the brain', 'Mr Varun, 30, from Delhi, has cramps, bloating and loose stools, worse before presentations. All tests, including colonoscopy, are normal. The gastroenterologist asks you to explain the condition and the role of stress.', 420, '[{"item":"Validated the symptoms as real","weight":2},{"item":"Explained the diagnosis positively, not as ''nothing found''","weight":2},{"item":"Explained the gut-brain connection in plain words","weight":2},{"item":"Addressed the cancer worry","weight":1},{"item":"Discussed diet, stress and therapy options","weight":1},{"item":"Agreed a plan","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-367', 'Liaison: vivid dreams and low mood on HIV treatment', 'Mr Anil, 35, from Pune, has HIV and takes an efavirenz-based regimen. He reports terrifying dreams, poor sleep and low mood. Assess him and advise his HIV doctor.', 420, '[{"item":"Linked symptoms to the start of the regimen","weight":2},{"item":"Asked about missed doses","weight":2},{"item":"Asked about mood and suicidal thoughts","weight":2},{"item":"Explored stigma and disclosure worries","weight":1},{"item":"Advised discussing a switch with the HIV doctor rather than missing doses","weight":2},{"item":"Planned support for mood","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-368', 'Liaison: new suspicion during tuberculosis treatment', 'Mr Lalit, 40, from Nagpur, started tuberculosis treatment six weeks ago. He now believes his wife is plotting against him and is not sleeping. The chest physician asks your opinion.', 420, '[{"item":"Took the timeline in relation to TB medicines","weight":2},{"item":"Asked about alcohol, nutrition and pyridoxine","weight":2},{"item":"Considered isoniazid-related psychosis","weight":2},{"item":"Considered other causes: alcohol, infection spreading to the brain, delirium","weight":2},{"item":"Advised against stopping TB treatment without the TB team''s plan","weight":2},{"item":"Suggested pyridoxine, alcohol support and low-dose antipsychotic if needed","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-369', 'Liaison: assessment before weight-loss surgery', 'Mrs Priya, 38, from Chennai, is being considered for bariatric surgery. The surgeon asks for a psychological assessment.', 420, '[{"item":"Explained the purpose of the assessment","weight":1},{"item":"Asked about eating patterns including binge eating","weight":2},{"item":"Asked about mood, past mental illness and self-harm","weight":2},{"item":"Asked about alcohol and substance use","weight":1},{"item":"Explored expectations of surgery","weight":2},{"item":"Discussed readiness and support","weight":1},{"item":"Gave a balanced recommendation","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-370', 'Liaison: a living kidney donor who may not be free to choose', 'Mrs Kamla, 32, from Jaipur, has offered to donate a kidney to her husband''s brother. The transplant team asks you to assess her psychologically before the authorisation committee meets.', 600, '[{"item":"Saw her alone and explained confidentiality","weight":2},{"item":"Explored her understanding of the risks","weight":2},{"item":"Explored her motives and feelings","weight":2},{"item":"Asked directly about pressure, threats or payment","weight":3},{"item":"Assessed mood and anxiety","weight":1},{"item":"Explained that she can decline, and how a medical reason can be given if she chooses","weight":2},{"item":"Reported concerns to the team appropriately","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-371', 'Liaison: skipping insulin to stay thin', 'Ms Ananya, 19, from Kolkata, has type 1 diabetes and has been admitted twice with ketoacidosis this year. The diabetes team asks you to see her.', 420, '[{"item":"Explored weight and shape concerns","weight":2},{"item":"Asked directly and kindly about missing insulin for weight","weight":3},{"item":"Asked about binge eating and other weight control","weight":1},{"item":"Explained the dangers: ketoacidosis, eye, kidney and nerve damage","weight":2},{"item":"Asked about mood and self-harm","weight":1},{"item":"Planned joint care with the diabetes team and eating disorder support","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-372', 'Liaison: living with a new stoma', 'Mr Imran, 45, from Lucknow, had bowel cancer surgery and now has a colostomy. He refuses to look at it and will not let the stoma nurse teach him. Assess him.', 420, '[{"item":"Acknowledged the shock of body change","weight":2},{"item":"Explored specific fears: smell, prayer, intimacy, work","weight":2},{"item":"Assessed mood and suicidal thoughts","weight":1},{"item":"Addressed not eating","weight":1},{"item":"Connected him to the stoma nurse and peer support","weight":1},{"item":"Respected religious concerns and suggested asking a trusted religious adviser","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-373', 'Liaison: nightmares after intensive care', 'Mrs Gita, 58, from Surat, spent two weeks on a ventilator with severe pneumonia. A month after discharge she has nightmares and panic. Take a history.', 420, '[{"item":"Explored memories, including frightening false memories from ICU","weight":2},{"item":"Asked about nightmares, flashbacks and avoidance","weight":2},{"item":"Asked about mood and suicidal thoughts","weight":1},{"item":"Explained that delirium memories are common and not madness","weight":2},{"item":"Mentioned weakness and memory problems after ICU","weight":1},{"item":"Offered treatment and follow-up","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-374', 'Liaison: a weak leg and a positive Hoover''s sign', 'Mr Shankar, 35, from Pune, has had a weak right leg for three weeks. Scans are normal. The neurologist asks you to examine for signs of functional weakness and explain the diagnosis.', 420, '[{"item":"Tested hip extension in the weak leg directly","weight":1},{"item":"Tested hip extension while he flexed the other leg against resistance","weight":2},{"item":"Correctly described a positive Hoover''s sign","weight":2},{"item":"Explained the diagnosis as positive and real","weight":2},{"item":"Avoided suggesting he is faking","weight":2},{"item":"Explained that it can improve with physiotherapy","weight":1}]'::jsonb, '{"label":"Global physical examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-375', 'Liaison: sweaty, shaky and confused on insulin', 'Mr Joseph, 60, from Kochi, is on the medical ward. A nurse calls you because he is sweaty, shaky and confused and she thinks he is ''having a panic attack''. Assess him.', 420, '[{"item":"Asked about diabetes and medicines first","weight":2},{"item":"Requested a bedside sugar check immediately","weight":3},{"item":"Recognised low sugar","weight":2},{"item":"Advised immediate treatment","weight":2},{"item":"Advised rechecking and reviewing the insulin plan","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-376', 'Liaison: a teenager on acne tablets who feels low', 'Rahul, 17, from Indore, has taken isotretinoin for severe acne for three months. His dermatologist noticed he seemed withdrawn and asks you to assess him.', 420, '[{"item":"Explained confidentiality and its limits","weight":1},{"item":"Assessed mood, sleep and interest","weight":2},{"item":"Asked directly about suicidal thoughts","weight":3},{"item":"Linked timing to isotretinoin while considering other causes such as bullying","weight":2},{"item":"Advised the dermatologist to review the medicine","weight":1},{"item":"Made a safety plan and involved a parent appropriately","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-377', 'Liaison: ''please clear her for discharge''', 'A surgical resident phones: ''Please see bed 14 and clear her psychiatrically so we can discharge her today.'' Clarify the referral.', 420, '[{"item":"Asked what the specific question is","weight":2},{"item":"Asked what happened and why the team is worried","weight":2},{"item":"Asked about any overdose, injuries or medical issues still pending","weight":2},{"item":"Asked whether the patient knows about the referral","weight":1},{"item":"Explained that ''clearance'' is not a psychiatric term and that the assessment aims at safety and a plan","weight":1},{"item":"Agreed a time and how results will be shared","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-378', 'Liaison: years of pelvic pain and an unspoken past', 'Mrs Sunita, 36, from Jaipur, has had chronic pelvic pain for eight years with many normal investigations and two laparoscopies. The gynaecologist asks you to see her.', 600, '[{"item":"Validated the pain and the frustration with repeated tests","weight":2},{"item":"Explored the pain''s impact on life, relationships and sex","weight":2},{"item":"Asked gently and generally about past difficult experiences","weight":2},{"item":"Responded to disclosure with belief and without pushing for detail","weight":2},{"item":"Assessed current mood and risk","weight":1},{"item":"Offered trauma-informed care and a choice of next steps","weight":2},{"item":"Asked what she wants shared with the gynaecologist","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-379', 'Liaison: sadness or depression at the end of life', 'Mr Gopal, 67, from Madurai, has advanced lung cancer and is in palliative care. His son says he is ''depressed'' and asks for treatment. Assess Mr Gopal.', 420, '[{"item":"Explored his feelings about dying with compassion","weight":2},{"item":"Asked about enjoyment, hope and self-worth","weight":2},{"item":"Asked about wishes to hasten death and suicidal thoughts","weight":2},{"item":"Distinguished sadness and grief from a depressive illness","weight":2},{"item":"Explained this to his son","weight":1},{"item":"Offered support rather than medicine","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-380', 'Liaison: a farmer recovering from pesticide poisoning', 'Mr Shivaji, 44, a farmer from Yavatmal, drank pesticide after his crop failed and is now off the ventilator in ICU. Assess him.', 600, '[{"item":"Assessed the attempt: planning, intent, regret about surviving","weight":2},{"item":"Assessed current suicidal thoughts","weight":3},{"item":"Explored debt, crop loss and shame","weight":2},{"item":"Asked about alcohol","weight":1},{"item":"Explored protective factors","weight":1},{"item":"Planned means restriction: locked pesticide storage, family involvement","weight":2},{"item":"Linked him to financial and farmer support schemes and follow-up","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-381', 'Liaison: advising surgeons about an antidepressant before an operation', 'An orthopaedic surgeon asks whether Mrs Lata, 63, from Pune, should stop her sertraline before knee replacement next week. Advise the surgeon.', 420, '[{"item":"Explained the small increase in bleeding risk, more with aspirin or anti-inflammatory drugs","weight":2},{"item":"Advised usually continuing the SSRI because of relapse and discontinuation risks","weight":2},{"item":"Suggested limiting other bleeding-risk drugs and using stomach protection if needed","weight":1},{"item":"Raised the serotonin toxicity risk with tramadol","weight":2},{"item":"Suggested alternative pain plans and monitoring","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-382', 'Liaison: handing back to the referring physician', 'You have assessed Mr Prem, 70, from Ahmedabad, on the medical ward for ''confusion''. You found delirium due to a chest infection on top of mild dementia, low suicide risk, and no need for psychiatric medicine. Give your opinion to the physician by phone.', 420, '[{"item":"Introduced self and the patient clearly","weight":1},{"item":"Gave the diagnosis in one or two lines","weight":2},{"item":"Gave practical recommendations","weight":2},{"item":"Answered the antipsychotic and transfer questions clearly","weight":2},{"item":"Stated the risk assessment","weight":1},{"item":"Agreed follow-up and documented in the notes","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-383', 'Emergency: calming an angry man in casualty', 'Mr Bunty, 32, from Delhi, has waited five hours in casualty for his father, who has chest pain. He is shouting at the nurses and kicking a chair. Security is nearby. Talk to him.', 420, '[{"item":"Kept a safe distance and an open exit for both","weight":2},{"item":"Introduced self with a calm voice and open posture","weight":1},{"item":"Listened and named his feelings","weight":2},{"item":"Avoided saying ''calm down'' or arguing","weight":1},{"item":"Found out what he needs and offered something real","weight":2},{"item":"Set a clear, respectful limit on the kicking","weight":1},{"item":"Followed through with the promised information","weight":1}]'::jsonb, '{"label":"Global de-escalation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-384', 'Emergency: a young woman stopped on the railway tracks', 'Ms Priyanka, 23, from Thane, was pulled off the railway tracks by a railway constable, who brought her to casualty. She is uninjured. Assess her.', 600, '[{"item":"Introduced self and ensured privacy and safety","weight":1},{"item":"Explored the events and the attempt: planning, intent, interruption","weight":2},{"item":"Asked about current suicidal thoughts and plans","weight":3},{"item":"Asked about access to means, including what she has with her","weight":2},{"item":"Explored precipitants and support","weight":1},{"item":"Explored protective factors","weight":1},{"item":"Judged high risk and planned close supervision and admission or intensive support","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-385', 'Emergency: a panic attack in casualty', 'Ms Kavya, 26, from Bengaluru, is in casualty with a racing heart and fear of dying. Her ECG, oxygen and sugar are normal. Help her settle.', 420, '[{"item":"Stayed calm and spoke slowly","weight":1},{"item":"Explained that the tests are normal and what a panic attack is","weight":2},{"item":"Guided slow breathing","weight":2},{"item":"Used grounding: naming things she can see or feel","weight":1},{"item":"Explained that the attack will pass","weight":1},{"item":"Arranged follow-up for recurrent attacks","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-386', 'Emergency: frightened and suspicious after bhang at Holi', 'Mr Abhishek, 20, from Mathura, drank bhang thandai at a Holi party five hours ago. He is now terrified, believes friends are trying to kill him and hears whispers. Assess and manage.', 420, '[{"item":"Checked vital signs and other substances taken","weight":2},{"item":"Explored the timeline and amount","weight":1},{"item":"Assessed psychotic symptoms and risk","weight":2},{"item":"Moved him to a quiet, low-stimulus space","weight":2},{"item":"Reassured him that the effects usually pass","weight":1},{"item":"Considered a short-acting benzodiazepine if very distressed","weight":1},{"item":"Planned follow-up if symptoms persist beyond the intoxication","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-387', 'Emergency: shaking, seeing insects and burning up', 'Mr Anthony, 49, from Panaji, was admitted three days ago for a leg fracture. Today he is confused, sweating and picking insects off the sheets. Assess and manage.', 600, '[{"item":"Recognised the timeline after the last drink","weight":2},{"item":"Identified delirium with autonomic overactivity","weight":2},{"item":"Named delirium tremens","weight":2},{"item":"Gave benzodiazepines promptly by a suitable route","weight":2},{"item":"Gave parenteral thiamine","weight":2},{"item":"Corrected fluids and electrolytes, including magnesium","weight":1},{"item":"Arranged close monitoring or ICU and looked for other causes","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-388', 'Emergency: pinpoint pupils and slow breathing', 'A young man is brought into casualty from the bus stand, barely rousable. Assess and manage.', 420, '[{"item":"Checked airway, breathing and circulation first","weight":2},{"item":"Recognised the opioid overdose picture","weight":2},{"item":"Supported breathing with oxygen and a bag-valve mask","weight":1},{"item":"Gave naloxone by a suitable route and repeated if needed","weight":2},{"item":"Explained the short action of naloxone and the risk of falling asleep again","weight":2},{"item":"Offered harm reduction and treatment","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-389', 'Emergency: when exactly did she take the paracetamol?', 'Ms Ruchi, 19, from Kanpur, says she took ''a lot of Crocin'' after a fight with her boyfriend. She looks well and wants to go home. Take a focused history and coordinate with the medical team.', 420, '[{"item":"Asked for the exact amount, strength and times","weight":3},{"item":"Recognised a staggered overdose","weight":2},{"item":"Asked about alcohol and other substances","weight":1},{"item":"Explained that feeling well does not mean she is safe","weight":2},{"item":"Informed the medical team for blood tests and antidote treatment","weight":2},{"item":"Planned the psychosocial assessment once medically fit","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-390', 'Emergency: a man on the terrace ledge', 'The police have called you to a residential building in Noida. Mr Manish, 35, is sitting on the terrace ledge. Police are present and have cleared the area. Talk to him from a safe distance.', 600, '[{"item":"Followed police safety guidance and kept a safe distance","weight":2},{"item":"Introduced self and asked his name","weight":1},{"item":"Spoke slowly and listened more than talked","weight":2},{"item":"Did not argue, lecture or make promises that cannot be kept","weight":2},{"item":"Asked directly about suicidal intent","weight":2},{"item":"Explored reasons for living gently","weight":2},{"item":"Invited small steps such as moving back from the edge","weight":2}]'::jsonb, '{"label":"Global crisis communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-391', 'Emergency: the police bring a woman found wandering', 'Police in Kolkata bring Ms X, about 40, found wandering at Howrah station for two days. She is unkempt, talking to herself and cannot give her name. The constable asks ''Can we leave her with you?'' Talk to the constable and plan.', 420, '[{"item":"Thanked the constable and gathered information","weight":1},{"item":"Explained the police duty to bring such a person to a public mental health establishment for assessment","weight":2},{"item":"Explained that the assessment must happen promptly and she cannot be kept in a police lock-up","weight":2},{"item":"Asked for help in tracing family and for a missing person report","weight":2},{"item":"Planned a medical and mental health assessment and admission if needed","weight":2},{"item":"Considered her safety and vulnerability, including sexual abuse","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-392', 'Emergency: a patient with a knife in the OPD', 'Mr Rafiq, 29, from Bhopal, has paranoid schizophrenia and has stopped medicine. In your OPD room he pulls out a vegetable knife and says, ''The neighbour sent you to poison me.'' You are between him and the door. Respond.', 600, '[{"item":"Kept calm and did not move towards him","weight":2},{"item":"Kept or moved to a position with a clear exit","weight":2},{"item":"Raised the alarm when it was safe to do so","weight":2},{"item":"Spoke softly, acknowledged his fear, did not argue about the belief","weight":2},{"item":"Did not attempt to disarm him","weight":2},{"item":"Asked him to put the knife down in a non-threatening way","weight":1},{"item":"Left the room and let security and police manage the knife, then planned assessment","weight":2}]'::jsonb, '{"label":"Global de-escalation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-393', 'Emergency: mute and still after an argument', 'Ms Shabnam, 21, from Moradabad, has not spoken or moved for six hours since a family argument. Her mother says she has ''gone into a trance''. Assess her.', 600, '[{"item":"Checked vital signs and sugar","weight":2},{"item":"Excluded intoxication, seizures and head injury","weight":2},{"item":"Examined for catatonic signs: posturing, rigidity, waxy flexibility","weight":2},{"item":"Noted signs inconsistent with true unconsciousness","weight":2},{"item":"Considered dissociative stupor","weight":2},{"item":"Planned a safe, supportive approach and later exploration of stress","weight":1},{"item":"Considered a lorazepam challenge if catatonia could not be ruled out","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-394', 'Emergency: first help after a building collapse', 'A building has collapsed in Bhiwandi. Mrs Salma, 40, was rescued with minor cuts. Her son is still missing. She is shaking and crying near the relief tent. Offer psychological first aid.', 420, '[{"item":"Approached calmly and introduced self","weight":1},{"item":"Checked immediate needs: injury, water, shelter","weight":2},{"item":"Listened without pushing for details","weight":2},{"item":"Helped with practical steps: register the missing son, find information","weight":2},{"item":"Did not give false reassurance","weight":1},{"item":"Connected her with family or support","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-395', 'Emergency: a relief camp after the floods', 'You are a mental health volunteer at a flood relief camp in Assam. The camp officer asks what mental health help should be offered to the 300 people there. Advise the officer.', 420, '[{"item":"Explained that most distress after disasters is normal and settles","weight":2},{"item":"Prioritised basic needs, safety, family reunion and routines","weight":2},{"item":"Advised psychological first aid for all and identifying those at high risk","weight":2},{"item":"Advised referral for severe reactions, suicidal thoughts and substance problems","weight":1},{"item":"Advised continuing medicines for people with existing illness","weight":2},{"item":"Suggested child-friendly spaces and community activities","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-396', 'Emergency: a phone call about a new mother at midnight', 'Mr Ravi, from Coimbatore, calls the psychiatry helpline at midnight. His wife Meena delivered nine days ago. She has not slept for three nights and says the baby is ''not ours, swapped by the hospital''. Triage the call.', 600, '[{"item":"Stayed calm and took key details: address, phone, who is home","weight":2},{"item":"Asked about thoughts or statements about harming the baby or herself","weight":3},{"item":"Asked about past bipolar disorder and stopped medicines","weight":1},{"item":"Recognised possible postpartum psychosis as an emergency","weight":2},{"item":"Advised that the baby is never left alone with her for now","weight":2},{"item":"Arranged urgent assessment tonight: emergency department or crisis team, ambulance if needed","weight":2},{"item":"Explained when to call emergency services","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-397', 'Emergency: tingling hands and cramped fingers', 'Ms Jyoti, 18, from Lucknow, is brought to casualty after an argument with her parents. She is breathing fast, her hands are cramped into claws and her lips tingle. Her family thinks it is a fit. Assess and manage.', 420, '[{"item":"Checked she was alert and breathing, and ruled out a fit","weight":2},{"item":"Checked oxygen saturation and sugar","weight":1},{"item":"Recognised overbreathing with hand spasm","weight":2},{"item":"Explained why the hands cramp in simple words","weight":1},{"item":"Coached slow breathing, without using a paper bag","weight":2},{"item":"Calmed the setting and asked the family to step back","weight":1},{"item":"Planned follow-up for the stress behind it","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-398', 'Emergency: hot, wild and paranoid after methamphetamine', 'Mr Lalchhanhima, 27, from Aizawl, is brought by friends after using methamphetamine for two days. He is paranoid, sweating and fighting staff. Assess and manage.', 600, '[{"item":"Recognised a medical emergency: high temperature, fast pulse, high BP","weight":2},{"item":"Stopped prone restraint and positioned him safely","weight":2},{"item":"Gave benzodiazepines as first-line sedation","weight":2},{"item":"Started active cooling and fluids","weight":2},{"item":"Checked for muscle breakdown, kidney injury and heart problems","weight":2},{"item":"Avoided relying on antipsychotics alone and monitored closely","weight":1},{"item":"Arranged high-dependency care","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-399', 'Emergency: mania at night and a family who cannot cope', 'Mr Naveen, 34, from Hubballi, has bipolar disorder. His family brings him at 1 am: he has not slept for four nights, smashed a TV and threatened his father. He refuses treatment. Assess and decide on next steps.', 600, '[{"item":"Assessed mental state and risk quickly and safely","weight":2},{"item":"Tried de-escalation and offered oral medicine first","weight":2},{"item":"Explained emergency treatment under the Mental Healthcare Act and its limits","weight":2},{"item":"Involved the nominated representative","weight":2},{"item":"Used the least restrictive option and documented reasons","weight":1},{"item":"Planned assessment for supported admission within the time limit","weight":2},{"item":"Arranged medical monitoring","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-400', 'Emergency: the hostel warden finds a note', 'The warden of a college hostel in Kota calls. He has found a note in a student''s room saying ''Sorry Mummy Papa, I failed you''. The student, Aman, 18, is not in his room. Advise him.', 420, '[{"item":"Treated this as an emergency","weight":2},{"item":"Asked about the student''s last known location and time","weight":2},{"item":"Advised immediate search of likely places with others, including the terrace","weight":2},{"item":"Advised calling emergency services and police","weight":2},{"item":"Advised contacting parents through college records","weight":1},{"item":"Advised staying with the student once found and bringing him for assessment","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-401', 'Emergency: an overdose in a Tamil-speaking teenager, with an interpreter', 'Selvi, 15, from Hosur, is medically fit after taking her mother''s blood pressure tablets. She speaks only Tamil. A trained interpreter is with you. Her uncle, who speaks Hindi, offers to interpret instead. Assess her risk.', 600, '[{"item":"Declined to use the uncle as interpreter and explained why politely","weight":3},{"item":"Briefed the interpreter on confidentiality and exact translation","weight":2},{"item":"Saw Selvi without family present","weight":2},{"item":"Assessed intent, planning and current suicidal thoughts","weight":2},{"item":"Asked about safety at home in a general, then specific, way","weight":2},{"item":"Recognised a disclosure of sexual abuse and acted under POCSO","weight":2},{"item":"Planned that she does not go home with the alleged abuser, with child protection services","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-402', 'Emergency: a fit in a man who drinks water all day', 'Mr Ramesh, 40, has long-term schizophrenia and lives in a rehabilitation home in Pune. He had a seizure this morning. Staff say he drinks water from every tap ''all day''. Assess and manage.', 420, '[{"item":"Linked the seizure to low sodium","weight":2},{"item":"Recognised excessive water drinking in chronic psychosis","weight":2},{"item":"Arranged medical admission and fluid restriction","weight":2},{"item":"Warned that sodium must be corrected slowly","weight":3},{"item":"Checked other causes of low sodium, including medicines","weight":1},{"item":"Planned weight monitoring and supervised fluid intake on return","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-403', 'Emergency: self-harm in police custody', 'Mr Sunny, 22, from Ludhiana, was arrested for theft and banged his head against the cell wall. Police bring him in handcuffs. Assess him.', 420, '[{"item":"Asked for privacy as far as safety allows","weight":2},{"item":"Checked for injuries, including the head, and documented them","weight":2},{"item":"Assessed withdrawal","weight":2},{"item":"Assessed suicide risk directly","weight":2},{"item":"Documented the allegation of assault and reported it appropriately","weight":1},{"item":"Advised custody staff on observation and withdrawal treatment","weight":2},{"item":"Explained confidentiality limits","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-404', 'Emergency: at midnight, fleeing a violent husband', 'Mrs Nirmala, 30, from Jaipur, comes to casualty at midnight with her two children and a bruised face. She says her husband threatened to kill her. Assess her safety and help her.', 420, '[{"item":"Ensured privacy and believed her","weight":1},{"item":"Assessed injuries and asked about strangulation specifically","weight":2},{"item":"Assessed danger: threats to kill, escalation, weapons","weight":2},{"item":"Asked about the children''s safety","weight":2},{"item":"Explained options: shelter, One Stop Centre, women''s helpline, protection orders","weight":2},{"item":"Respected her choice about a police complaint while documenting injuries","weight":1},{"item":"Planned safe care tonight","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-405', 'Emergency: staff debrief after a nurse is assaulted', 'An hour ago, a patient on your ward in Chennai hit Staff Nurse Selvi with a chair. She has a cut on her arm and has been treated. Lead a short debrief with the nurse and a ward attendant.', 420, '[{"item":"Checked wellbeing and injuries first","weight":2},{"item":"Set a non-blaming tone","weight":2},{"item":"Let each person describe what happened and how they feel","weight":2},{"item":"Identified system issues: staffing, alarms, warnings not acted on","weight":2},{"item":"Agreed actions and who will follow them up","weight":2},{"item":"Offered support: time off, counselling, help with a police complaint if she wishes","weight":1}]'::jsonb, '{"label":"Global leadership competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-406', 'Emergency: a catatonic man who is not drinking', 'Mr Jagdish, 38, from Indore, has been mute and motionless for three days and has drunk very little. Catatonia has been confirmed on examination. Explain and carry out the next steps to the examiner.', 420, '[{"item":"Checked vital signs and medical causes, including fever and stiffness for NMS","weight":2},{"item":"Started fluids and monitoring","weight":2},{"item":"Gave a lorazepam challenge and reassessed signs","weight":2},{"item":"Interpreted the response","weight":1},{"item":"Planned regular lorazepam and treatment of the cause","weight":1},{"item":"Named ECT as the next step if lorazepam fails or he is in danger","weight":2},{"item":"Avoided high-potency antipsychotics in the acute phase","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-407', 'Emergency: brought from the dargah', 'Mr Irfan, 25, from Ajmer, was kept at a dargah for a week by his family because of ''a jinn''. He is now brought to casualty, not eating and shouting at unseen people. Assess him and talk to his father.', 420, '[{"item":"Greeted the family respectfully and listened to their explanation","weight":2},{"item":"Assessed the patient''s safety, intake and physical health","weight":2},{"item":"Avoided dismissing the family''s beliefs","weight":2},{"item":"Explained the illness in plain words","weight":1},{"item":"Suggested that prayer and medical treatment can go together","weight":2},{"item":"Agreed a treatment plan with the family","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-408', 'Emergency: first response to a survivor of sexual assault', 'Ms Pooja, 22, from Pune, arrives in casualty with a friend, saying she was raped last night by an acquaintance. The duty doctor asks you to see her first because she is very distressed.', 600, '[{"item":"Ensured privacy, a female staff member if wished, and the friend''s role","weight":1},{"item":"Believed her and said it was not her fault","weight":2},{"item":"Did not ask for unnecessary detail","weight":2},{"item":"Explained her choices and that consent is needed for each step of the examination","weight":2},{"item":"Explained free treatment, emergency contraception and infection prevention","weight":2},{"item":"Explained that she can decide whether to file a police complaint, and the hospital''s own duties","weight":2},{"item":"Assessed safety and arranged follow-up support","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-409', 'Emergency: drunk and demanding to go home', 'Mr Pradeep, 38, from Nashik, came in after a fall while drunk. He has a scalp wound that needs stitches and his CT scan is pending. He insists on going home. Assess and decide.', 420, '[{"item":"Explained the risks in simple words","weight":2},{"item":"Assessed his capacity to decide about leaving","weight":2},{"item":"Recognised that intoxication can temporarily remove capacity","weight":2},{"item":"Tried persuasion and involving his wife","weight":1},{"item":"Acted in his best interests with the least restrictive approach","weight":2},{"item":"Documented the assessment and reasons","weight":1},{"item":"Planned reassessment as he sobers up","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-410', 'Emergency: a seizure in the waiting room', 'A young man in the psychiatry OPD waiting room in Varanasi falls and starts jerking all four limbs. Respond.', 420, '[{"item":"Kept him safe and noted the time","weight":2},{"item":"Did not restrain him or put anything in his mouth","weight":2},{"item":"Called for help and planned emergency medicine if it lasted over five minutes","weight":2},{"item":"Placed him in the recovery position after the seizure","weight":1},{"item":"Checked breathing, sugar and injuries","weight":1},{"item":"Took a history from his mother","weight":1},{"item":"Planned medical review","weight":1}]'::jsonb, '{"label":"Global assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-411', 'Emergency: back after five days off clozapine', 'Mr Siddharth, 30, from Pune, has taken clozapine 350 mg a day for two years. He ran out of tablets five days ago and is becoming suspicious again. He asks to ''just restart my usual dose today''. Advise him and his mother.', 600, '[{"item":"Asked exactly when the last dose was taken","weight":2},{"item":"Explained why the full dose cannot be restarted after more than two days off","weight":3},{"item":"Explained the risks: low blood pressure, collapse, seizures, heart problems","weight":2},{"item":"Planned restarting at a low dose and building up again","weight":2},{"item":"Checked blood count monitoring rules after the break","weight":1},{"item":"Addressed the returning symptoms and supervision","weight":1},{"item":"Planned to prevent running out again","weight":1}]'::jsonb, '{"label":"Global medication safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-412', 'Emergency: presenting a night assessment to the on-call consultant', 'It is 3 am. You assessed Ms Kiran, 27, from Gurugram, in casualty after she cut her wrists. Phone the on-call consultant and present your assessment and recommendation, using the card.', 420, '[{"item":"Gave a concise summary in the first sentence","weight":2},{"item":"Presented the risk factors and current intent","weight":2},{"item":"Mentioned intoxication and that she was reassessed sober","weight":1},{"item":"Gave protective factors","weight":1},{"item":"Recommended a clear disposition with reasons","weight":2},{"item":"Addressed the question about admission thoughtfully","weight":2},{"item":"Stated the immediate safety plan","weight":1}]'::jsonb, '{"label":"Global case presentation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-413', 'MHCA: explaining an independent admission', 'Ms Renu, 29, from Dehradun, has severe depression and has asked to be admitted. Explain independent admission and her rights in plain words.', 420, '[{"item":"Explained that she is choosing to come in","weight":2},{"item":"Explained that treatment needs her informed consent","weight":2},{"item":"Explained that she can ask to leave","weight":1},{"item":"Explained the short assessment that may happen if staff are worried about her safety when she asks to leave","weight":2},{"item":"Explained confidentiality and what family will be told with her agreement","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-414', 'MHCA: an independent patient who wants to leave tonight', 'Mr Ajay, 34, from Lucknow, was admitted as an independent patient three days ago with severe depression. At 9 pm he demands to leave, saying ''there is no point staying''. Nurses found a rope in his bag. Assess and decide.', 600, '[{"item":"Listened to his reasons and stayed calm","weight":1},{"item":"Assessed suicide risk, including the rope","weight":3},{"item":"Explained the legal power to delay discharge for a short assessment","weight":2},{"item":"Explained that he may need supported admission if criteria are met","weight":2},{"item":"Informed the nominated representative and documented","weight":1},{"item":"Kept him safe in the least restrictive way","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-415', 'MHCA: your rights on the ward', 'Mr Thomas, 41, from Kochi, has just been admitted under supported admission. He asks ''What rights do I have now?'' Explain.', 420, '[{"item":"Explained the right to information about his admission and treatment","weight":1},{"item":"Explained the right to contact family and friends, and to refuse visitors","weight":1},{"item":"Explained confidentiality and that his employer will not be told without consent","weight":2},{"item":"Explained the right to see his records, with rare limits","weight":1},{"item":"Explained how to complain and to appeal to the Mental Health Review Board","weight":2},{"item":"Explained the right to free legal aid","weight":1},{"item":"Gave the information in writing too","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-416', 'MHCA: a patient asks to read his case file', 'Mr Ganesh, 45, from Pune, was discharged after a manic episode. He asks for a copy of his file. One note records his wife''s report of his threats, which she asked to keep private. Respond.', 420, '[{"item":"Confirmed his right to access his records","weight":2},{"item":"Explained the process for getting a copy","weight":1},{"item":"Explained that some information can be withheld if it would cause serious harm, such as third-party information","weight":2},{"item":"Offered to go through the file with him","weight":1},{"item":"Considered the third-party confidentiality and harm to others","weight":2},{"item":"Documented the decision and reasons","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-417', 'MHCA: a reporter wants a photo on the ward', 'A TV reporter has come to your ward in Bhopal for a story on ''mental hospitals''. He wants to photograph patients and interview one man who is happy to talk. Respond.', 420, '[{"item":"Was polite and explained the hospital''s duty","weight":1},{"item":"Explained that photos or details of patients cannot be released without their consent","weight":2},{"item":"Recognised that Raju may lack capacity to consent while manic","weight":2},{"item":"Protected other patients from being photographed","weight":2},{"item":"Offered alternatives: an interview with staff, or patients who consent when well","weight":1},{"item":"Referred to the hospital''s media office","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-418', 'MHCA: what the law says about physical restraint', 'A new ward attendant in Nagpur asks why the team did not tie a patient who kept shouting. Explain the rules on physical restraint.', 420, '[{"item":"Explained that restraint is allowed only as the only way to prevent immediate harm","weight":2},{"item":"Explained that the psychiatrist in charge authorises it","weight":1},{"item":"Explained that it must be for the shortest time with regular supervision","weight":2},{"item":"Explained that it is never for punishment or because of staff shortage","weight":2},{"item":"Explained recording, informing the nominated representative and reporting to the Board","weight":2},{"item":"Explained de-escalation first","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-419', 'MHCA: a son kept in chains at home', 'On a community visit near Siwan, you find Mohan, 30, chained to a tree outside his house. His mother says he gets violent. Speak to her.', 420, '[{"item":"Approached her with respect, not blame","weight":2},{"item":"Listened to why the family did this","weight":1},{"item":"Explained clearly that chaining is not allowed by law and is harmful","weight":2},{"item":"Arranged immediate safe release with support","weight":2},{"item":"Offered practical help: treatment nearby, free medicines, home visits","weight":2},{"item":"Planned follow-up","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-420', 'MHCA: an insurance company refused cover', 'Mrs Rachna, 38, from Gurugram, was admitted for depression. Her health insurer has refused to pay because ''mental illness is excluded''. She asks what she can do.', 420, '[{"item":"Explained that insurers must cover mental illness on the same basis as physical illness","weight":2},{"item":"Explained the steps: written claim, grievance to insurer, ombudsman or regulator","weight":2},{"item":"Offered a supporting letter or certificate","weight":1},{"item":"Respected confidentiality about her employer","weight":1},{"item":"Acknowledged her distress","weight":1},{"item":"Pointed to legal aid if needed","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-421', 'MHCA: the police want to book her for attempting suicide', 'Ms Divya, 20, from Vijayawada, is recovering after an overdose. A police constable arrives to ''file a case against her''. Speak to him.', 420, '[{"item":"Greeted him and asked what he needs","weight":1},{"item":"Explained that the law presumes severe stress in a person who attempts suicide","weight":2},{"item":"Explained that she should not be treated as a criminal for the attempt","weight":2},{"item":"Explained the government''s duty to provide care and rehabilitation","weight":1},{"item":"Protected her privacy and medical fitness for any statement","weight":2},{"item":"Offered to provide a medical summary if formally required","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-422', 'MHCA: admission longer than thirty days', 'Mr Mahesh, 36, from Rajkot, has been on supported admission for 27 days with schizophrenia and remains very unwell and at risk. Explain to his nominated representative, his sister, what happens next.', 600, '[{"item":"Explained that admission beyond 30 days needs a separate process","weight":2},{"item":"Explained the need for two psychiatrists'' assessments","weight":2},{"item":"Explained that the Mental Health Review Board must approve it","weight":2},{"item":"Explained the maximum periods and that each extension needs review","weight":2},{"item":"Explained his right to appeal and to legal aid","weight":1},{"item":"Explained that he can be discharged earlier if he improves","weight":1},{"item":"Explained her role as nominated representative","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-423', 'MHCA: parents ask about ECT for their fifteen-year-old', 'Ritika, 15, from Indore, has severe catatonia that has not responded to lorazepam. She is not eating. The team believes ECT may be life-saving. Discuss this with her parents.', 600, '[{"item":"Explained the seriousness of her condition","weight":2},{"item":"Explained ECT and how it is given under anaesthesia","weight":2},{"item":"Explained that ECT is generally not allowed for minors except with strict safeguards","weight":2},{"item":"Explained the need for the guardian''s informed consent and the Board''s prior permission","weight":2},{"item":"Addressed memory and safety concerns","weight":1},{"item":"Explained what happens while waiting: fluids, nutrition, lorazepam","weight":1},{"item":"Involved Ritika in the discussion as far as she can","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-424', 'MHCA: admitting a fifteen-year-old', 'Arjun, 15, from Bengaluru, has a first episode of psychosis and is at risk at home. His parents agree to admission. Explain how admission of a minor works.', 600, '[{"item":"Explained that the nominated representative, usually a parent, applies for admission","weight":2},{"item":"Explained the two independent assessments required","weight":1},{"item":"Explained that the minor must be kept separate from adults","weight":2},{"item":"Explained that a parent or attendant must stay with him throughout","weight":2},{"item":"Explained that the Board is informed and reviews the admission","weight":2},{"item":"Explained that treatment needs the parent''s informed consent and Arjun''s views count","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-425', 'MHCA: an advance directive that refuses the medicine that works', 'Ms Sunaina, 32, from Kolkata, has bipolar disorder. Her registered advance directive refuses olanzapine because of past weight gain. She is now severely manic and lacks capacity. Olanzapine helped her before. Discuss options with her mother, who is her nominated representative.', 600, '[{"item":"Explained that a valid advance directive must be followed","weight":3},{"item":"Explored alternatives that respect the directive","weight":2},{"item":"Explained that emergency treatment is a separate, short power","weight":1},{"item":"Explained that the team or family can apply to the Board to review or set aside the directive","weight":2},{"item":"Respected the reasons behind Sunaina''s directive","weight":1},{"item":"Documented and planned to review with Sunaina when she recovers","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-426', 'MHCA: when the nominated representative is not acting for the patient', 'Mr Anand, 50, from Varanasi, has schizophrenia. His brother, the nominated representative, wants him kept in hospital ''permanently'' and has taken over his share of the family house. Anand is now well enough for discharge and wants his cousin as representative. Discuss with Anand.', 600, '[{"item":"Assessed his current mental state and capacity to make this choice","weight":2},{"item":"Explained that he can appoint a new nominated representative in writing","weight":2},{"item":"Explained that the Board can be asked to review the current representative","weight":2},{"item":"Explained discharge planning that does not depend on the brother","weight":2},{"item":"Pointed him to legal aid for the property issue","weight":1},{"item":"Documented his wishes","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-427', 'Capacity: helping a woman decide with support', 'Mrs Gauri, 44, from Thane, has mild intellectual disability and depression. She needs to decide about starting an antidepressant. She gets confused by long explanations. Help her make the decision.', 420, '[{"item":"Chose a quiet time and simple language","weight":1},{"item":"Used aids such as pictures or written points","weight":2},{"item":"Involved her chosen support person without letting them decide for her","weight":2},{"item":"Checked understanding by asking her to explain back","weight":2},{"item":"Allowed time and repeated as needed","weight":1},{"item":"Respected her decision and recorded the support given","weight":2}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-428', 'Capacity: a mother asks for her daughter to be sterilised', 'Mrs Kanta, from Ajmer, brings her daughter Pinki, 22, who has moderate intellectual disability. She asks you to ''certify'' Pinki for sterilisation because she fears pregnancy and abuse. Respond to the mother.', 600, '[{"item":"Listened to the mother''s fears","weight":2},{"item":"Explained that sterilisation needs the woman''s own informed consent and cannot be done for convenience or protection","weight":3},{"item":"Explained that it does not protect against abuse","weight":2},{"item":"Explored Pinki''s own views with her directly","weight":2},{"item":"Offered safety education, supervision and reversible contraception options she can understand","weight":1},{"item":"Raised safeguarding if abuse is suspected","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-429', 'Capacity: confused today, decide tomorrow', 'Mr Shah, 70, from Surat, has delirium from an infection. The team wants his consent for a non-urgent hernia operation next month. Assess whether he can decide today.', 420, '[{"item":"Recognised delirium and its fluctuating nature","weight":2},{"item":"Tested understanding and retention","weight":2},{"item":"Concluded he lacks capacity today","weight":2},{"item":"Recognised the decision can wait until he recovers","weight":2},{"item":"Planned to reassess once the delirium clears","weight":1},{"item":"Explained this to the son","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-430', 'Capacity: a pregnant woman with schizophrenia and a family who want a termination', 'Mrs Rani, 27, from Patna, has schizophrenia and is 10 weeks pregnant. She wants to continue the pregnancy. Her husband and in-laws want a termination because ''she is mad''. Assess her and discuss.', 600, '[{"item":"Saw her alone","weight":1},{"item":"Assessed her mental state and understanding of the pregnancy","weight":2},{"item":"Assessed capacity for this decision","weight":2},{"item":"Was clear that a termination cannot be done against her will","weight":3},{"item":"Discussed medicine safety in pregnancy and relapse risk","weight":2},{"item":"Planned antenatal and perinatal mental health care","weight":1},{"item":"Addressed family pressure and safety at home","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-431', 'Capacity: refusing a blood transfusion for religious reasons', 'Ms Grace, 35, from Chennai, has heavy bleeding after surgery and refuses a blood transfusion because of her faith. The surgeons ask whether she ''lacks capacity''. Assess her.', 420, '[{"item":"Assessed understanding of the risk of death","weight":2},{"item":"Assessed retention, weighing and communication","weight":2},{"item":"Considered mental illness and coercion","weight":1},{"item":"Concluded she has capacity","weight":2},{"item":"Advised the team that a capacitous refusal must be respected even if unwise","weight":2},{"item":"Explored acceptable alternatives","weight":1},{"item":"Documented the assessment carefully","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-432', 'Capacity: a young man with intellectual disability who wants to marry', 'Mr Babloo, 28, from Varanasi, has mild intellectual disability. He wants to marry Rekha, 26, whom he met at a vocational centre. His parents want a certificate that he ''cannot marry''. Assess him.', 420, '[{"item":"Saw him alone and in simple language","weight":1},{"item":"Assessed his understanding of what marriage involves","weight":2},{"item":"Checked that the choice is his own and not under pressure","weight":2},{"item":"Recognised that capacity to marry is a relatively simple decision","weight":2},{"item":"Avoided a blanket judgement based on disability","weight":2},{"item":"Offered support for the couple and family","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-433', 'Guardianship for an adult son with intellectual disability', 'Mr and Mrs Pillai, from Thrissur, have a son Manu, 19, with severe intellectual disability. The bank will not let them operate his account. They ask what to do.', 420, '[{"item":"Explained that at 18 he is legally an adult","weight":1},{"item":"Explained the legal guardian process through the district local level committee","weight":2},{"item":"Explained that guardianship should be limited to what he needs","weight":2},{"item":"Mentioned disability certification","weight":1},{"item":"Discussed future planning: a will, trusts, siblings","weight":1},{"item":"Pointed to support organisations and the social worker","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-434', 'MHCA: a remand prisoner with psychosis', 'You visit the district jail in Gwalior. The jail medical officer asks your advice about Kallu, 30, a remand prisoner who hears voices, refuses food and is kept alone in a cell. Advise the medical officer.', 600, '[{"item":"Assessed urgency: food refusal, injuries, risk","weight":2},{"item":"Advised immediate safety and care inside the jail","weight":2},{"item":"Explained the legal route to transfer him for treatment through the court or magistrate","weight":2},{"item":"Explained that treatment still requires the Act''s safeguards on consent and capacity","weight":2},{"item":"Advised against isolation as punishment and protection from other prisoners","weight":1},{"item":"Offered follow-up and liaison","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-435', 'MHCA: planning discharge with the patient and family', 'Mr Ravi, 35, from Hubballi, is ready for discharge after treatment for schizophrenia. Plan the discharge with him and his wife.', 420, '[{"item":"Involved Ravi and his wife in planning","weight":1},{"item":"Agreed follow-up close to home","weight":2},{"item":"Arranged free or low-cost medicine","weight":1},{"item":"Discussed early warning signs and a crisis plan","weight":2},{"item":"Discussed work or daily activity","weight":1},{"item":"Respected his privacy wishes","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-436', 'MHCA: how to appeal to the Review Board', 'Ms Farida, 39, from Hyderabad, is on supported admission and disagrees with it. She asks how she can challenge it. Explain.', 420, '[{"item":"Respected her right to challenge","weight":2},{"item":"Explained what the Mental Health Review Board is","weight":1},{"item":"Explained how to apply, including help from staff","weight":2},{"item":"Explained free legal aid","weight":1},{"item":"Explained that she will not be punished for appealing","weight":1},{"item":"Gave contact details in writing","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-437', 'Confidentiality: the family wants to know everything', 'Mr Kapoor, from Delhi, calls about his son Rohit, 24, who is in your clinic for depression. Rohit has asked that his parents not be told details. Mr Kapoor demands to know ''what is wrong with my son''. Respond.', 420, '[{"item":"Listened to his worry","weight":2},{"item":"Explained that Rohit is an adult and has a right to confidentiality","weight":2},{"item":"Did not confirm details without consent","weight":2},{"item":"Explained when information can be shared, such as serious risk","weight":1},{"item":"Offered to take his information and pass on his concern","weight":1},{"item":"Offered general information about supporting someone who is low","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-438', 'MHCA: a homeless man and the right to free care', 'Mr Dukhi, about 50, is homeless in Patna and has been brought by an NGO worker. The hospital clerk says he cannot be registered without an address or ID and must pay. Speak to the clerk.', 420, '[{"item":"Was polite and solution-focused","weight":1},{"item":"Explained the right to mental health care for all","weight":2},{"item":"Explained that homeless and poor people are entitled to free treatment at government services even without a card","weight":2},{"item":"Suggested using the NGO address or a hospital code","weight":1},{"item":"Arranged medicines and follow-up","weight":1},{"item":"Linked him to social welfare services","weight":1}]'::jsonb, '{"label":"Global legal and ethical practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-439', 'Capacity: a voluntary patient says no to an antipsychotic', 'Mr Sameer, 31, from Pune, was admitted as an independent patient with paranoid ideas. He now refuses risperidone. Assess whether he can refuse and discuss.', 420, '[{"item":"Explored his reasons for refusal","weight":2},{"item":"Assessed understanding, appreciation, weighing and communication","weight":2},{"item":"Concluded he has capacity to refuse","weight":2},{"item":"Respected the refusal","weight":2},{"item":"Offered alternatives that address his concerns","weight":1},{"item":"Documented and planned review","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-440', 'Fitness to stand trial: assessing an accused for the court', 'The court in Jabalpur has asked whether Mr Lakhan, 38, accused of assault, is fit to stand trial. Assess him.', 600, '[{"item":"Explained the purpose of the assessment and its limits of confidentiality","weight":2},{"item":"Assessed understanding of the charge","weight":2},{"item":"Assessed understanding of court roles: judge, lawyer, prosecutor","weight":2},{"item":"Assessed ability to instruct a lawyer and follow proceedings","weight":2},{"item":"Assessed the mental state and its effect on these abilities","weight":2},{"item":"Gave a clear opinion for the court in plain language","weight":1},{"item":"Recommended treatment and reassessment","weight":1}]'::jsonb, '{"label":"Global forensic assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-441', 'MHCA: leave of absence for a festival', 'Mrs Leela, 48, from Mysuru, on supported admission for depression, is improving. She asks to go home for two days for Dasara. Discuss leave with her and her husband.', 420, '[{"item":"Assessed current mood and risk","weight":2},{"item":"Explained that leave can be granted with conditions","weight":1},{"item":"Agreed conditions: who stays with her, medicines, return time","weight":2},{"item":"Gave a plan for what to do if things go wrong","weight":1},{"item":"Involved her husband","weight":1},{"item":"Documented the leave and conditions","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-442', 'Capacity: presenting and recording a capacity assessment', 'You assessed Mr Prakash, 66, from Nashik, who refuses amputation of a gangrenous foot. Present your capacity assessment to the surgeon and say how you will record it. Use the card.', 420, '[{"item":"Named the specific decision","weight":1},{"item":"Presented each part: understanding, retention, weighing, communication","weight":2},{"item":"Considered mental illness, delirium and coercion","weight":2},{"item":"Gave a clear conclusion: he has capacity to refuse","weight":2},{"item":"Answered the depression question with reasoning","weight":2},{"item":"Advised continuing discussion and palliative support","weight":1},{"item":"Described how to record the assessment","weight":1}]'::jsonb, '{"label":"Global case presentation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-443', 'Medicines: starting an SSRI for the first time', 'Ms Farzana, 27, a bank clerk in Hyderabad, has moderate depression. Her psychiatrist has prescribed sertraline. Explain the medicine to her before she leaves.', 420, '[{"item":"Checked what she already knew and feared about the medicine","weight":1},{"item":"Explained that benefit builds over two to four weeks, not days","weight":2},{"item":"Named common early side effects such as nausea, loose stools, headache and poor sleep, and that most settle","weight":2},{"item":"Corrected the belief that it is addictive and explained why it should not be stopped suddenly","weight":2},{"item":"Explained how long to continue after she feels well, usually at least six months","weight":2},{"item":"Told her to come back quickly if she feels more agitated or has thoughts of harming herself","weight":2},{"item":"Asked about alcohol and other medicines","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-444', 'Medicines: lamotrigine and the rash warning', 'Mr Varghese, 38, a schoolteacher in Thrissur, has bipolar II disorder with mostly depressive episodes. He is starting lamotrigine. Explain how to take it safely.', 420, '[{"item":"Explained the slow increase in dose over several weeks","weight":2},{"item":"Explained that the slow start lowers the risk of a serious skin reaction","weight":3},{"item":"Told him to stop and seek urgent help for any rash, mouth ulcers, fever or sore eyes","weight":3},{"item":"Asked about other medicines and recognised that valproate means a slower, lower schedule","weight":3},{"item":"Told him that if he misses several days he must not restart at the full dose","weight":2},{"item":"Checked understanding with teach-back","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-445', 'Medicines: carbamazepine and the blood test for a gene', 'Ms Lin, 30, from Siliguri, whose family is of Chinese origin, has bipolar disorder and did not tolerate lithium. Her psychiatrist suggests carbamazepine. Explain the tests and precautions.', 420, '[{"item":"Explained the HLA-B*1502 test and why it matters in people of East and South Asian ancestry","weight":3},{"item":"Explained the serious skin reaction the test helps to avoid","weight":2},{"item":"Explained the blood counts, liver tests and sodium checks","weight":2},{"item":"Explained that it makes the contraceptive pill less effective and advised a more reliable method","weight":3},{"item":"Explained the risk to a baby if she becomes pregnant and the need to plan pregnancy","weight":2},{"item":"Told her to report rash, fever, sore throat or unusual bruising","weight":2}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-446', 'Medicines: lithium and a painkiller for a sprained ankle', 'Mr Sandeep, 46, a courier in Indore, has taken lithium for eight years. He phones the clinic: for a week he has had loose stools, shaky hands and feels ''drunk''. He started diclofenac for an ankle sprain ten days ago. Take a focused history and advise him.', 420, '[{"item":"Asked about the new painkiller and other new medicines","weight":3},{"item":"Recognised that anti-inflammatory painkillers can raise lithium levels","weight":3},{"item":"Asked about fluid intake, sweating, vomiting and diarrhoea","weight":2},{"item":"Asked about warning signs of toxicity such as coarse tremor, unsteadiness, slurred speech and confusion","weight":2},{"item":"Advised urgent same-day lithium level and kidney tests and to hold the next dose as advised by the doctor","weight":3},{"item":"Suggested paracetamol as a safer painkiller and told him to tell every doctor and chemist he takes lithium","weight":2}]'::jsonb, '{"label":"Global medicine safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-447', 'Medicines: when to take the first buprenorphine dose', 'Mr Jaspreet, 29, from Amritsar, injects heroin and wants to start buprenorphine treatment today. He last used four hours ago. Explain how the first dose works.', 420, '[{"item":"Asked about the last opioid use, its type and amount","weight":2},{"item":"Explained why the first dose must wait until moderate withdrawal has started","weight":3},{"item":"Explained precipitated withdrawal in plain words","weight":2},{"item":"Explained that withdrawal will be measured with a short scale before dosing","weight":2},{"item":"Explained taking it under the tongue until it dissolves, not swallowing","weight":2},{"item":"Discussed overdose risk with alcohol or sleeping tablets and offered naloxone information","weight":2}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-448', 'Medicines: disulfiram, consent and the warning card', 'Mr Mahadev, 50, a shopkeeper in Belagavi, wants to stay off alcohol and is considering disulfiram. His wife says privately she would like to ''mix it in his food if he refuses''. Counsel him, then respond to her.', 420, '[{"item":"Explained that disulfiram causes a severe reaction with any alcohol","weight":2},{"item":"Explained that he must be sober for at least a day before the first dose","weight":2},{"item":"Explained hidden alcohol in cough syrups, sauces and some lotions, and that the risk lasts up to two weeks after stopping","weight":2},{"item":"Explained that it only works with his full knowledge and agreement","weight":2},{"item":"Refused covert use clearly and explained the danger to his life","weight":3},{"item":"Acknowledged the wife''s distress and offered support for her","weight":2}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-449', 'Medicines: naltrexone after detox and the overdose warning', 'Mr Irfan, 24, from Srinagar, has just finished opioid detoxification in a de-addiction centre. He has been opioid-free for ten days and wants naltrexone. Explain the medicine and the main danger after detox.', 420, '[{"item":"Checked that he had been opioid-free for at least seven to ten days","weight":2},{"item":"Explained that naltrexone blocks the effects of opioids","weight":2},{"item":"Explained that tolerance falls quickly after detox, so the old amount can kill","weight":3},{"item":"Warned that trying to overcome the block with large doses is very dangerous","weight":3},{"item":"Explained the liver test and pain relief planning for emergencies","weight":1},{"item":"Gave overdose advice, including naloxone and not using alone","weight":2}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-450', 'Medicines: coming off a sleeping tablet taken for nine years', 'Mrs Bhagyashree, 61, a retired clerk in Nagpur, has taken alprazolam every night for nine years. She now wants to stop. Plan the reduction with her.', 420, '[{"item":"Praised her decision and explored her reasons, including falls","weight":1},{"item":"Explained why sudden stopping is unsafe, including the risk of fits","weight":3},{"item":"Proposed a slow reduction, often by switching to a longer-acting medicine and lowering in small steps every one to two weeks","weight":3},{"item":"Explained likely withdrawal symptoms and that they pass","weight":2},{"item":"Offered sleep strategies to use during the reduction","weight":2},{"item":"Agreed regular reviews and that the pace can be slowed but not reversed","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-451', 'Medicines: an antidepressant for an older man who cannot eat or sleep', 'Mr Hariharan, 72, a retired railway guard in Madurai, has depression with poor sleep, poor appetite and weight loss. The consultant has chosen mirtazapine. Explain the choice and the precautions to him and his daughter.', 420, '[{"item":"Explained that it helps sleep and appetite, which suits his symptoms","weight":2},{"item":"Explained daytime drowsiness and weight gain as common effects","weight":2},{"item":"Addressed the falls risk at night with practical steps","weight":2},{"item":"Asked about his other medicines and health problems","weight":2},{"item":"Explained when benefit is expected and the follow-up plan","weight":1},{"item":"Asked about any thoughts of self-harm in him, or checked this had been done","weight":2}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-452', 'Medicines: choosing an antipsychotic together in a first episode', 'Mr Ankur, 21, a college footballer in Kolkata, has first-episode psychosis and agrees to treatment. Discuss two or three antipsychotic options and help him choose.', 600, '[{"item":"Asked what mattered most to him before offering options","weight":3},{"item":"Explained two or three options with their main side effects in plain words","weight":2},{"item":"Raised sexual side effects and prolactin sensitively","weight":2},{"item":"Linked the choice to his priorities on weight and sedation","weight":2},{"item":"Explained the monitoring of weight, sugar and lipids","weight":2},{"item":"Agreed a plan and a review, and checked understanding","weight":1}]'::jsonb, '{"label":"Global shared decision making competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-453', 'Rating scale: asking the nine PHQ questions in a busy clinic', 'Ms Pinki, 33, a domestic worker in Gurugram, cannot read well. Read the nine-question depression screen aloud, score it and explain what the score means.', 420, '[{"item":"Explained the purpose and the two-week time frame","weight":1},{"item":"Read each question clearly with the four answer choices","weight":1},{"item":"Scored each item from zero to three and totalled correctly","weight":2},{"item":"Recognised a total in the moderately severe range","weight":2},{"item":"Followed up the last item at once with a clear risk assessment","weight":3},{"item":"Explained that a questionnaire supports, but does not replace, a full assessment","weight":1}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-454', 'Rating scale: measuring obsessions and compulsions with a structured interview', 'Mr Nilesh, 26, a software tester in Pune, has contamination obsessions and washing. Rate the severity of his obsessions and compulsions using the five standard severity questions for each.', 420, '[{"item":"Explained the scale and checked his symptom list first","weight":1},{"item":"Asked about time occupied, interference, distress, resistance and control for obsessions","weight":3},{"item":"Asked the same five areas for compulsions","weight":3},{"item":"Used clear examples so he could rate himself honestly","weight":1},{"item":"Totalled the scores and placed them in a severity band","weight":2},{"item":"Explained how the score will be used to track progress","weight":1}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-455', 'Rating scale: a structured mania interview on the ward', 'Ms Roshni, 31, an event manager from Mumbai, was admitted four days ago with mania. Use the eleven-item mania rating scale to rate her today.', 420, '[{"item":"Rated elevated mood, energy, sexual interest and sleep from her account and the notes","weight":2},{"item":"Rated irritability, speech, thought content and disruptive behaviour, which carry double weight","weight":3},{"item":"Rated language and thought disorder from her speech in the interview","weight":2},{"item":"Rated appearance and insight","weight":1},{"item":"Used the last 48 hours and the observed interview as the time frame","weight":2},{"item":"Stayed calm, set gentle limits and kept the interview short","weight":1}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-456', 'Rating scale: ten alcohol questions in a primary care clinic', 'Mr Rakesh, 44, a bus conductor in Bhubaneswar, came for back pain. The clinic screens everyone for alcohol. Ask the ten AUDIT questions, score them and give feedback.', 420, '[{"item":"Explained why the questions are asked and that answers are confidential","weight":1},{"item":"Explained what one standard drink means","weight":2},{"item":"Asked all ten questions without judgement","weight":1},{"item":"Scored and placed him in a risk zone correctly","weight":2},{"item":"Gave brief feedback linking alcohol to his health","weight":2},{"item":"Offered advice to cut down and a follow-up","weight":1}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-457', 'Rating scale: a new mother answers yes to the last question', 'Mrs Kavitha, 26, six weeks after her first baby, is at a well-baby clinic in Mysuru. Use the ten-question postnatal depression scale with her, score it and act on the result.', 420, '[{"item":"Explained that the questions cover the past seven days","weight":1},{"item":"Let her choose her answers and scored them correctly","weight":1},{"item":"Noted a high total above the clinic cut-off","weight":2},{"item":"Responded to the self-harm item at once, whatever the total","weight":3},{"item":"Asked directly about thoughts of harming the baby, gently","weight":2},{"item":"Addressed her fear about the baby being taken away","weight":2},{"item":"Arranged same-day review and support","weight":2}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-458', 'Rating scale: rating depression severity with the seventeen-item interview', 'Mr Bijoy, 49, a jute mill supervisor from Howrah, is on an antidepressant for three weeks. Rate his depression today using the seventeen-item clinician-rated depression scale.', 420, '[{"item":"Explained the scale and the one-week time frame","weight":1},{"item":"Covered mood, guilt, suicide and the three sleep items","weight":2},{"item":"Covered work and interests, slowing, agitation and anxiety","weight":2},{"item":"Covered appetite, weight, physical symptoms, sexual interest and insight","weight":2},{"item":"Used observation as well as his answers for slowing","weight":1},{"item":"Totalled the score and compared it with the baseline","weight":2}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-459', 'Rating scale: positive symptoms in a structured psychosis interview', 'Mr Lokesh, 34, from Vijayawada, has schizophrenia and is in a medicine trial at your centre. Rate his positive symptoms over the past week using the seven positive items of the standard psychosis rating scale.', 600, '[{"item":"Explained the purpose and the one-week time frame","weight":1},{"item":"Rated delusions with conviction, distress and effect on behaviour","weight":2},{"item":"Rated conceptual disorganisation from his speech","weight":2},{"item":"Rated hallucinations by frequency and impact","weight":2},{"item":"Rated excitement, grandiosity, suspiciousness and hostility","weight":2},{"item":"Used informant or ward reports where available, and rated each item from one to seven","weight":2}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-460', 'Rating scale: what a worry score does not tell you', 'Ms Angela, 35, an air hostess based in Kochi, scores 14 on a seven-item anxiety screen. Explain the score and ask about what else might be going on.', 420, '[{"item":"Explained the score as moderate anxiety","weight":1},{"item":"Explained that a screen is not a diagnosis","weight":2},{"item":"Asked about physical causes such as thyroid symptoms","weight":3},{"item":"Asked about caffeine and other substances","weight":2},{"item":"Asked about low mood and safety","weight":1},{"item":"Planned a fuller assessment and blood tests","weight":1}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-461', 'Rating scale: structured suicide severity questions after a near miss', 'Mr Pradeep, 19, an engineering student in Kota, was brought in by his roommate who found him writing a goodbye letter. Use the structured suicide severity questions to assess him.', 420, '[{"item":"Asked about the wish to be dead","weight":2},{"item":"Asked about active thoughts of ending his life","weight":2},{"item":"Asked about method, intent and plan step by step","weight":3},{"item":"Asked about any preparatory acts, such as the letter","weight":2},{"item":"Asked about past attempts and recent behaviour","weight":2},{"item":"Summarised the level of risk and agreed an immediate safety plan","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-462', 'Medicines: a pregnant woman who wants to stop sertraline today', 'Ms Shreya, 30, an architect in Bengaluru, is eight weeks pregnant. She has had three episodes of severe depression and is well on sertraline. Her mother-in-law has told her the tablets will ''harm the baby''. She wants to stop today. Discuss.', 600, '[{"item":"Explored her fears and her past episodes","weight":2},{"item":"Explained the high risk of relapse if she stops, given three severe episodes","weight":3},{"item":"Explained the known risks of sertraline in pregnancy honestly, including that most studied risks are small","weight":3},{"item":"Explained that untreated depression also carries risks for her and the baby","weight":2},{"item":"Explained that sudden stopping causes discontinuation symptoms","weight":1},{"item":"Supported her to make an informed decision and planned close follow-up with the obstetrician","weight":2}]'::jsonb, '{"label":"Global shared decision making competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-463', 'Medicines: a stimulant for an adult with attention problems', 'Mr Abhishek, 28, a software engineer in Noida, has been diagnosed with ADHD as an adult. He is starting methylphenidate. Explain the medicine and the checks.', 420, '[{"item":"Asked about heart history, family history and blood pressure","weight":3},{"item":"Explained benefits and how fast it works","weight":1},{"item":"Explained common side effects such as poor appetite, sleep problems and raised heart rate","weight":2},{"item":"Advised cutting down caffeine","weight":1},{"item":"Explained the misuse risk and that tablets must never be shared","weight":2},{"item":"Explained that medicine works best alongside practical skills for planning and time","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-464', 'Medicines: stopping an antipsychotic after a year of recovery', 'Ms Ritu, 24, an MBA student in Chandigarh, recovered fully from a first psychotic episode fourteen months ago on risperidone. She wants to stop the medicine before her placement interviews. Discuss.', 600, '[{"item":"Respected her wish and explored her reasons, including side effects","weight":2},{"item":"Gave honest information that relapse is much more likely after stopping, even after full recovery","weight":3},{"item":"Offered options such as a lower dose or a switch for side effects","weight":2},{"item":"If she chooses to stop, planned a slow taper over months rather than sudden stopping","weight":3},{"item":"Agreed early warning signs and a relapse plan with her and, with consent, her family","weight":2},{"item":"Planned closer follow-up during and after the reduction","weight":1}]'::jsonb, '{"label":"Global shared decision making competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-465', 'Medicines: falls and confusion after a new antidepressant at eighty', 'Mrs Rukmini, 80, from Varanasi, started escitalopram two weeks ago. Her son says she has become confused, sleepy and fell yesterday. She also takes a water tablet for blood pressure. Take a history from the son and advise.', 420, '[{"item":"Took a clear timeline of the change after starting the medicine","weight":2},{"item":"Asked about headache, nausea, sleepiness and falls","weight":2},{"item":"Recognised low sodium as a likely cause and named the risk factors: age, SSRI and a water tablet","weight":3},{"item":"Asked about fluid intake","weight":1},{"item":"Arranged an urgent sodium level and physical review","weight":3},{"item":"Explained that the antidepressant may need to stop or change, and that delirium can be reversed","weight":1}]'::jsonb, '{"label":"Global medicine safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-466', 'Medicines: a newly married man and sexual side effects', 'Mr Faisal, 31, a pharmacist in Lucknow, has taken paroxetine for panic disorder for six months. He got married three months ago and has quietly reduced his dose. Explore and advise.', 420, '[{"item":"Asked about sexual side effects directly and normalised them","weight":2},{"item":"Explored the effect on his marriage","weight":1},{"item":"Recognised discontinuation symptoms from cutting the dose","weight":2},{"item":"Advised against sudden changes on his own","weight":2},{"item":"Discussed options: dose timing, lower dose, or a switch to a medicine with fewer sexual effects","weight":2},{"item":"Offered a joint session with his wife if he wishes","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-467', 'Medicines: thirsty all day on lithium', 'Mrs Aparna, 52, a lecturer in Guwahati, has taken lithium for fifteen years. She says she is passing urine every hour and drinks four litres a day. Assess and advise.', 420, '[{"item":"Took a history of thirst and urine volume, including at night","weight":2},{"item":"Asked about symptoms of an underactive thyroid","weight":2},{"item":"Asked about the timing of her last lithium level, kidney and thyroid tests","weight":2},{"item":"Explained that lithium can affect the kidney''s ability to concentrate urine","weight":2},{"item":"Arranged lithium level, kidney function, thyroid and calcium tests","weight":2},{"item":"Reassured her that any change would be planned with her, not sudden","weight":2}]'::jsonb, '{"label":"Global medicine safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-468', 'Medicines: clozapine and a man who has stopped smoking', 'Mr Debashish, 40, from Durgapur, is stable on clozapine 400 mg a day. He stopped smoking ten days ago after a chest infection. His sister says he is very drowsy, drooling and had a jerk of the arm yesterday. Take a history and advise the ward doctor.', 600, '[{"item":"Recognised that stopping smoking raises clozapine levels","weight":3},{"item":"Recognised that ciprofloxacin can raise clozapine levels too","weight":3},{"item":"Linked drowsiness, drooling and the jerk to a high level and seizure risk","weight":2},{"item":"Advised an urgent clozapine level and holding or reducing the dose","weight":2},{"item":"Advised checking for constipation, pulse, blood pressure and blood counts","weight":1},{"item":"Advised planning dose changes whenever smoking habits change","weight":1}]'::jsonb, '{"label":"Global medicine safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-469', 'Medicines: a pharmacist calls about fluoxetine and tramadol', 'A pharmacist in Coimbatore calls. Mrs Selvi, 45, takes fluoxetine 40 mg from your clinic. An orthopaedic surgeon has prescribed tramadol for knee pain. The pharmacist asks for advice.', 420, '[{"item":"Thanked the pharmacist and checked the doses","weight":1},{"item":"Explained the risk of serotonin toxicity with the combination","weight":3},{"item":"Explained the raised seizure risk with tramadol","weight":2},{"item":"Explained that fluoxetine can make tramadol a weaker painkiller","weight":2},{"item":"Suggested a safer painkiller and agreed to contact the surgeon","weight":2},{"item":"Advised which warning signs she should look for if it is used","weight":1}]'::jsonb, '{"label":"Global medicine safety competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-470', 'Rating scale: fourteen questions about anxiety and its body signs', 'Mr Ghanshyam, 55, a cloth merchant in Surat, has generalised anxiety. Rate his anxiety using the fourteen-item clinician-rated anxiety scale.', 420, '[{"item":"Explained the scale and the time frame","weight":1},{"item":"Rated anxious mood, tension, fears and sleep","weight":2},{"item":"Rated concentration and depressed mood","weight":1},{"item":"Rated the body systems: muscles, senses, heart, breathing, gut, urinary and autonomic signs","weight":2},{"item":"Rated behaviour seen at interview","weight":2},{"item":"Totalled the score out of 56 and explained the meaning","weight":2}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-471', 'Medicines: a pill box for a man who forgets', 'Mr Venkatesh, 45, from Tirupati, has schizophrenia and lives with his elderly mother. His tablets are often left in the strip. Talk to him about taking his medicine.', 420, '[{"item":"Asked about missed doses in a non-blaming way","weight":2},{"item":"Explored the reasons: forgetting, routine, side effects and beliefs","weight":2},{"item":"Suggested simplifying to once-daily dosing if possible","weight":2},{"item":"Suggested a weekly pill box and linking the dose to a daily habit","weight":1},{"item":"Involved his mother with his consent","weight":1},{"item":"Agreed a plan and a follow-up","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-472', 'Rating scales: present the scores and what they do and do not show', 'You are reviewing Ms Nazneen, 37, from Bhopal, after eight weeks of treatment for depression. Her self-rated nine-question score fell from 21 to 9, but the clinician-rated seventeen-item score fell only from 24 to 18. Present the scores to the examiner and explain what you would do.', 600, '[{"item":"Presented both scores with their ranges and time frames","weight":1},{"item":"Noted that the self-rating suggests response but the clinician rating does not","weight":2},{"item":"Offered reasons for disagreement, such as differences in items, physical symptoms or wanting to please","weight":3},{"item":"Stated that remission needs a low score on a validated scale plus clinical judgement","weight":2},{"item":"Planned a full clinical review, including risk and physical causes","weight":2},{"item":"Discussed the limits of scales and the need for functional measures","weight":1}]'::jsonb, '{"label":"Global clinical reasoning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-473', 'Therapy: solving one problem at a time with a farmer''s wife', 'Mrs Gangamma, 42, from a village near Raichur, has mild depression. Her main worry is a bank loan instalment due next month after a poor harvest. Use problem-solving steps to work on this one problem with her.', 420, '[{"item":"Helped her state the problem clearly and specifically","weight":2},{"item":"Set a realistic goal with her","weight":2},{"item":"Brainstormed several options without judging them","weight":2},{"item":"Weighed the pros and cons of each option with her","weight":2},{"item":"Helped her choose one option and plan concrete steps","weight":2},{"item":"Agreed to review how it went at the next session","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-474', 'Therapy: teaching muscle relaxation to a tense student', 'Ms Harini, 20, a BCom student in Chennai, has tension headaches and anxiety before exams. Teach her progressive muscle relaxation.', 420, '[{"item":"Explained the idea of tensing and then releasing muscle groups","weight":1},{"item":"Asked about injuries or pain before starting","weight":2},{"item":"Guided her through tensing for about five seconds and releasing for longer","weight":2},{"item":"Worked through muscle groups in order with calm pacing","weight":2},{"item":"Asked her to notice the contrast between tension and relaxation","weight":1},{"item":"Agreed a daily practice plan and how to rate tension before and after","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-475', 'Therapy: building a ladder for exposure and response prevention', 'Mr Yusuf, 30, a tailor in Hyderabad, has contamination OCD. He washes his hands about forty times a day. Build an exposure hierarchy with him and explain the first task.', 420, '[{"item":"Explained how exposure and not doing the ritual works","weight":2},{"item":"Listed feared situations and rated each from zero to a hundred","weight":2},{"item":"Ordered them into a ladder","weight":1},{"item":"Agreed a first step in the moderate range, not too easy or too hard","weight":2},{"item":"Explained response prevention clearly, including no washing after","weight":3},{"item":"Planned daily practice and a record of anxiety","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-476', 'Therapy: cooling down a crisis with a quick skill', 'Ms Tanvi, 23, a graphic designer in Pune, has emotionally unstable personality traits. She arrives at the clinic very distressed after a fight with her boyfriend and says she feels ''about to explode''. Help her through the next few minutes using a distress tolerance skill.', 420, '[{"item":"Stayed calm, validated her distress and checked immediate safety","weight":2},{"item":"Asked clearly about urges to self-harm","weight":3},{"item":"Offered a skill such as cold water on the face, paced breathing or brief intense exercise","weight":2},{"item":"Guided her through the skill in the room","weight":2},{"item":"Re-rated her distress after the skill","weight":1},{"item":"Agreed a short plan for the rest of the day","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-477', 'Therapy: agreeing the frame with a client who has been let down before', 'Ms Ayesha, 26, from Delhi, has borderline personality disorder. She has started and stopped therapy with three therapists. This is your first session. Agree a therapy contract.', 600, '[{"item":"Explored her past experiences of therapy without blame","weight":2},{"item":"Agreed the length, frequency and goals of sessions","weight":2},{"item":"Set clear limits on contact between sessions and explained the crisis plan","weight":3},{"item":"Agreed what happens after missed sessions or self-harm","weight":2},{"item":"Responded to her fear of abandonment with warmth and honesty","weight":2},{"item":"Checked her understanding and agreement","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-478', 'Therapy: when a client says therapy is useless', 'Mr Rohan, 35, a bank manager in Mumbai, is in his sixth session of CBT for depression. He arrives late and says, ''This is a waste of money. These worksheets are childish.'' Respond.', 420, '[{"item":"Stayed non-defensive and thanked him for saying it","weight":2},{"item":"Explored what felt unhelpful","weight":2},{"item":"Acknowledged own contribution honestly","weight":3},{"item":"Linked his reaction to the session content with care","weight":1},{"item":"Agreed together how to change the approach","weight":2},{"item":"Checked how he felt by the end","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-479', 'Therapy: ending well with a client who wants to continue', 'Mrs Lalitha, 58, a homemaker in Bengaluru, has finished sixteen sessions of therapy for depression and is now well. At the last session she says, ''Please do not stop, I will fall apart.'' Respond.', 420, '[{"item":"Validated her feelings about ending","weight":2},{"item":"Reviewed her progress and the skills she has learned","weight":2},{"item":"Highlighted her own supports and achievements","weight":2},{"item":"Kept the boundary on personal contact kindly","weight":2},{"item":"Agreed a relapse prevention plan and a booster session","weight":2},{"item":"Explained how to return to services if needed","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-480', 'Therapy: questioning the thought ''I am a failure''', 'Mr Sunil, 29, a sales executive in Jaipur, missed his monthly target and says, ''I am a complete failure.'' Use guided questions to help him look at the thought.', 420, '[{"item":"Identified the thought and rated how strongly he believed it","weight":1},{"item":"Asked for evidence for and against the thought","weight":2},{"item":"Used open questions rather than arguing","weight":2},{"item":"Helped him form a more balanced thought","weight":2},{"item":"Re-rated his belief in the original thought","weight":1},{"item":"Agreed a small task to test the new thought","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-481', 'Therapy: less time in bed for long-standing insomnia', 'Mr Jagdish, 56, a retired bank officer in Ludhiana, has insomnia for three years. His two-week diary shows he spends nine hours in bed but sleeps about five and a half. Explain sleep restriction and set his first sleep window.', 420, '[{"item":"Worked out sleep efficiency from the diary","weight":2},{"item":"Explained why less time in bed builds stronger sleep","weight":2},{"item":"Set a time in bed close to his actual sleep time, not below about five and a half hours","weight":2},{"item":"Fixed the wake time every day and stopped naps","weight":2},{"item":"Warned about daytime sleepiness, especially when driving","weight":2},{"item":"Explained how the window will be widened as sleep improves","weight":1}]'::jsonb, '{"label":"Global therapeutic skill competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-482', 'Sleep: the teenager who cannot get up for school', 'Ishaan, 16, from Ahmedabad, is brought by his mother because he ''cannot wake up'' for school. Take a sleep history.', 420, '[{"item":"Asked about bedtime, sleep onset and wake times on school days and holidays","weight":3},{"item":"Asked about how he feels when allowed to sleep his own hours","weight":2},{"item":"Asked about screens and light at night","weight":1},{"item":"Screened for low mood, substance use and snoring","weight":2},{"item":"Recognised a delayed sleep timing pattern","weight":1},{"item":"Suggested morning light, fixed wake time and earlier screen-off","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-483', 'Sleep: restless legs in the last months of pregnancy', 'Mrs Saba, 29, from Bhopal, is seven months pregnant and cannot sleep because of ''strange feelings'' in her legs at night. Her obstetrician has asked for advice. Take a history.', 420, '[{"item":"Asked about the urge to move the legs and the sensations","weight":2},{"item":"Asked whether it is worse at rest and in the evening","weight":2},{"item":"Asked whether movement relieves it","weight":2},{"item":"Asked about iron, anaemia and diet","weight":2},{"item":"Advised checking iron stores and restarting iron in a tolerable form","weight":2},{"item":"Reassured that it often improves after delivery and offered sleep advice","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-484', 'Perinatal: can I breastfeed on my antidepressant?', 'Mrs Priya, 31, from Kochi, had postnatal depression and is well on sertraline. Her baby is two months old and healthy. Her family says she must stop breastfeeding or stop the tablet. Advise her.', 420, '[{"item":"Explored her wishes and fears","weight":2},{"item":"Explained that sertraline passes into breast milk only in small amounts","weight":2},{"item":"Explained the risk of relapse if she stops","weight":2},{"item":"Explained what to watch for in the baby, such as poor feeding or unusual sleepiness","weight":2},{"item":"Supported her to continue both if she chooses","weight":2},{"item":"Offered to speak with the family, with her consent","weight":1}]'::jsonb, '{"label":"Global medicine counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-485', 'Perinatal: the day after a stillbirth', 'Mrs Nandita, 27, and her husband Sourav are on the maternity ward in Kolkata the day after their daughter was stillborn at 36 weeks. The team has asked you to see them. Talk with them.', 420, '[{"item":"Offered condolences and used the baby''s name if they have one","weight":2},{"item":"Listened more than talked and allowed silence","weight":2},{"item":"Gently addressed self-blame without false promises","weight":2},{"item":"Offered choices such as holding the baby, photographs and keepsakes","weight":2},{"item":"Acknowledged family and cultural wishes respectfully","weight":1},{"item":"Explained follow-up, including support for grief and the next pregnancy","weight":2}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-486', 'Perinatal: planning a second pregnancy after postpartum psychosis', 'Mrs Meghna, 32, from Nagpur, had postpartum psychosis after her first baby three years ago and recovered fully. She has had no episodes since and takes no medicine. She and her husband want another child. Discuss planning.', 600, '[{"item":"Gave honest information that the risk of another episode is high, around half","weight":3},{"item":"Discussed options, including preventive medicine started at or after delivery","weight":2},{"item":"Planned with the perinatal and obstetric teams in writing","weight":2},{"item":"Discussed protecting sleep after the birth, including night feeds","weight":2},{"item":"Agreed early warning signs and a crisis plan with the family","weight":2},{"item":"Discussed breastfeeding in relation to any medicine","weight":1}]'::jsonb, '{"label":"Global clinical planning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-487', 'Sexual health: too quick, and afraid to tell anyone', 'Mr Ravi, 26, a software developer in Hyderabad, married four months ago. He says he ''finishes too quickly''. Take a history.', 420, '[{"item":"Set the scene, reassured confidentiality and asked permission","weight":2},{"item":"Clarified timing, how often and since when","weight":2},{"item":"Asked whether it was lifelong or recent","weight":2},{"item":"Asked about erections, anxiety and relationship","weight":2},{"item":"Asked about beliefs, internet use and remedies tried","weight":1},{"item":"Explained that it is common and treatable, with options","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-488', 'Sexual health: low desire, with a husband who wants a quick fix', 'Mrs Anupama, 34, a schoolteacher in Kozhikode, is brought by her husband, who says she has ''no interest'' in sex for a year and wants ''a tablet''. Take a history, including time with her alone.', 600, '[{"item":"Asked to see her alone for part of the consultation","weight":3},{"item":"Asked about mood, sleep and tiredness","weight":2},{"item":"Asked about pain during intercourse and delivery history","weight":2},{"item":"Asked about safety and consent in the relationship","weight":3},{"item":"Asked about medicines, contraception and physical health","weight":1},{"item":"Explained that there may be several causes and planned assessment and support","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-489', 'Gender: a transgender woman asks for help with the next steps', 'Ms Sana, 24, a transgender woman from Lucknow, has come for an assessment before starting hormone treatment and asks about her rights. Talk with her.', 420, '[{"item":"Used her name and pronouns and asked what she would like","weight":2},{"item":"Explained that being transgender is not a mental illness","weight":3},{"item":"Explored her goals, supports and experiences of stigma","weight":2},{"item":"Screened for low mood, anxiety and safety","weight":2},{"item":"Explained the role of the assessment in supporting informed decisions about hormones","weight":1},{"item":"Gave information on legal recognition and support services","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-490', 'Personality: passed over for promotion and furious', 'Mr Kunal, 39, a senior manager in Gurugram, was passed over for promotion. He has come at his wife''s insistence. Take a history.', 420, '[{"item":"Allowed him to tell his story without challenging too early","weight":2},{"item":"Explored long-standing patterns in work and relationships","weight":2},{"item":"Explored the hurt and shame beneath the anger","weight":2},{"item":"Asked about alcohol and sleep","weight":1},{"item":"Asked clearly about suicidal thoughts","weight":3},{"item":"Kept a respectful, non-competitive stance","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-491', 'Personality: asking a sister about how he has always been', 'Mr Pratap, 33, from Jodhpur, has been admitted after a fight. The team wonders about antisocial personality disorder. Take an informant history from his older sister.', 420, '[{"item":"Explained the purpose and confidentiality limits","weight":1},{"item":"Asked about childhood behaviour before fifteen","weight":3},{"item":"Asked about patterns across work, relationships and the law","weight":2},{"item":"Asked about remorse, impulsivity and lying","weight":2},{"item":"Asked about alcohol and drugs","weight":1},{"item":"Asked about his own childhood experiences and her wellbeing","weight":1}]'::jsonb, '{"label":"Global history taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-492', 'Professional: teaching a medical student to ask about suicide', 'A final-year MBBS student, Ms Simran, tells you she is ''too scared'' to ask patients about suicide because it might ''put the idea in their head''. Teach her how to ask.', 420, '[{"item":"Explored her current knowledge and worries","weight":1},{"item":"Corrected the myth that asking puts the idea in someone''s head","weight":3},{"item":"Gave a clear step-by-step approach with example questions","weight":2},{"item":"Let her practise and gave specific feedback","weight":2},{"item":"Explained what to do with a positive answer","weight":2},{"item":"Checked her confidence at the end","weight":1}]'::jsonb, '{"label":"Global teaching competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-493', 'Professional: a colleague asks you to write her a prescription', 'Dr Neha, a junior resident in your department in Chandigarh, asks you in the corridor to ''just write'' zolpidem for her because she cannot sleep before night duty. Respond.', 420, '[{"item":"Declined clearly and kindly","weight":2},{"item":"Explained why informal prescribing for colleagues is unsafe","weight":2},{"item":"Showed concern and asked how she is","weight":2},{"item":"Asked gently about mood and safety","weight":2},{"item":"Encouraged her to see her own doctor or a confidential staff service","weight":2},{"item":"Offered practical help such as covering a shift if possible","weight":1}]'::jsonb, '{"label":"Global professionalism competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-494', 'Professional: assessing disability for a certificate', 'Mr Somnath, 46, from Patna, has had schizophrenia for twelve years. His brother has brought him for a disability certificate. Explain the assessment and rate the main areas.', 420, '[{"item":"Explained the purpose and the scale that rates disability in four areas","weight":2},{"item":"Asked about self-care","weight":1},{"item":"Asked about relationships and social activities","weight":1},{"item":"Asked about communication and understanding","weight":1},{"item":"Asked about work, study or housework, and how long he has been ill","weight":2},{"item":"Explained that a medical board certifies, and refused any improper request firmly","weight":3}]'::jsonb, '{"label":"Global structured assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-495', 'Professional: a patient posts about you online', 'Ms Diksha, 22, a patient you see for depression in Indore, has posted on Instagram that you are ''the best doctor ever'' with a photo of you in the clinic. She has also sent you a friend request. Discuss this with her at the next appointment.', 420, '[{"item":"Thanked her for the kind intention","weight":1},{"item":"Explained why you will not accept friend requests from patients","weight":2},{"item":"Raised the photo and asked her to remove it, explaining why","weight":2},{"item":"Discussed her own privacy now that followers know about her treatment","weight":2},{"item":"Explored her feelings about the boundary","weight":2},{"item":"Did not respond to the post publicly","weight":1}]'::jsonb, '{"label":"Global professionalism competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-496', 'Culture: ''weakness of the mind'', explained to the family elder', 'Mr Jagga, 35, a farmer near Bathinda, has depression. His grandfather, the family elder, says it is ''weakness of the mind'' and a ''real man'' would work it off. Explain depression to the grandfather, with the patient''s consent.', 420, '[{"item":"Greeted him respectfully and asked for his view first","weight":2},{"item":"Acknowledged his life experience and strength","weight":1},{"item":"Explained depression as an illness that affects sleep, appetite, energy and thinking","weight":2},{"item":"Used the changes he had noticed in his grandson","weight":2},{"item":"Explained that it is not weakness and can be treated","weight":2},{"item":"Asked him to help in a specific way","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-497', 'Psychoeducation: writing early warning signs with a family', 'Mr Arun, 28, from Mangaluru, is recovering from his second episode of schizophrenia. He and his mother want to stop it happening again. Help them write his early warning signs and an action plan.', 420, '[{"item":"Asked them both what happened in the weeks before each episode","weight":2},{"item":"Ordered the signs from earliest to latest","weight":2},{"item":"Agreed what Arun and his mother will do at each stage","weight":2},{"item":"Included who to call and the clinic number","weight":1},{"item":"Discussed what to do if he refuses help, respecting his rights","weight":2},{"item":"Gave them a written copy","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-498', 'Intellectual disability: what is the behaviour telling us?', 'Mr Bunty, 24, has moderate intellectual disability and lives in a group home in Pune. Staff say he has started hitting his head on the wall. Take a history from his key worker to understand the behaviour.', 420, '[{"item":"Asked what happens before, during and after the behaviour","weight":3},{"item":"Asked about timing, setting and people present","weight":2},{"item":"Considered physical pain and health causes, including teeth","weight":3},{"item":"Asked about recent changes in routine or staff","weight":1},{"item":"Thought about what the behaviour achieves for him","weight":2},{"item":"Suggested a plan that addresses the cause, not just the behaviour","weight":1}]'::jsonb, '{"label":"Global clinical reasoning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-499', 'Professional: a phone referral to a de-addiction centre', 'You are the psychiatry resident in a district hospital in Mandi. Mr Bhupesh, 37, has alcohol dependence and wants admission for detox. Phone the de-addiction centre and make the referral.', 420, '[{"item":"Introduced self, role and reason for the call","weight":1},{"item":"Gave a clear summary of the patient and the request","weight":2},{"item":"Gave the drinking history, last drink and any past withdrawal fits or delirium","weight":3},{"item":"Gave physical health, liver tests and risk information","weight":2},{"item":"Confirmed his willingness and consent","weight":1},{"item":"Agreed the plan, time of transfer and documented the call","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-500', 'Long case: present a full assessment and plan to the examiner', 'You have spent forty minutes with Mrs Revathi, 45, a schoolteacher from Salem, who has had low mood, poor sleep and weight loss for four months, with hearing her late mother''s voice calling her name at night, and recent hypothyroidism on treatment. Present the case to the examiner, with your formulation and plan.', 900, '[{"item":"Presented identifying details, complaint and history in a logical order","weight":2},{"item":"Presented a focused mental state, including the nature of the voice","weight":2},{"item":"Gave a 5P formulation linking biological, psychological and social factors","weight":2},{"item":"Gave a reasoned differential, including depression with psychotic features, grief and thyroid-related mood change","weight":3},{"item":"Presented a risk assessment","weight":2},{"item":"Gave a clear plan for investigations, treatment and follow-up","weight":2}]'::jsonb, '{"label":"Global clinical reasoning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-1', 'Ravi: ''the heaviness'' (somatic depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"f1","text":"Body ache, heaviness, poor sleep, 6kg weight loss","bucket":"presenting"},{"id":"f2","text":"Promotion added night shifts 8 months ago","bucket":"precipitating"},{"id":"f3","text":"Father had a ''nervous breakdown'' in his 40s","bucket":"predisposing"},{"id":"f4","text":"Avoids talking about feelings; keeps working while exhausted","bucket":"perpetuating"},{"id":"f5","text":"Supportive wife who ''keeps asking''","bucket":"protective"},{"id":"f6","text":"GP visits for ''gas'' and ''weakness'' without improvement","bucket":"perpetuating"},{"id":"f7","text":"Core belief: ''I am failing my family''","bucket":"predisposing"},{"id":"f8","text":"The weather is unusually hot this summer","bucket":"distractor"},{"id":"f9","text":"Employee has a steady job and a roof","bucket":"protective"},{"id":"f10","text":"Two-year help-seeking delay before any mental-health contact","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi presents with somatic depression: 8 months of body ache, broken sleep and weight loss following a promotion that added night shifts (precipitant). A family history of paternal ''nervous breakdown'' and a core belief of failing his family (predisposing) shape his coping: he avoids disclosing distress and keeps working through exhaustion (perpetuating), and a two-year help-seeking delay reinforced it. Protective factors include a supportive wife and stable employment. The formulation explains why he presents somatically: the heaviness is the only acceptable language his belief system permits for distress.","hint":"Somatic depression in a man who won''t talk about feelings","tags":{"topic":"depression","difficulty":2,"objective":"Link a somatic presentation of depression to its 5 Ps","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Moderate depressive episode with somatic presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-2', 'Meera: the exam that never ends (panic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"m1","text":"Sudden attacks of racing heart, breathlessness and fear of dying, 3 to 4 times a week","bucket":"presenting"},{"id":"m2","text":"Now avoids the coaching centre and travels only with her mother","bucket":"presenting"},{"id":"m3","text":"First attack in the exam hall, two months before her second NEET attempt","bucket":"precipitating"},{"id":"m4","text":"Mother has ''BP and tension'' and checks her own pulse often","bucket":"predisposing"},{"id":"m5","text":"Anxious, perfectionistic temperament since childhood","bucket":"predisposing"},{"id":"m6","text":"Three ECGs and an echo, all normal; each one calms her for a day only","bucket":"perpetuating"},{"id":"m7","text":"Carries a water bottle and sits near doors ''just in case'' (safety behaviours)","bucket":"perpetuating"},{"id":"m8","text":"Reads about heart attacks in young women late at night","bucket":"perpetuating"},{"id":"m9","text":"Close friend who has offered to sit with her in class","bucket":"protective"},{"id":"m10","text":"Bright, motivated, and asked for help herself","bucket":"protective"},{"id":"m11","text":"Her blood group is B positive","bucket":"distractor"},{"id":"m12","text":"The family recently bought a new scooter","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meera, 19, presents with panic disorder with growing agoraphobic avoidance: frequent surges of palpitations, breathlessness and fear of dying, and she now avoids the coaching centre. An anxious, perfectionistic temperament and a mother who models health vigilance (predisposing) set the stage; the first attack came in the exam hall during a high-stakes repeat attempt (precipitating). The cycle is kept going by repeated reassurance-seeking through normal cardiac tests, safety behaviours that stop her learning the attacks are harmless, and night-time symptom searching (perpetuating). Her own help-seeking, intelligence and a supportive friend are strengths to build exposure work on (protective).","hint":"Panic attacks before NEET, a heart she is sure is failing","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how safety behaviours and reassurance keep panic going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Panic disorder with early agoraphobic avoidance"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-3', 'Arjun: the voices after the hostel (first-episode psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"a1","text":"Hears two men discussing him; believes classmates put a chip in his laptop","bucket":"presenting"},{"id":"a2","text":"Stopped attending college, poor sleep, speaks less, 4 months","bucket":"presenting"},{"id":"a3","text":"Paternal uncle with schizophrenia","bucket":"predisposing"},{"id":"a4","text":"Daily cannabis use since second year","bucket":"predisposing"},{"id":"a5","text":"Moved to a distant hostel and failed two subjects last semester","bucket":"precipitating"},{"id":"a6","text":"Heavier cannabis use after the exam results","bucket":"precipitating"},{"id":"a7","text":"Family took him to a faith healer first; 3-month delay before a psychiatrist","bucket":"perpetuating"},{"id":"a8","text":"Ongoing cannabis use and no fixed sleep routine","bucket":"perpetuating"},{"id":"a9","text":"Believes medicine is ''for mad people'' and skips doses","bucket":"perpetuating"},{"id":"a10","text":"Parents are worried but involved and come to every visit","bucket":"protective"},{"id":"a11","text":"Good school record and friends from before college","bucket":"protective"},{"id":"a12","text":"He prefers Android phones","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 21, presents with a first episode of psychosis: auditory hallucinations in the third person, a persecutory delusion about a chip in his laptop, and four months of withdrawal, poor sleep and dropping out. A family history of schizophrenia and regular adolescent cannabis use (predisposing) raised his vulnerability; moving away from home, academic failure and heavier cannabis use after the results (precipitating) came just before onset. The duration of untreated psychosis was lengthened by the faith-healer route, and continuing cannabis, irregular sleep and his belief that medicine is for ''mad people'' (perpetuating) risk relapse. Engaged parents and a good premorbid level of functioning (protective) predict a better outcome and make early family work possible.","hint":"A 21-year-old engineering student who stopped attending","tags":{"topic":"psychosis","difficulty":3,"objective":"Separate vulnerability, triggers and relapse drivers in first-episode psychosis","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"psychosis","diagnosis":"First-episode psychosis (schizophreniform picture)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-4', 'Sunita: ''I just want to sleep'' (postpartum depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"s1","text":"Low mood, crying, no interest in the baby''s care, poor appetite for 6 weeks","bucket":"presenting"},{"id":"s2","text":"Thoughts that the baby would be better off with her mother-in-law","bucket":"presenting"},{"id":"s3","text":"Depressive episode in college that settled without treatment","bucket":"predisposing"},{"id":"s4","text":"Emergency caesarean and a 5-day NICU stay for the baby","bucket":"precipitating"},{"id":"s5","text":"Criticism from in-laws after the baby was a girl","bucket":"precipitating"},{"id":"s6","text":"Husband works away; night feeds are hers alone, sleep 3 to 4 hours","bucket":"perpetuating"},{"id":"s7","text":"Feels guilty and hides her tears so she is ''not a bad mother''","bucket":"perpetuating"},{"id":"s8","text":"Her own mother calls every day and wants to visit","bucket":"protective"},{"id":"s9","text":"Breastfeeding well; the baby is gaining weight","bucket":"protective"},{"id":"s10","text":"The house is being painted","bucket":"distractor"},{"id":"s11","text":"She studied commerce","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunita, 27, presents ten weeks postpartum with a moderate depressive episode: low mood, tearfulness, poor appetite, loss of interest in caring for her baby and thoughts that the baby would be better off with others, which need a careful risk assessment. A previous untreated depressive episode (predisposing) left her vulnerable; a traumatic emergency caesarean with a NICU stay and criticism over the baby''s sex (precipitating) came just before onset. Severe sleep loss with no one to share night feeds and guilt-driven concealment of her distress (perpetuating) keep it going. Her mother''s daily support and the fact that feeding and the baby''s growth are going well (protective) are footholds for treatment and for practical help at night.","hint":"A new mother, 10 weeks after a caesarean, in a joint family","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate postpartum depression with risk to self and baby in view","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"depression","diagnosis":"Moderate depressive episode, postpartum onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-5', 'Mr Khan: the drink after the shop shut (alcohol dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"k1","text":"Drinks a quarter bottle of whisky daily, morning tremor relieved by a drink","bucket":"presenting"},{"id":"k2","text":"First withdrawal seizure last week after 2 days without alcohol","bucket":"presenting"},{"id":"k3","text":"Father drank heavily and died of liver disease","bucket":"predisposing"},{"id":"k4","text":"Started drinking with friends at 18; drinking was the way to unwind","bucket":"predisposing"},{"id":"k5","text":"Shop closed during a long market slump 2 years ago; drinking doubled","bucket":"precipitating"},{"id":"k6","text":"Evenings at the same friend''s place where everyone drinks","bucket":"perpetuating"},{"id":"k7","text":"Drinks to stop the shaking and sleeplessness of withdrawal","bucket":"perpetuating"},{"id":"k8","text":"Says ''I can stop when I want'' and refused help before","bucket":"perpetuating"},{"id":"k9","text":"Wife and teenage son want him well; son came to the appointment","bucket":"protective"},{"id":"k10","text":"Frightened by the seizure and now asking how to stop","bucket":"protective"},{"id":"k11","text":"His shop sold stationery","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Khan, 45, presents with alcohol dependence with physiological withdrawal, shown by morning tremor relieved by drinking and a recent withdrawal seizure. A father who drank heavily and an early learned habit of drinking to unwind (predisposing) built the pattern; the loss of his shop two years ago (precipitating) doubled his intake. Drinking to relieve withdrawal, an evening routine centred on a drinking circle, and minimisation of the problem (perpetuating) maintain it. The fright of the seizure has opened a window of motivation, and a wife and son who are involved (protective) give a base for supervised detoxification, relapse-prevention medicine and family work.","hint":"A 45-year-old shopkeeper brought in after a withdrawal fit","tags":{"topic":"substance","difficulty":2,"objective":"Place withdrawal relief and social cues as perpetuating factors","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"substance","diagnosis":"Alcohol dependence with withdrawal seizure"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-6', 'Riya: washing until her hands bleed (OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"r1","text":"Intrusive thoughts of germs and of harming her family by passing on illness","bucket":"presenting"},{"id":"r2","text":"Washes hands 40 times a day and showers for an hour; hands cracked and bleeding","bucket":"presenting"},{"id":"r3","text":"Mother has always been very particular about cleanliness and order","bucket":"predisposing"},{"id":"r4","text":"Rigid, rule-bound and anxious as a child","bucket":"predisposing"},{"id":"r5","text":"Grandfather fell seriously ill with an infection a year ago","bucket":"precipitating"},{"id":"r6","text":"Family washes the vegetables again for her and answers ''Is it clean?'' many times a day","bucket":"perpetuating"},{"id":"r7","text":"Each wash brings relief for a few minutes, so the urge comes back stronger","bucket":"perpetuating"},{"id":"r8","text":"Avoids school because the toilets feel ''contaminated''","bucket":"perpetuating"},{"id":"r9","text":"Knows the thoughts are excessive and wants to stop (good insight)","bucket":"protective"},{"id":"r10","text":"A teacher she trusts has kept in touch","bucket":"protective"},{"id":"r11","text":"She is learning the sitar","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Riya, 16, presents with obsessive-compulsive disorder with good insight: contamination obsessions and fears of harming her family, with washing compulsions that take four hours a day and have damaged her skin. An anxious, rule-bound temperament and a household with strong cleanliness rules (predisposing) form the background; her grandfather''s serious infection (precipitating) gave the fears their content. The cycle is maintained because each wash brings brief relief that strengthens the urge, the family''s reassurance and re-washing accommodate the rituals, and avoiding school prevents her ever testing her fears (perpetuating). Good insight, her wish to stop and a trusted teacher (protective) make her a strong candidate for exposure and response prevention, with the family taught to step back from reassurance.","hint":"A 16-year-old whose rituals now take 4 hours a day","tags":{"topic":"ocd","difficulty":2,"objective":"Show how family accommodation maintains compulsions","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with good insight"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-7', 'Kavitha: the nurse who stopped eating lunch (moderate depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-7-1","text":"Replays the night of the death every evening","bucket":"perpetuating"},{"id":"form-7-2","text":"Tends to hold herself responsible for everything on the ward","bucket":"predisposing"},{"id":"form-7-3","text":"Volunteers for extra night shifts so she has no time to think","bucket":"perpetuating"},{"id":"form-7-4","text":"Has asked her GP for help herself","bucket":"protective"},{"id":"form-7-5","text":"A young patient in her care died after a cardiac arrest on her night shift","bucket":"precipitating"},{"id":"form-7-6","text":"Her hospital is changing to electronic records next year","bucket":"distractor"},{"id":"form-7-7","text":"Has stopped eating lunch and lost 4 kg","bucket":"presenting"},{"id":"form-7-8","text":"Low mood, early waking at 4 am and loss of interest for seven weeks","bucket":"presenting"},{"id":"form-7-9","text":"A ward sister who checks on her daily","bucket":"protective"},{"id":"form-7-10","text":"Previous low spell at 19 after her father''s illness","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kavitha, 32, presents with a moderate depressive episode: seven weeks of low mood, early waking, loss of interest and weight loss. An earlier low spell and a habit of taking personal responsibility for outcomes (predisposing) left her vulnerable, and the death of a young patient on her shift (precipitating) began the episode. Taking extra night shifts to avoid thinking and replaying the event each evening (perpetuating) disturb sleep and feed guilt. A caring ward sister and her own help-seeking (protective) are the base for treatment.","hint":"A staff nurse after a ward death she blames herself for","tags":{"topic":"depression","difficulty":1,"objective":"Sort a clear depressive presentation into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-8', 'Suresh: the farmer and the second failed crop (depression with risk)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-8-1","text":"Second consecutive cotton crop failure from pest attack","bucket":"precipitating"},{"id":"form-8-2","text":"Hopelessness, poor sleep and thoughts that his family would be better off without him","bucket":"presenting"},{"id":"form-8-3","text":"Has always kept worries to himself","bucket":"predisposing"},{"id":"form-8-4","text":"Two daughters he wants to see educated","bucket":"protective"},{"id":"form-8-5","text":"Stopped going to the village meetings","bucket":"presenting"},{"id":"form-8-6","text":"Wife who brought him to the health centre","bucket":"protective"},{"id":"form-8-7","text":"Drinks more in the evenings to sleep","bucket":"perpetuating"},{"id":"form-8-8","text":"Pesticide stored in the shed beside the house","bucket":"perpetuating"},{"id":"form-8-9","text":"The village got a new tar road last year","bucket":"distractor"},{"id":"form-8-10","text":"His elder brother died by suicide after crop loss","bucket":"predisposing"},{"id":"form-8-11","text":"Debt of three lakh to a private lender who visits often","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Suresh, 46, presents with a moderate depressive episode with suicidal ideation: hopelessness, broken sleep, withdrawal and thoughts that his family would be better off without him. A brother''s suicide after crop loss and a lifelong habit of hiding worry (predisposing) raise his risk; the second crop failure (precipitating) triggered the episode. Ongoing debt pressure, evening drinking and easy access to pesticide (perpetuating) keep both the mood and the risk high. His daughters'' future and a wife who sought help (protective) give reasons for living; the plan must include removing the pesticide, debt support and treatment.","hint":"A cotton farmer in debt who keeps pesticide in the shed","tags":{"topic":"depression","difficulty":3,"objective":"Show how social stressors and means access belong in a formulation","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"suicide","diagnosis":"Moderate depressive episode with suicidal ideation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-9', 'Mrs Banerjee: grey for twenty years (persistent depressive disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-9-1","text":"She prefers reading on paper rather than on screens","bucket":"distractor"},{"id":"form-9-2","text":"Grew up with a critical, cold mother","bucket":"predisposing"},{"id":"form-9-3","text":"No single trigger; worsened slightly after her son left for college","bucket":"precipitating"},{"id":"form-9-4","text":"Steady job she does well","bucket":"protective"},{"id":"form-9-5","text":"Lost her father at nine with little chance to grieve","bucket":"predisposing"},{"id":"form-9-6","text":"Self-critical thinking that she is a mediocre person","bucket":"perpetuating"},{"id":"form-9-7","text":"Low, joyless mood most days for over twenty years","bucket":"presenting"},{"id":"form-9-8","text":"Low self-esteem and constant tiredness without full collapse","bucket":"presenting"},{"id":"form-9-9","text":"Believes ''this is just my nature'' so never sought help","bucket":"perpetuating"},{"id":"form-9-10","text":"A close friend from college who calls weekly","bucket":"protective"},{"id":"form-9-11","text":"Withdraws from colleagues'' invitations","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Banerjee, 51, presents with persistent depressive disorder: over twenty years of low, joyless mood, poor self-esteem and fatigue without a single severe episode. A cold, critical mother and an early, ungrieved loss of her father (predisposing) shaped a self-critical view of herself. There is no clear precipitant, though her son leaving home made it more noticeable. Her belief that this is simply her nature, social withdrawal and self-critical thinking (perpetuating) have kept it going untreated for decades. A job she does well and a loyal friend (protective) are strengths for treatment, which can help even a long-standing low mood.","hint":"A school librarian who says she has always been gloomy","tags":{"topic":"depression","difficulty":2,"objective":"Formulate a chronic low-grade mood problem","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"depression","diagnosis":"Persistent depressive disorder (dysthymia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-10', 'Ankit: the topper who failed placement (depression in a student)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-10-1","text":"Froze and failed a campus placement interview","bucket":"precipitating"},{"id":"form-10-2","text":"Avoids his parents'' calls so the shame grows","bucket":"perpetuating"},{"id":"form-10-3","text":"Loss of interest, poor sleep and missing classes for six weeks","bucket":"presenting"},{"id":"form-10-4","text":"His college changed its canteen contractor","bucket":"distractor"},{"id":"form-10-5","text":"Core belief that he is worthless unless he comes first","bucket":"predisposing"},{"id":"form-10-6","text":"Night-time gaming that wrecks his sleep","bucket":"perpetuating"},{"id":"form-10-7","text":"Ignores calls from home and games through the night","bucket":"presenting"},{"id":"form-10-8","text":"Close bond with his younger sister","bucket":"protective"},{"id":"form-10-9","text":"Compares himself to friends who got placed","bucket":"perpetuating"},{"id":"form-10-10","text":"Father''s harsh expectations through school","bucket":"predisposing"},{"id":"form-10-11","text":"A roommate who brought him to the counsellor","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ankit, 21, presents with a moderate depressive episode: six weeks of anhedonia, poor sleep, missed classes and withdrawal. A belief that his worth depends on coming first, shaped by a father''s harsh expectations (predisposing), made a single failure feel catastrophic, and freezing in a placement interview (precipitating) set it off. Night gaming that ruins sleep, avoidance of his parents and constant comparison with placed friends (perpetuating) keep him stuck. A loyal roommate and his sister (protective) are allies; the plan should include a risk check, sleep routine and work on his all-or-nothing beliefs.","hint":"A final-year engineering student who games all night","tags":{"topic":"depression","difficulty":2,"objective":"Link academic pressure and avoidance in a young man''s depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-11', 'Mr Iqbal: since the stroke (post-stroke depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-11-1","text":"Long-standing high blood pressure and diabetes","bucket":"predisposing"},{"id":"form-11-2","text":"Identity built entirely around his tailoring skill","bucket":"predisposing"},{"id":"form-11-3","text":"Says he is ''useless now''","bucket":"presenting"},{"id":"form-11-4","text":"Cannot sew, so has lost his main source of pride","bucket":"perpetuating"},{"id":"form-11-5","text":"Left-sided stroke three months ago with weakness of the right hand","bucket":"precipitating"},{"id":"form-11-6","text":"Strong faith and regular prayer","bucket":"protective"},{"id":"form-11-7","text":"Grandson who sits with him every evening","bucket":"protective"},{"id":"form-11-8","text":"Low mood, crying and refusing physiotherapy on most days","bucket":"presenting"},{"id":"form-11-9","text":"His shop sign was repainted last year","bucket":"distractor"},{"id":"form-11-10","text":"Family do everything for him, so he does nothing","bucket":"perpetuating"},{"id":"form-11-11","text":"Skips physiotherapy, which slows recovery","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Iqbal, 68, presents with post-stroke depression: low mood, tearfulness, refusal of physiotherapy and a sense of being useless three months after a left-sided stroke. Vascular risk factors and an identity built on his craft (predisposing) set the stage; the stroke itself, which damaged the hand he sewed with (precipitating), brought on the episode both through brain injury and through loss of role. Loss of his work, well-meant over-helping by family and missed physiotherapy (perpetuating) keep him inactive and hopeless. His grandson and his faith (protective) can be built into rehabilitation goals and activity scheduling.","hint":"A retired tailor three months after a stroke","tags":{"topic":"depression","difficulty":3,"objective":"Include medical illness and role loss in a formulation","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Post-stroke depression"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-12', 'Leena: the winter months in Oslo (seasonal pattern)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-12-1","text":"Full recovery each spring","bucket":"presenting"},{"id":"form-12-2","text":"Cancels social plans in winter, so she becomes isolated","bucket":"perpetuating"},{"id":"form-12-3","text":"Moved from Kochi, where daylight is steady all year","bucket":"predisposing"},{"id":"form-12-4","text":"Stays indoors after night shifts and sees almost no daylight","bucket":"perpetuating"},{"id":"form-12-5","text":"Understanding manager who allows shift changes","bucket":"protective"},{"id":"form-12-6","text":"Clear insight into the pattern","bucket":"protective"},{"id":"form-12-7","text":"Low mood, oversleeping and craving for sweets each winter for three years","bucket":"presenting"},{"id":"form-12-8","text":"Mother had recurrent low spells","bucket":"predisposing"},{"id":"form-12-9","text":"She owns a second-hand bicycle","bucket":"distractor"},{"id":"form-12-10","text":"Onset each year as daylight shortens in November","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Leena, 34, presents with recurrent depressive disorder with a seasonal pattern: three winters of low mood, oversleeping and carbohydrate craving with full spring recovery. A family history of mood disorder and a move from a stable-daylight region (predisposing) leave her sensitive to light changes; shortening daylight each November (precipitating) triggers each episode. Night shifts with little daylight and winter social withdrawal (perpetuating) deepen it. A flexible manager and her own insight (protective) support a plan of light therapy, daytime light exposure, social scheduling and medicine if needed.","hint":"An Indian nurse in Norway whose low mood comes every November","tags":{"topic":"depression","difficulty":3,"objective":"Show a biological rhythm as a predisposing and perpetuating factor","exams":["md-psychiatry","ugc-net","cuet-pg"],"module":"depression","diagnosis":"Recurrent depressive disorder with seasonal pattern"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-13', 'Rajesh: four ECGs and still afraid (panic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-13-1","text":"Avoids the metro and crowded places","bucket":"presenting"},{"id":"form-13-2","text":"Repeated ECGs that calm him for a day only","bucket":"perpetuating"},{"id":"form-13-3","text":"Anxious temperament since school","bucket":"predisposing"},{"id":"form-13-4","text":"Sits near exits as a safety behaviour","bucket":"perpetuating"},{"id":"form-13-5","text":"He supports a cricket team from Chennai","bucket":"distractor"},{"id":"form-13-6","text":"First attack in a crowded metro coach during a heat wave","bucket":"precipitating"},{"id":"form-13-7","text":"Wife who joins him for therapy sessions","bucket":"protective"},{"id":"form-13-8","text":"Checks his pulse many times a day","bucket":"perpetuating"},{"id":"form-13-9","text":"Father had a heart attack at 50","bucket":"predisposing"},{"id":"form-13-10","text":"Sudden surges of racing heart, breathlessness and fear of dying, several times a week","bucket":"presenting"},{"id":"form-13-11","text":"Good understanding when the cycle is explained","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rajesh, 38, presents with panic disorder: frequent sudden surges of palpitations, breathlessness and fear of dying, with growing avoidance of the metro. An anxious temperament and his father''s heart attack (predisposing) made heart symptoms frightening; the first attack in a crowded, hot coach (precipitating) set the cycle off. Reassurance from repeated ECGs, pulse checking and sitting near exits (perpetuating) prevent him learning the attacks are harmless. His wife''s support and his quick grasp of the panic cycle (protective) favour CBT with graded exposure.","hint":"A bank clerk who now avoids the metro","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a clear panic cycle into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Panic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-14', 'Mrs Thomas: the woman who worries about everything (generalised anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-14-1","text":"Her mother was a constant worrier","bucket":"predisposing"},{"id":"form-14-2","text":"Calls her children every evening for reassurance","bucket":"perpetuating"},{"id":"form-14-3","text":"Constant hard-to-control worry about health, money and her children for over a year","bucket":"presenting"},{"id":"form-14-4","text":"Believes worrying keeps her family safe","bucket":"perpetuating"},{"id":"form-14-5","text":"Husband who is calm and patient","bucket":"protective"},{"id":"form-14-6","text":"Childhood with an unpredictable, drinking father","bucket":"predisposing"},{"id":"form-14-7","text":"Retired from teaching and lost her daily structure","bucket":"precipitating"},{"id":"form-14-8","text":"Avoids news and then worries about what she missed","bucket":"perpetuating"},{"id":"form-14-9","text":"She grows tomatoes on her balcony","bucket":"distractor"},{"id":"form-14-10","text":"Muscle tension, poor sleep and irritability","bucket":"presenting"},{"id":"form-14-11","text":"Active in her church choir","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Thomas, 62, presents with generalised anxiety disorder: a year of uncontrollable worry across many topics with tension, poor sleep and irritability. A worried mother and an unpredictable childhood home (predisposing) taught her that vigilance keeps danger away; retirement removed her structure and gave worry room (precipitating). Positive beliefs about worry, nightly reassurance calls and avoidance (perpetuating) keep the cycle running. Her choir and a calm husband (protective) can support CBT that targets beliefs about worry and reassurance seeking.","hint":"A retired teacher who calls her children every evening","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how beliefs about worry keep it going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Generalised anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-15', 'Rohan: red-faced in every presentation (social anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-15-1","text":"Blushes, trembles and avoids presentations","bucket":"presenting"},{"id":"form-15-2","text":"Shy and inhibited since early childhood","bucket":"predisposing"},{"id":"form-15-3","text":"Rehearses every sentence and avoids eye contact (safety behaviours)","bucket":"perpetuating"},{"id":"form-15-4","text":"Intense fear of being judged when speaking or eating in front of others","bucket":"presenting"},{"id":"form-15-5","text":"Avoids presentations, so never learns he can cope","bucket":"perpetuating"},{"id":"form-15-6","text":"He lives on the third floor of his building","bucket":"distractor"},{"id":"form-15-7","text":"Teased harshly in middle school","bucket":"predisposing"},{"id":"form-15-8","text":"Motivated to finish his degree","bucket":"protective"},{"id":"form-15-9","text":"Two close childhood friends","bucket":"protective"},{"id":"form-15-10","text":"Laughed at after forgetting lines in a school speech","bucket":"precipitating"},{"id":"form-15-11","text":"Replays each social event looking for mistakes","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohan, 19, presents with social anxiety disorder: intense fear of judgement when speaking or eating in front of others, with blushing, trembling and avoidance. An inhibited temperament and teasing in school (predisposing) built a fear of scrutiny; public laughter after a failed speech (precipitating) fixed it. Safety behaviours, avoidance and post-event rumination (perpetuating) keep the fear alive by blocking disconfirming experiences. Close friends and his wish to finish college (protective) support CBT focused on dropping safety behaviours and graded exposure.","hint":"A first-year college student who eats lunch in the library","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort the social anxiety cycle into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-16', 'Fatima: the Eid bazaar and the locked gate (agoraphobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-16-1","text":"Cannot leave the house without her husband for two years","bucket":"presenting"},{"id":"form-16-2","text":"First panic attack in a crowded bazaar during Eid shopping","bucket":"precipitating"},{"id":"form-16-3","text":"Husband wants her to get better and will join sessions","bucket":"protective"},{"id":"form-16-4","text":"Avoidance has spread from the bazaar to the street","bucket":"perpetuating"},{"id":"form-16-5","text":"Anxious as a child, clung to her mother at school","bucket":"predisposing"},{"id":"form-16-6","text":"Panic attacks in crowded places","bucket":"presenting"},{"id":"form-16-7","text":"Her house is painted light green","bucket":"distractor"},{"id":"form-16-8","text":"Husband now does all errands and takes the children to school","bucket":"perpetuating"},{"id":"form-16-9","text":"Mother also feared going out alone","bucket":"predisposing"},{"id":"form-16-10","text":"Wants to attend her daughter''s school events","bucket":"protective"},{"id":"form-16-11","text":"Takes an unknown ''nerve tablet'' from the chemist","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Fatima, 38, presents with agoraphobia with panic attacks: two years of being unable to leave home alone after panic in crowds. An anxious, clinging childhood and a mother with similar fears (predisposing) shaped her vulnerability; a panic attack in the Eid bazaar (precipitating) started the avoidance. Her husband doing all the errands, an unknown chemist sedative and the spreading of avoidance (perpetuating) keep her housebound. Her husband''s willingness to help and her wish to attend her daughter''s events (protective) support graded exposure with the family as coaches, not rescuers.","hint":"A homemaker who cannot leave the house alone","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how family accommodation maintains avoidance","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Agoraphobia with panic attacks"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-17', 'Neha: hands washed raw before exams (OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-17-1","text":"Washes hands 30 times a day and asks others if things are clean","bucket":"presenting"},{"id":"form-17-2","text":"Intrusive fears of contaminating others with germs","bucket":"presenting"},{"id":"form-17-3","text":"Knows the fears are excessive","bucket":"protective"},{"id":"form-17-4","text":"Roommates answer ''yes it''s clean'' many times a day","bucket":"perpetuating"},{"id":"form-17-5","text":"A hepatitis outbreak at her hostel during exams","bucket":"precipitating"},{"id":"form-17-6","text":"Avoids the hostel kitchen entirely","bucket":"perpetuating"},{"id":"form-17-7","text":"She plays badminton on weekends","bucket":"distractor"},{"id":"form-17-8","text":"Supportive mother who will learn to step back","bucket":"protective"},{"id":"form-17-9","text":"Uncle with similar checking habits","bucket":"predisposing"},{"id":"form-17-10","text":"Perfectionistic and rule-bound since childhood","bucket":"predisposing"},{"id":"form-17-11","text":"Each wash brings brief relief so the urge returns stronger","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neha, 20, presents with obsessive-compulsive disorder with contamination fears and washing and reassurance-seeking compulsions. A perfectionistic temperament and a family history of similar traits (predisposing) made her vulnerable; a hepatitis outbreak at her hostel (precipitating) gave the fears their content. Relief from washing, roommates'' reassurance and avoidance of the kitchen (perpetuating) strengthen the cycle. Good insight and a mother willing to stop accommodating (protective) make exposure and response prevention a strong option.","hint":"A pharmacy student with contamination fears","tags":{"topic":"ocd","difficulty":2,"objective":"Show how neutralising and reassurance maintain obsessions","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, contamination type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-18', 'Dinesh: the stove, the lock, the stove again (checking OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-18-1","text":"Takes photos of the locked door to look at later","bucket":"perpetuating"},{"id":"form-18-2","text":"Wife does a final check for him to save time","bucket":"perpetuating"},{"id":"form-18-3","text":"Strong belief that if anything goes wrong it will be his fault","bucket":"predisposing"},{"id":"form-18-4","text":"Each check raises doubt rather than settling it","bucket":"perpetuating"},{"id":"form-18-5","text":"A small kitchen fire at a neighbour''s flat","bucket":"precipitating"},{"id":"form-18-6","text":"Arrives late daily and has received warnings at work","bucket":"presenting"},{"id":"form-18-7","text":"He commutes by scooter","bucket":"distractor"},{"id":"form-18-8","text":"Strict, punishing father","bucket":"predisposing"},{"id":"form-18-9","text":"Checks the gas, locks and taps up to 20 times before leaving","bucket":"presenting"},{"id":"form-18-10","text":"Employer willing to adjust timing during treatment","bucket":"protective"},{"id":"form-18-11","text":"Good insight and wants to stop","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dinesh, 35, presents with obsessive-compulsive disorder with checking compulsions that make him late every day. An inflated sense of personal responsibility shaped by a punishing father (predisposing) gave fertile ground; a neighbour''s kitchen fire (precipitating) turned the fear onto gas and locks. His wife''s final checks, photos of the locked door and the way checking breeds more doubt (perpetuating) keep it going. Good insight and an accommodating employer (protective) support exposure and response prevention plus work on responsibility beliefs.","hint":"An accountant late for work every day","tags":{"topic":"ocd","difficulty":3,"objective":"Separate the inflated sense of responsibility from the rituals","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, checking type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-19', 'Captain Rana: the convoy ambush (PTSD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-19-1","text":"Ambush on his convoy in which two of his men died","bucket":"precipitating"},{"id":"form-19-2","text":"Avoids talking or thinking about the ambush","bucket":"perpetuating"},{"id":"form-19-3","text":"Culture of ''soldiers don''t complain''","bucket":"predisposing"},{"id":"form-19-4","text":"He was posted in Leh before the ambush","bucket":"distractor"},{"id":"form-19-5","text":"Drinks six pegs nightly to sleep","bucket":"presenting"},{"id":"form-19-6","text":"Unit medical officer who referred him","bucket":"protective"},{"id":"form-19-7","text":"Alcohol blocks emotional processing and worsens sleep","bucket":"perpetuating"},{"id":"form-19-8","text":"Wife who has not given up","bucket":"protective"},{"id":"form-19-9","text":"Nightmares and flashbacks of an ambush, startle and irritability for two years","bucket":"presenting"},{"id":"form-19-10","text":"Lost his mother suddenly at 12","bucket":"predisposing"},{"id":"form-19-11","text":"Survivor guilt: believes he should have saved them","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Captain Rana, 36, presents with post-traumatic stress disorder: two years of nightmares, flashbacks, startle and irritability after an ambush, with heavy drinking to sleep. An early sudden loss and a culture of silence about distress (predisposing) shaped how he copes; the ambush and the deaths of his men (precipitating) caused the disorder. Avoidance, alcohol that blocks processing, and survivor guilt (perpetuating) keep the memory raw. A loyal wife and a referring medical officer (protective) support trauma-focused therapy, alcohol treatment and a risk plan that covers his weapon.","hint":"An army officer who drinks to sleep","tags":{"topic":"trauma","difficulty":3,"objective":"Formulate trauma symptoms with substance use and risk","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Post-traumatic stress disorder with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-20', 'Pooja: the flood that took the house (adjustment disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-20-1","text":"Tends to worry when routines break","bucket":"predisposing"},{"id":"form-20-2","text":"Lost her grandparents'' home in an earlier flood as a child","bucket":"predisposing"},{"id":"form-20-3","text":"Tearfulness, worry and poor sleep since the flood","bucket":"presenting"},{"id":"form-20-4","text":"Living in her in-laws'' crowded home with little privacy","bucket":"perpetuating"},{"id":"form-20-5","text":"Struggles to concentrate on teaching","bucket":"presenting"},{"id":"form-20-6","text":"Strong local community rebuilding together","bucket":"protective"},{"id":"form-20-7","text":"Floodwater damaged her home and the family moved to a relief camp","bucket":"precipitating"},{"id":"form-20-8","text":"Her son is learning Bharatanatyam","bucket":"distractor"},{"id":"form-20-9","text":"Supportive school principal","bucket":"protective"},{"id":"form-20-10","text":"Slow insurance and compensation process","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pooja, 35, presents with an adjustment disorder with mixed anxiety and low mood after floodwater damaged her home: tearfulness, worry, poor sleep and poor concentration that exceed what she expected but do not meet criteria for a depressive episode. A tendency to worry when routines break and an earlier flood loss in childhood (predisposing) made this harder; the flood and displacement (precipitating) began it. Slow compensation and crowded living (perpetuating) prolong it. Her principal''s support and the community''s rebuilding (protective) favour practical help, problem-solving and brief supportive therapy.","hint":"A teacher three months after floods in Kerala","tags":{"topic":"trauma","difficulty":2,"objective":"Formulate distress in response to a clear stressor","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Adjustment disorder with mixed anxiety and low mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-21', 'Arvind: the heart he is sure is failing (illness anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-21-1","text":"Fixed fear that he has undiagnosed heart disease despite normal tests","bucket":"presenting"},{"id":"form-21-2","text":"Father died of a sudden heart attack at 52","bucket":"predisposing"},{"id":"form-21-3","text":"Has had 14 tests in two years","bucket":"presenting"},{"id":"form-21-4","text":"He collects old coins","bucket":"distractor"},{"id":"form-21-5","text":"Wife who wants him to stop testing","bucket":"protective"},{"id":"form-21-6","text":"Avoids exercise in case it strains his heart","bucket":"perpetuating"},{"id":"form-21-7","text":"Searches symptoms online for hours at night","bucket":"perpetuating"},{"id":"form-21-8","text":"Tendency to read bodily sensations as danger","bucket":"predisposing"},{"id":"form-21-9","text":"Each normal test calms him for only a day","bucket":"perpetuating"},{"id":"form-21-10","text":"Responds well when the cycle is drawn out","bucket":"protective"},{"id":"form-21-11","text":"A colleague of his age died of a heart attack","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arvind, 41, presents with illness anxiety disorder: a fixed fear of undiagnosed heart disease despite fourteen normal tests. His father''s sudden cardiac death and a habit of reading body sensations as danger (predisposing) made him vulnerable; a colleague''s heart attack (precipitating) set it off. Night-time online searching, short-lived reassurance from tests and avoidance of exercise (perpetuating) keep attention fixed on his heart. His wife''s support and his response to seeing the cycle (protective) suit CBT that reduces checking and reassurance and rebuilds activity.","hint":"A software lead who has had 14 cardiac tests","tags":{"topic":"somatic","difficulty":3,"objective":"Show checking and reassurance as perpetuating factors in health anxiety","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Illness anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-22', 'Meera: the band around the head (somatic symptom disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-22-1","text":"Pain began after her son moved abroad and her husband retired","bucket":"precipitating"},{"id":"form-22-2","text":"Long-standing difficulty putting feelings into words","bucket":"predisposing"},{"id":"form-22-3","text":"Enjoys her temple bhajan group when she goes","bucket":"protective"},{"id":"form-22-4","text":"Her house faces east","bucket":"distractor"},{"id":"form-22-5","text":"Visits doctors several times a month","bucket":"presenting"},{"id":"form-22-6","text":"Grew up in a home where only physical illness earned care","bucket":"predisposing"},{"id":"form-22-7","text":"Family attention increases when pain is worse","bucket":"perpetuating"},{"id":"form-22-8","text":"A daughter-in-law she trusts","bucket":"protective"},{"id":"form-22-9","text":"Rests in bed most afternoons, so fitness falls","bucket":"perpetuating"},{"id":"form-22-10","text":"Daily headaches and body pain for four years with excessive worry about them","bucket":"presenting"},{"id":"form-22-11","text":"Repeated tests and painkiller injections that bring short relief","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meera, 56, presents with somatic symptom disorder: four years of daily headaches and body pain with heavy worry and frequent doctor visits. A childhood where only physical illness earned care and difficulty naming feelings (predisposing) shaped a bodily way of expressing distress; pain began as her son left and her husband retired (precipitating). Repeated tests and injections, daytime resting and extra family attention when pain rises (perpetuating) keep it going. A trusted daughter-in-law and her bhajan group (protective) can support a plan built on one regular doctor, graded activity and gentle work on emotions.","hint":"A homemaker with years of headaches and many doctors","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate persistent somatic symptoms without dismissing them","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Somatic symptom disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-23', 'Kiran: the legs that stopped after the wedding news (functional weakness)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-23-1","text":"Previous episode of losing her voice at 15 during exams","bucket":"predisposing"},{"id":"form-23-2","text":"Little say in family decisions","bucket":"predisposing"},{"id":"form-23-3","text":"She was born in the month of Shravan","bucket":"distractor"},{"id":"form-23-4","text":"Wheelchair use and bed rest leading to deconditioning","bucket":"perpetuating"},{"id":"form-23-5","text":"Told her marriage had been fixed to a man she has not met","bucket":"precipitating"},{"id":"form-23-6","text":"Motivated to return to her nursing course","bucket":"protective"},{"id":"form-23-7","text":"Sudden weakness of both legs for three weeks, unable to walk","bucket":"presenting"},{"id":"form-23-8","text":"A cousin she confides in","bucket":"protective"},{"id":"form-23-9","text":"Normal scans, nerve tests and positive Hoover''s sign","bucket":"presenting"},{"id":"form-23-10","text":"Fear that walking again means the wedding goes ahead","bucket":"perpetuating"},{"id":"form-23-11","text":"Family believe it is a curse and await a ritual cure","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kiran, 20, presents with functional neurological symptom disorder: three weeks of leg weakness with normal investigations and positive signs of functional weakness. A previous functional voice loss and having little voice in family decisions (predisposing) suggest a vulnerability to expressing overwhelming conflict through the body; news of an arranged marriage she did not choose (precipitating) came just before onset. Wheelchair use, family belief in a curse and her fear that recovery means the wedding (perpetuating) maintain it. A confiding cousin and her nursing ambitions (protective) support physiotherapy-led rehabilitation, a clear explanation of the condition and safe exploration of the marriage conflict.","hint":"A young woman who cannot walk, with normal scans","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate functional neurological symptoms without blame","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Functional neurological symptom disorder (functional weakness)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-24', 'Shalini: ''I am too fat'' at 38 kg (anorexia nervosa)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-24-1","text":"Starvation narrows her thinking to food and weight","bucket":"perpetuating"},{"id":"form-24-2","text":"Close relationship with her father","bucket":"protective"},{"id":"form-24-3","text":"Intense fear of gaining weight; periods stopped","bucket":"presenting"},{"id":"form-24-4","text":"Praise from friends for ''looking fit''","bucket":"perpetuating"},{"id":"form-24-5","text":"Over-exercises two hours daily","bucket":"perpetuating"},{"id":"form-24-6","text":"Perfectionism and high achievement at school","bucket":"predisposing"},{"id":"form-24-7","text":"Wants to keep dancing, which needs strength","bucket":"protective"},{"id":"form-24-8","text":"Dance teacher said she needed to be ''lighter'' for a competition","bucket":"precipitating"},{"id":"form-24-9","text":"Her school has a new principal","bucket":"distractor"},{"id":"form-24-10","text":"Weight 38 kg (BMI about 15) after losing 12 kg in a year","bucket":"presenting"},{"id":"form-24-11","text":"Mother diets constantly and comments on weight","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shalini, 17, presents with anorexia nervosa, restricting type: weight loss to a BMI near 15, fear of weight gain and loss of periods. Perfectionism and a family focus on dieting (predisposing) shaped her vulnerability; a dance teacher''s comment about being lighter (precipitating) started the restriction. The effects of starvation on thinking, praise for her appearance and excessive exercise (perpetuating) maintain it. Her bond with her father and her wish to dance with strength (protective) support family-based treatment with medical monitoring for refeeding risks.","hint":"A 17-year-old dancer who has lost 12 kg","tags":{"topic":"eating","difficulty":3,"objective":"Show how starvation itself maintains an eating disorder","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Anorexia nervosa, restricting type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-25', 'Ritu: the midnight binges and the guilt (bulimia nervosa)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-25-1","text":"Binge eating three to four nights a week followed by vomiting","bucket":"presenting"},{"id":"form-25-2","text":"She has a pet parrot","bucket":"distractor"},{"id":"form-25-3","text":"Skips meals all day after a binge, which sets up the next binge","bucket":"perpetuating"},{"id":"form-25-4","text":"Low self-esteem tied to appearance","bucket":"predisposing"},{"id":"form-25-5","text":"Teased about weight as a child","bucket":"predisposing"},{"id":"form-25-6","text":"Vomiting makes her believe she can binge ''safely''","bucket":"perpetuating"},{"id":"form-25-7","text":"Normal weight but intense concern about shape","bucket":"presenting"},{"id":"form-25-8","text":"A sister who knows and wants to help","bucket":"protective"},{"id":"form-25-9","text":"Wishes to stop and asked for help","bucket":"protective"},{"id":"form-25-10","text":"Binges when stressed by night shifts","bucket":"perpetuating"},{"id":"form-25-11","text":"Break-up with a partner who criticised her body","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ritu, 25, presents with bulimia nervosa: frequent binges followed by vomiting, at a normal weight, with self-worth tied to shape. Childhood teasing and appearance-based self-esteem (predisposing) set the ground; a critical partner and the break-up (precipitating) intensified body concern. Daytime restriction that drives night binges, the false safety of vomiting and stress from night shifts (perpetuating) keep the cycle turning. Her sister''s support and her own wish to change (protective) favour CBT for eating disorders with regular eating as the first step, plus checks on potassium.","hint":"A call-centre worker who vomits after eating","tags":{"topic":"eating","difficulty":3,"objective":"Map the binge, purge and restrict cycle","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Bulimia nervosa"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-26', 'Vinod: four hours of sleep and blaming the mattress (insomnia disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-26-1","text":"Tired and irritable at work","bucket":"presenting"},{"id":"form-26-2","text":"Mother had sleep problems","bucket":"predisposing"},{"id":"form-26-3","text":"Months of stress during a school inspection","bucket":"precipitating"},{"id":"form-26-4","text":"Checks the clock and calculates lost sleep","bucket":"perpetuating"},{"id":"form-26-5","text":"He bought a new mattress twice","bucket":"distractor"},{"id":"form-26-6","text":"Difficulty falling and staying asleep for eight months","bucket":"presenting"},{"id":"form-26-7","text":"Wife willing to change routines together","bucket":"protective"},{"id":"form-26-8","text":"Light sleeper and worrier all his life","bucket":"predisposing"},{"id":"form-26-9","text":"Naps in the afternoon and drinks tea late","bucket":"perpetuating"},{"id":"form-26-10","text":"Motivated and organised","bucket":"protective"},{"id":"form-26-11","text":"Spends nine hours in bed to ''catch up''","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vinod, 50, presents with insomnia disorder: eight months of trouble falling and staying asleep with daytime fatigue. A lifelong light-sleeping, worrying style and a family pattern of poor sleep (predisposing) left him vulnerable; inspection stress (precipitating) began it. Long hours in bed, clock-watching, afternoon naps and late tea (perpetuating) weaken his sleep drive and condition his bed for wakefulness. His organised nature and a supportive wife (protective) make CBT for insomnia, with sleep restriction and stimulus control, a good fit. The new mattresses were a reasonable guess but not a cause.","hint":"A school principal who lies awake for hours","tags":{"topic":"sleep","difficulty":2,"objective":"Show how behaviour in bed keeps insomnia going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"more-disorders","diagnosis":"Insomnia disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-27', 'Asha: the mood that drops every month (PMDD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-27-1","text":"Tracks her cycle on an app","bucket":"protective"},{"id":"form-27-2","text":"Symptoms worsened after stopping the contraceptive pill","bucket":"precipitating"},{"id":"form-27-3","text":"High-pressure perfectionism at work","bucket":"predisposing"},{"id":"form-27-4","text":"She drives an automatic car","bucket":"distractor"},{"id":"form-27-5","text":"Schedules her heaviest work in the bad week without noticing","bucket":"perpetuating"},{"id":"form-27-6","text":"Partner who wants to understand","bucket":"protective"},{"id":"form-27-7","text":"Well in the week after periods","bucket":"presenting"},{"id":"form-27-8","text":"Arguments with her partner in the bad week leave lasting tension","bucket":"perpetuating"},{"id":"form-27-9","text":"Severe irritability, sadness and anxiety in the week before periods","bucket":"presenting"},{"id":"form-27-10","text":"Sensitivity to hormonal change; mother had similar problems","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Asha, 30, presents with premenstrual dysphoric disorder: severe irritability, sadness and anxiety in the luteal week with clear wellness after menstruation. Sensitivity to hormonal shifts with a family history and a perfectionistic style (predisposing) shaped her vulnerability; stopping the pill (precipitating) unmasked worse symptoms. Heavy workloads and arguments falling in the bad week (perpetuating) compound the distress. Her cycle tracking and a willing partner (protective) support confirmation by prospective charting and treatment options including SSRIs and planning around the cycle.","hint":"A lawyer whose worst week is the same week each cycle","tags":{"topic":"depression","difficulty":3,"objective":"Include a biological cycle in the formulation","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Premenstrual dysphoric disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-28', 'Baba Ji: grief at four weeks (normal bereavement)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-28-1","text":"Waves of yearning when he sees her things","bucket":"presenting"},{"id":"form-28-2","text":"No past mental illness","bucket":"predisposing"},{"id":"form-28-3","text":"Laughs with grandchildren at times","bucket":"protective"},{"id":"form-28-4","text":"His scooter needs servicing","bucket":"distractor"},{"id":"form-28-5","text":"Wife died after a short illness","bucket":"precipitating"},{"id":"form-28-6","text":"Married for 48 years; she managed the household","bucket":"predisposing"},{"id":"form-28-7","text":"Has not yet had to learn household tasks she did","bucket":"perpetuating"},{"id":"form-28-8","text":"Visits the temple and his brother daily","bucket":"protective"},{"id":"form-28-9","text":"Crying, poor appetite and poor sleep four weeks after his wife''s death","bucket":"presenting"},{"id":"form-28-10","text":"Avoids her room, which is still as she left it","bucket":"perpetuating"},{"id":"form-28-11","text":"Keeps self-esteem: says he was a good husband","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Baba Ji, 70, presents four weeks after his wife''s death with crying, poor sleep and poor appetite in waves of yearning linked to reminders of her: a normal grief reaction, not a mental disorder. Forty-eight years of marriage and her management of the home (predisposing) shape the size of the loss; her death after a short illness is the clear precipitant. Practical gaps and avoidance of her room (perpetuating) are expected early features. Preserved self-esteem, daily contact with his brother and the temple and moments of warmth with grandchildren (protective) all point away from depression; the plan is support, practical help and review if grief does not soften.","hint":"A 70-year-old man whose wife died last month","tags":{"topic":"grief","difficulty":4,"objective":"Use a formulation to show why this is not a disorder","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"depression","diagnosis":"Normal grief (no mental disorder)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-29', 'Shreya: the two-week highs she misses (bipolar II)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-29-1","text":"Her bakery has a blue awning","bucket":"distractor"},{"id":"form-29-2","text":"Low mood began after a slow business month","bucket":"precipitating"},{"id":"form-29-3","text":"Mother with mood swings","bucket":"predisposing"},{"id":"form-29-4","text":"Previously treated with an antidepressant alone","bucket":"perpetuating"},{"id":"form-29-5","text":"Values the highs and tries to recreate them with late nights","bucket":"perpetuating"},{"id":"form-29-6","text":"Past spells of four to seven days with high energy and little sleep","bucket":"presenting"},{"id":"form-29-7","text":"Irregular sleep from baking at night","bucket":"perpetuating"},{"id":"form-29-8","text":"Good insight into the lows","bucket":"protective"},{"id":"form-29-9","text":"Depressive episode for a month","bucket":"presenting"},{"id":"form-29-10","text":"Early adult onset of low spells","bucket":"predisposing"},{"id":"form-29-11","text":"Husband who recognises the early signs","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shreya, 31, presents with bipolar II disorder in a depressive episode; the history of several short hypomanic spells changes both the diagnosis and the treatment. A family history of mood instability and early-onset low spells (predisposing) raise her risk; a slow business month (precipitating) came before this episode. Valuing and chasing the highs, irregular night-time sleep and past antidepressant-only treatment (perpetuating) destabilise her mood. A husband who spots early signs and her insight into lows (protective) support mood-stabilising treatment, regular sleep and a relapse-signature plan.","hint":"A baker who comes only when she is low","tags":{"topic":"bipolar","difficulty":4,"objective":"Show why a missed history of highs changes the formulation","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar II disorder, current depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-30', 'Mr Rao: the lithium and the heat wave (lithium toxicity)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-30-1","text":"Coarse tremor, unsteady walking, vomiting and confusion over two days","bucket":"presenting"},{"id":"form-30-2","text":"Wife who noticed the change quickly","bucket":"protective"},{"id":"form-30-3","text":"Drinking little water in the heat","bucket":"perpetuating"},{"id":"form-30-4","text":"Chemist unaware of his lithium","bucket":"perpetuating"},{"id":"form-30-5","text":"No lithium level for over a year","bucket":"perpetuating"},{"id":"form-30-6","text":"Long-term lithium treatment","bucket":"predisposing"},{"id":"form-30-7","text":"Diarrhoea in a heat wave plus a new painkiller (ibuprofen) from the chemist","bucket":"precipitating"},{"id":"form-30-8","text":"Previously stable and engaged with care","bucket":"protective"},{"id":"form-30-9","text":"Age 66 with reduced kidney function","bucket":"predisposing"},{"id":"form-30-10","text":"He enjoys Carnatic music","bucket":"distractor"},{"id":"form-30-11","text":"Stable bipolar disorder on lithium for 20 years","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rao, 66, presents with lithium toxicity: coarse tremor, ataxia, vomiting and confusion after two days of diarrhoea in a heat wave. Older age, reduced kidney function and long-term lithium (predisposing) narrowed his safety margin; dehydration plus a new anti-inflammatory painkiller (precipitating) raised lithium levels. Poor fluid intake, lapsed monitoring and a chemist who did not know about lithium (perpetuating) allowed it to build. An observant wife and a history of good engagement (protective) help now, and prevention needs regular levels, sick-day rules and a medicine card.","hint":"A retired clerk confused after diarrhoea and a painkiller","tags":{"topic":"bipolar","difficulty":3,"objective":"Formulate an iatrogenic emergency","exams":["md-psychiatry","mcp-entrance"],"module":"stabilisers","diagnosis":"Lithium toxicity"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-31', 'Rakesh: the voices after the hostel move (first-episode psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-31-1","text":"Eight months untreated while the family tried a temple first","bucket":"perpetuating"},{"id":"form-31-2","text":"Hears two voices commenting on his actions","bucket":"presenting"},{"id":"form-31-3","text":"Parents who came quickly when called","bucket":"protective"},{"id":"form-31-4","text":"Aunt with a long psychotic illness","bucket":"predisposing"},{"id":"form-31-5","text":"Believes professors insert thoughts into his head","bucket":"presenting"},{"id":"form-31-6","text":"Good school record before onset","bucket":"protective"},{"id":"form-31-7","text":"Shy, isolated adolescence","bucket":"predisposing"},{"id":"form-31-8","text":"Stopped eating in the mess, sleeps little","bucket":"perpetuating"},{"id":"form-31-9","text":"Believes medicine is ''for mad people''","bucket":"perpetuating"},{"id":"form-31-10","text":"His hostel room faces the football ground","bucket":"distractor"},{"id":"form-31-11","text":"Moved to a distant hostel and lost his usual supports","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rakesh, 20, presents with a first episode of schizophrenia: running-commentary voices and delusions of thought insertion after an eight-month prodrome of withdrawal and decline. A family history of psychotic illness and an isolated adolescence (predisposing) raised his vulnerability; moving far from home (precipitating) removed his supports. A long duration of untreated psychosis, poor sleep and eating, and stigma about medicine (perpetuating) worsen the outlook. Responsive parents and a good premorbid record (protective) support early intervention with medicine, family work and a return-to-study plan.","hint":"A 20-year-old who taped his laptop camera","tags":{"topic":"psychosis","difficulty":2,"objective":"Sort a first episode with prodrome into the 5 Ps","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"psychosis","diagnosis":"Schizophrenia, first episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-32', 'Shabana: back again after stopping (relapse of schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-32-1","text":"Voices and beliefs about black magic by a neighbour have returned","bucket":"presenting"},{"id":"form-32-2","text":"Poor sleep and angry outbursts for six weeks","bucket":"presenting"},{"id":"form-32-3","text":"Brother hides tablets in her food, which destroyed trust","bucket":"perpetuating"},{"id":"form-32-4","text":"Three years of good stability when on treatment","bucket":"protective"},{"id":"form-32-5","text":"Stopped her antipsychotic two months ago","bucket":"precipitating"},{"id":"form-32-6","text":"Weight gain of 12 kg and slowness that hurt her sewing income","bucket":"perpetuating"},{"id":"form-32-7","text":"Ten-year history of schizophrenia with three admissions","bucket":"predisposing"},{"id":"form-32-8","text":"Her sewing machine is a 1990s model","bucket":"distractor"},{"id":"form-32-9","text":"Tailoring skill and pride in her work","bucket":"protective"},{"id":"form-32-10","text":"A peer told her the tablets are poison","bucket":"perpetuating"},{"id":"form-32-11","text":"Father had a similar illness","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shabana, 37, presents with a relapse of schizophrenia after stopping medicine: returning voices and persecutory beliefs about black magic. A long illness and a family history (predisposing) make relapse likely without treatment; stopping her antipsychotic (precipitating) began this episode. The side effects that cost her work, covert medication that broke trust and peer misinformation (perpetuating) all drive non-adherence. Three stable years on treatment and her pride in her craft (protective) support a plan that switches to a medicine with fewer metabolic effects, rebuilds trust openly and links treatment to her work goals.","hint":"A tailor who gained 12 kg on her tablets","tags":{"topic":"psychosis","difficulty":3,"objective":"Put side effects at the centre of a relapse formulation","exams":["mcp-entrance","md-psychiatry"],"module":"antipsychotics","diagnosis":"Schizophrenia, relapse after stopping medicine"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-33', 'Mr Bhatt: the wife and the milkman (delusional disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-33-1","text":"Onset after erectile difficulties began","bucket":"precipitating"},{"id":"form-33-2","text":"His shop sells paint and hardware","bucket":"distractor"},{"id":"form-33-3","text":"Sons who moved home to protect their mother","bucket":"protective"},{"id":"form-33-4","text":"Each ''piece of evidence'' he finds confirms the belief","bucket":"perpetuating"},{"id":"form-33-5","text":"Drinking at weekends increases interrogations","bucket":"perpetuating"},{"id":"form-33-6","text":"Shame stops him discussing his sexual health","bucket":"perpetuating"},{"id":"form-33-7","text":"Checks her phone and clothes and follows her","bucket":"presenting"},{"id":"form-33-8","text":"Works steadily and keeps his business","bucket":"protective"},{"id":"form-33-9","text":"Long-standing feelings of inadequacy","bucket":"predisposing"},{"id":"form-33-10","text":"Fixed belief that his wife is having an affair, for a year","bucket":"presenting"},{"id":"form-33-11","text":"Suspicious, sensitive personality","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhatt, 52, presents with delusional disorder, jealous type: a year of fixed belief in his wife''s infidelity with checking and following, and a serious risk of violence to her. A suspicious, sensitive personality and feelings of inadequacy (predisposing) shaped vulnerability; the onset of erectile difficulties (precipitating) appears to have fed the belief. Confirmation from ''evidence'', weekend drinking and shame about sexual health (perpetuating) keep it fixed. His sons'' protection and his intact working life (protective) help engagement, but the first priority is the wife''s safety plan, then treatment and support for sexual health.","hint":"A shop owner who checks his wife''s phone nightly","tags":{"topic":"psychosis","difficulty":4,"objective":"Include risk to others in a delusional disorder formulation","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Delusional disorder, jealous type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-34', 'Mohan: the man who sits all day (negative symptoms)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-34-1","text":"Sedation from medicine adds to inactivity","bucket":"perpetuating"},{"id":"form-34-2","text":"Illness onset at 22 with two early admissions","bucket":"predisposing"},{"id":"form-34-3","text":"Gradual decline after his father''s retirement reduced outings","bucket":"precipitating"},{"id":"form-34-4","text":"The family owns a black-and-white photo album","bucket":"distractor"},{"id":"form-34-5","text":"Devoted parents","bucket":"protective"},{"id":"form-34-6","text":"Parents do everything for him out of love","bucket":"perpetuating"},{"id":"form-34-7","text":"Apathy, poverty of speech and poor self-care","bucket":"presenting"},{"id":"form-34-8","text":"No structured activity or rehabilitation in the day","bucket":"perpetuating"},{"id":"form-34-9","text":"Enjoyed kite flying and music earlier","bucket":"protective"},{"id":"form-34-10","text":"Limited education and no work history since onset","bucket":"predisposing"},{"id":"form-34-11","text":"Voices well controlled for years","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mohan, 45, presents with schizophrenia with predominant negative symptoms: apathy, poverty of speech and poor self-care, with positive symptoms controlled. Early onset and loss of education and work (predisposing) limited his skills; reduced outings after his father retired (precipitating) deepened the withdrawal. No day structure, sedation and loving over-care by parents (perpetuating) reinforce inactivity. Devoted parents and old interests in kites and music (protective) are routes into psychosocial rehabilitation, a medicine review for sedation and future-care planning.","hint":"A 45-year-old with 20 years of illness and ageing parents","tags":{"topic":"psychosis","difficulty":3,"objective":"Formulate negative symptoms and the future of care","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"psychosis","diagnosis":"Schizophrenia with predominant negative symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-35', 'Sai: the joints during exams (cannabis-induced psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-35-1","text":"A friend who brought him","bucket":"protective"},{"id":"form-35-2","text":"Poor sleep and fear","bucket":"presenting"},{"id":"form-35-3","text":"Fear of his parents finding out stops him seeking help","bucket":"perpetuating"},{"id":"form-35-4","text":"Binge of heavy cannabis and MDMA at a beach party","bucket":"precipitating"},{"id":"form-35-5","text":"He studies typography","bucket":"distractor"},{"id":"form-35-6","text":"Social anxiety eased by smoking","bucket":"predisposing"},{"id":"form-35-7","text":"Daily cannabis since 18","bucket":"predisposing"},{"id":"form-35-8","text":"Stopped cannabis himself out of fear","bucket":"protective"},{"id":"form-35-9","text":"Two weeks of believing friends film him and hearing whispers","bucket":"presenting"},{"id":"form-35-10","text":"Friends in his circle still smoke daily","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sai, 19, presents with a cannabis-induced psychotic disorder: persecutory ideas and whispering voices starting after a heavy binge. Daily cannabis use since 18 and social anxiety that smoking eased (predisposing) increased vulnerability; a beach-party binge with MDMA (precipitating) triggered it. A smoking peer group and fear of parental discovery (perpetuating) risk continued use and delay. Stopping use himself and a caring friend (protective) give an opening for treatment, a month of abstinence with reassessment, and work on social anxiety.","hint":"A design student in Goa sure his friends film him","tags":{"topic":"psychosis","difficulty":3,"objective":"Show substance use across several Ps","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Cannabis-induced psychotic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-36', 'Raju: the auto driver''s morning quarter (alcohol dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-36-1","text":"Drinks daily from morning, with tremor relieved by drinking","bucket":"presenting"},{"id":"form-36-2","text":"Daily evenings at the auto stand bar","bucket":"perpetuating"},{"id":"form-36-3","text":"Income fell when ride apps came; drinking rose","bucket":"precipitating"},{"id":"form-36-4","text":"His auto is painted green and yellow","bucket":"distractor"},{"id":"form-36-5","text":"Father drank heavily","bucket":"predisposing"},{"id":"form-36-6","text":"Saw insects on the wall when he tried to stop","bucket":"presenting"},{"id":"form-36-7","text":"Ashamed about his son''s silence, which can fuel change","bucket":"protective"},{"id":"form-36-8","text":"Believes he can stop when he wants","bucket":"perpetuating"},{"id":"form-36-9","text":"Wife still with him","bucket":"protective"},{"id":"form-36-10","text":"Drinks to stop withdrawal shakes","bucket":"perpetuating"},{"id":"form-36-11","text":"Drinking normal among his auto stand friends","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raju, 42, presents with alcohol dependence with a history of complicated withdrawal: daily morning drinking to relieve tremor and visual disturbances when he stopped. A father who drank and a drinking peer culture (predisposing) laid the base; falling income when ride apps arrived (precipitating) increased his drinking. Drinking to avoid withdrawal, a bar at the auto stand and minimisation (perpetuating) maintain it. His wife and his shame about his son (protective) can power change, starting with medically supervised detox with thiamine.","hint":"A driver who saw insects on the wall when he stopped","tags":{"topic":"substance","difficulty":1,"objective":"Sort a clear alcohol dependence case into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"substance","diagnosis":"Alcohol dependence with complicated withdrawal"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-37', 'Gurpreet: chitta in Tarn Taran (opioid dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-37-1","text":"Stealing from home","bucket":"presenting"},{"id":"form-37-2","text":"Past forced rehab with chaining and beatings made him distrust treatment","bucket":"perpetuating"},{"id":"form-37-3","text":"Father drinks; little supervision as a teen","bucket":"predisposing"},{"id":"form-37-4","text":"Injecting heroin daily with tolerance and withdrawal","bucket":"presenting"},{"id":"form-37-5","text":"Shares needles with friends","bucket":"perpetuating"},{"id":"form-37-6","text":"The family farm grows wheat and paddy","bucket":"distractor"},{"id":"form-37-7","text":"Withdrawal drives daily use","bucket":"perpetuating"},{"id":"form-37-8","text":"Brother abroad who could support recovery","bucket":"protective"},{"id":"form-37-9","text":"Failed Class 12 and joined friends who used","bucket":"precipitating"},{"id":"form-37-10","text":"Mother who keeps bringing him for help","bucket":"protective"},{"id":"form-37-11","text":"Easy local availability of heroin","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gurpreet, 24, presents with opioid dependence with injecting: tolerance, withdrawal, theft and needle sharing. High local availability and little supervision with a drinking father (predisposing) shaped the risk; failing Class 12 and joining using friends (precipitating) began it. Distrust after an abusive private rehab, needle sharing and withdrawal-driven use (perpetuating) keep him using and at risk of infection and overdose. A persistent mother and a supportive brother (protective) support opioid substitution treatment, naloxone, testing for blood-borne infections and family work.","hint":"A young man injecting heroin after a failed rehab","tags":{"topic":"substance","difficulty":2,"objective":"Include harmful treatment history in the formulation","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"substance","diagnosis":"Opioid dependence, injecting"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-38', 'Vishal: the rummy app and six loan apps (gambling disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-38-1","text":"Wife likely to support him once told","bucket":"protective"},{"id":"form-38-2","text":"A large win of 40,000 early on","bucket":"precipitating"},{"id":"form-38-3","text":"Easy loan apps that lend in minutes","bucket":"perpetuating"},{"id":"form-38-4","text":"Stable job","bucket":"protective"},{"id":"form-38-5","text":"Believes he is ''lucky with numbers''","bucket":"predisposing"},{"id":"form-38-6","text":"Secrecy from his wife increases shame and stress","bucket":"perpetuating"},{"id":"form-38-7","text":"Uncle who gambled","bucket":"predisposing"},{"id":"form-38-8","text":"Debts of six lakh hidden from his new wife","bucket":"presenting"},{"id":"form-38-9","text":"A year of online card gambling with chasing losses","bucket":"presenting"},{"id":"form-38-10","text":"He works at a branch near the railway station","bucket":"distractor"},{"id":"form-38-11","text":"Chasing losses to win it back","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vishal, 29, presents with gambling disorder: a year of online card gambling, chasing losses, lying and six lakh of hidden debt, with suicidal thoughts when loan agents threaten him. A family history of gambling and a belief in his own luck (predisposing) set the ground; an early big win (precipitating) hooked him. Chasing losses, instant loan apps and secrecy (perpetuating) deepen the hole. A likely supportive wife and stable job (protective) support a plan of safety planning, financial controls, telling his wife with help, and CBT.","hint":"A bank cashier hiding six lakh of debt","tags":{"topic":"substance","difficulty":3,"objective":"Formulate a behavioural addiction with suicide risk","exams":["mcp-entrance","ma-semester"],"module":"substance","diagnosis":"Gambling disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-39', 'Aarav: the game squad at 10 pm (gaming disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-39-1","text":"Parents'' sudden router shutdowns lead to fights","bucket":"perpetuating"},{"id":"form-39-2","text":"His bedroom has blue walls","bucket":"distractor"},{"id":"form-39-3","text":"Both parents work long hours","bucket":"predisposing"},{"id":"form-39-4","text":"Interested in coding","bucket":"protective"},{"id":"form-39-5","text":"Plays 8 to 10 hours daily and has not attended school for a month","bucket":"presenting"},{"id":"form-39-6","text":"Shy child with few friends","bucket":"predisposing"},{"id":"form-39-7","text":"Aggressive when the internet is cut","bucket":"presenting"},{"id":"form-39-8","text":"Sleeps through mornings, so school feels impossible","bucket":"perpetuating"},{"id":"form-39-9","text":"Online squad is his only social contact","bucket":"perpetuating"},{"id":"form-39-10","text":"Responds to a counsellor who asks about the game","bucket":"protective"},{"id":"form-39-11","text":"Moved to a new school where he knows no one","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aarav, 15, presents with gaming disorder: very long daily play, school refusal for a month and aggression when access is cut. A shy temperament and long parental work hours (predisposing) left him with little offline connection; moving to a new school without friends (precipitating) pushed him online. An online squad as his only social world, reversed sleep and abrupt router shutdowns (perpetuating) maintain the pattern. Interest in coding and responsiveness to curious adults (protective) support family work, a gradual sleep and school plan and building offline friendships.","hint":"A 15-year-old who stopped going to school","tags":{"topic":"substance","difficulty":3,"objective":"Show loneliness behind a behavioural addiction","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Gaming disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-40', 'Tanvi: the girl in the group chat (adolescent low mood and bullying)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-40-1","text":"Cries after checking her phone","bucket":"presenting"},{"id":"form-40-2","text":"Avoids school, where the teasing happens","bucket":"perpetuating"},{"id":"form-40-3","text":"Low mood, staying in her room and falling marks for two months","bucket":"presenting"},{"id":"form-40-4","text":"Keeps checking the group at night","bucket":"perpetuating"},{"id":"form-40-5","text":"Edited photos of her shared in a class group chat","bucket":"precipitating"},{"id":"form-40-6","text":"Parents who are concerned and willing","bucket":"protective"},{"id":"form-40-7","text":"Recent move away from her close friends","bucket":"predisposing"},{"id":"form-40-8","text":"Her school uniform is maroon","bucket":"distractor"},{"id":"form-40-9","text":"Sensitive temperament","bucket":"predisposing"},{"id":"form-40-10","text":"Trusting relationship with her class teacher","bucket":"protective"},{"id":"form-40-11","text":"Fear her parents will take her phone stops her telling them","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tanvi, 15, presents with a mild depressive episode in the context of cyberbullying: low mood, withdrawal and falling marks. A sensitive temperament and the loss of close friends after a move (predisposing) left her isolated; edited photos shared in a class group (precipitating) began it. Night-time checking, secrecy for fear of losing her phone and school avoidance (perpetuating) keep it going. A trusted teacher and caring parents (protective) support a plan of school action against the bullying, a safety check, and supportive therapy with agreed limits on phone use.","hint":"A 15-year-old whose marks fell after online teasing","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate an adolescent''s distress with school and online factors","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Depressive episode, mild, in the context of cyberbullying"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-41', 'Ishaan: the boy who won''t go to school (school refusal)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-41-1","text":"Stomach aches and crying every school morning for two months","bucket":"presenting"},{"id":"form-41-2","text":"Mother also anxious","bucket":"predisposing"},{"id":"form-41-3","text":"Each missed day makes returning harder","bucket":"perpetuating"},{"id":"form-41-4","text":"Father willing to do the school drop","bucket":"protective"},{"id":"form-41-5","text":"Likes his class teacher","bucket":"protective"},{"id":"form-41-6","text":"His favourite colour is orange","bucket":"distractor"},{"id":"form-41-7","text":"Mother was in hospital for a week with dengue","bucket":"precipitating"},{"id":"form-41-8","text":"Missed 20 days of school","bucket":"presenting"},{"id":"form-41-9","text":"Clingy, anxious temperament from toddlerhood","bucket":"predisposing"},{"id":"form-41-10","text":"Allowed to stay home when he cries, with TV and snacks","bucket":"perpetuating"},{"id":"form-41-11","text":"Mother checks on him by phone from work all day","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ishaan, 10, presents with school refusal driven by separation anxiety: morning stomach aches, crying and many missed days. An anxious, clingy temperament and an anxious mother (predisposing) set the ground; his mother''s hospital stay with dengue (precipitating) made separation feel dangerous. Comfortable days at home, mounting missed work and frequent phone checking (perpetuating) reward avoidance. A liked class teacher and a father willing to do drop-offs (protective) support a graded return plan with the school, making home days dull and coaching the mother to tolerate his distress.","hint":"A 10-year-old with stomach aches every Monday","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Show how staying home rewards avoidance","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"School refusal with separation anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-42', 'Arjun: the boy who can''t sit still in class (ADHD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-42-1","text":"Father had similar problems as a boy","bucket":"predisposing"},{"id":"form-42-2","text":"Daily scolding and punishment lower his self-esteem","bucket":"perpetuating"},{"id":"form-42-3","text":"Screen time late at night reduces sleep","bucket":"perpetuating"},{"id":"form-42-4","text":"Very good at football and drawing","bucket":"protective"},{"id":"form-42-5","text":"Born premature at 33 weeks","bucket":"predisposing"},{"id":"form-42-6","text":"He was born in Jaipur","bucket":"distractor"},{"id":"form-42-7","text":"Falling behind in reading","bucket":"presenting"},{"id":"form-42-8","text":"Grandmother who praises him","bucket":"protective"},{"id":"form-42-9","text":"Teacher seats him at the back","bucket":"perpetuating"},{"id":"form-42-10","text":"Restless, impulsive and easily distracted at home and school since age 4","bucket":"presenting"},{"id":"form-42-11","text":"Moved to a stricter school with longer seated lessons","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 8, presents with ADHD, combined presentation: restlessness, impulsivity and distractibility across settings since early childhood, now affecting reading. A family history and prematurity (predisposing) raise his risk; a stricter school with longer seated lessons (precipitating) made the difficulties more visible. Constant punishment, late screens that cut sleep and being seated at the back (perpetuating) worsen behaviour and self-esteem. Talent in football and drawing and a praising grandmother (protective) support parent training, school adjustments and, if needed, medicine.","hint":"An 8-year-old the teacher calls naughty","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort a neurodevelopmental presentation into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Attention-deficit hyperactivity disorder, combined presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-43', 'Riya: the girl who lines up her toys (autism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-43-1","text":"Limited speech, little eye contact and no pretend play","bucket":"presenting"},{"id":"form-43-2","text":"Long screen time in place of interaction","bucket":"perpetuating"},{"id":"form-43-3","text":"Starting playschool made differences obvious","bucket":"precipitating"},{"id":"form-43-4","text":"The family''s flat is near a temple","bucket":"distractor"},{"id":"form-43-5","text":"Parents now motivated and informed","bucket":"protective"},{"id":"form-43-6","text":"Strong memory for numbers and songs","bucket":"protective"},{"id":"form-43-7","text":"Elder cousin with autism","bucket":"predisposing"},{"id":"form-43-8","text":"Early signs noticed from 18 months","bucket":"predisposing"},{"id":"form-43-9","text":"Grandparents fear stigma and resist assessment","bucket":"perpetuating"},{"id":"form-43-10","text":"Distress when routines change; lines up toys","bucket":"presenting"},{"id":"form-43-11","text":"Family told ''she''ll talk late, wait'' delayed help","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Riya, 4, presents with autism spectrum disorder: limited speech, reduced social reciprocity, no pretend play, rigid routines and repetitive play. A family history (predisposing) suggests genetic vulnerability; starting playschool (precipitating) made her differences clear rather than causing them. Advice to wait, long screen time and family stigma (perpetuating) have delayed early intervention. Her memory for songs and numbers and newly motivated parents (protective) support early intervention with speech and occupational therapy and parent-mediated play.","hint":"A 4-year-old with few words and strong routines","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate autism with strengths and family needs","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Autism spectrum disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-44', 'Sunita: the baby and the thoughts she can''t say (postpartum depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-44-1","text":"Unwanted images of the baby being hurt that horrify her","bucket":"presenting"},{"id":"form-44-2","text":"Difficult delivery and a week of NICU care for the baby","bucket":"precipitating"},{"id":"form-44-3","text":"Avoids bathing the baby alone because of the thoughts","bucket":"perpetuating"},{"id":"form-44-4","text":"Sleeps three hours a night","bucket":"perpetuating"},{"id":"form-44-5","text":"Husband who takes leave to help","bucket":"protective"},{"id":"form-44-6","text":"Low mood, tearfulness and exhaustion for six weeks","bucket":"presenting"},{"id":"form-44-7","text":"Bonded with the baby and breastfeeding well","bucket":"protective"},{"id":"form-44-8","text":"Previous anxiety in college","bucket":"predisposing"},{"id":"form-44-9","text":"Perfectionistic standards for herself","bucket":"predisposing"},{"id":"form-44-10","text":"The hospital was in another district","bucket":"distractor"},{"id":"form-44-11","text":"Hides the thoughts for fear the baby will be taken away","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunita, 28, presents with a postpartum depressive episode with intrusive obsessional thoughts: low mood and exhaustion with horrifying, unwanted images of harm to her baby that she avoids and hides. Past anxiety and perfectionism (predisposing) increased her vulnerability; a difficult delivery with NICU care (precipitating) began it. Avoidance, secrecy for fear of losing the baby and severe sleep loss (perpetuating) maintain both mood and thoughts. Her bond with the baby and a supportive husband (protective) are strengths; the plan explains that these thoughts are not intentions, assesses risk carefully, protects sleep and treats both conditions.","hint":"A mother eight weeks after delivery with intrusive harm thoughts","tags":{"topic":"perinatal","difficulty":4,"objective":"Separate intrusive harm thoughts from intent in a perinatal formulation","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Postpartum depressive episode with intrusive obsessional thoughts"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-45', 'Anita: certain the baby is not hers (postpartum psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-45-1","text":"Continued sleep loss with night feeds","bucket":"perpetuating"},{"id":"form-45-2","text":"Husband who called the doctor","bucket":"protective"},{"id":"form-45-3","text":"Bipolar disorder diagnosed at 24, stopped treatment before pregnancy","bucket":"predisposing"},{"id":"form-45-4","text":"Childbirth with severe sleep loss over four nights","bucket":"precipitating"},{"id":"form-45-5","text":"Rapidly changing mood, at times elated","bucket":"presenting"},{"id":"form-45-6","text":"The baby was born on a Tuesday","bucket":"distractor"},{"id":"form-45-7","text":"From day five after delivery, confused, sleepless, believes the baby was swapped","bucket":"presenting"},{"id":"form-45-8","text":"Family believe it is the evil eye and plan a ritual first","bucket":"perpetuating"},{"id":"form-45-9","text":"Obstetric team alert to the change","bucket":"protective"},{"id":"form-45-10","text":"Mother had a ''breakdown'' after childbirth","bucket":"predisposing"},{"id":"form-45-11","text":"No psychiatric plan made during pregnancy","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anita, 30, presents with postpartum psychosis: from day five, confusion, sleeplessness, rapid mood change and a delusion that her baby was swapped. Known bipolar disorder off treatment and a mother with a similar postpartum illness (predisposing) made her very high risk; childbirth with severe sleep loss (precipitating) triggered the episode. Family belief in the evil eye with delay for a ritual, continuing sleep loss and no pregnancy plan (perpetuating) increase danger to her and the baby. A husband who acted and an alert obstetric team (protective) allow urgent admission, ideally to a mother and baby setting, with treatment and close safety for both.","hint":"A new mother sleepless and confused on day five","tags":{"topic":"perinatal","difficulty":5,"objective":"Formulate a perinatal psychiatric emergency","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Postpartum psychosis (likely bipolar spectrum)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-46', 'Mr Dsouza: the mind that started slipping (Alzheimer''s dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-46-1","text":"Hearing loss limits conversation","bucket":"perpetuating"},{"id":"form-46-2","text":"Untreated hearing loss and high blood pressure","bucket":"predisposing"},{"id":"form-46-3","text":"Repeats questions; struggles with bills","bucket":"presenting"},{"id":"form-46-4","text":"Two years of worsening memory for recent events; got lost on his usual walk","bucket":"presenting"},{"id":"form-46-5","text":"Social isolation since he stopped visiting the club","bucket":"perpetuating"},{"id":"form-46-6","text":"Enjoys music and his garden","bucket":"protective"},{"id":"form-46-7","text":"Family correct and argue with him, causing distress","bucket":"perpetuating"},{"id":"form-46-8","text":"He worked on the Konkan railway","bucket":"distractor"},{"id":"form-46-9","text":"Devoted daughter nearby","bucket":"protective"},{"id":"form-46-10","text":"Age 76; mother had memory problems late in life","bucket":"predisposing"},{"id":"form-46-11","text":"Decline became obvious after his wife was hospitalised and his routine broke","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Dsouza, 76, presents with mild dementia due to Alzheimer''s disease: two years of progressive recent memory loss, getting lost and difficulty with finances. Age, a family history and untreated hearing loss and blood pressure (predisposing) raise his risk; his wife''s admission broke his routine and unmasked the decline (precipitating). Isolation, hearing loss and arguments when he forgets (perpetuating) worsen function and mood. A devoted daughter and his love of music and gardening (protective) support a plan of medical review, hearing aids, routine, carer education and future planning while he has capacity.","hint":"A retired engineer lost on his usual walk","tags":{"topic":"neurocognitive","difficulty":2,"objective":"Formulate early dementia with carer factors","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"neurocognitive","diagnosis":"Mild dementia due to Alzheimer''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-47', 'Mrs Kapoor: confused since the urine infection (delirium)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-47-1","text":"Age 82 with mild memory problems","bucket":"predisposing"},{"id":"form-47-2","text":"Dehydrated; drinking little water","bucket":"perpetuating"},{"id":"form-47-3","text":"Urinary tract infection with fever","bucket":"precipitating"},{"id":"form-47-4","text":"Poor eyesight from cataracts","bucket":"predisposing"},{"id":"form-47-5","text":"Sudden confusion over two days, worse at night","bucket":"presenting"},{"id":"form-47-6","text":"Sees children in her room; drowsy by day","bucket":"presenting"},{"id":"form-47-7","text":"Her son''s flat is on the fifth floor","bucket":"distractor"},{"id":"form-47-8","text":"Moved to an unfamiliar room at her son''s flat","bucket":"perpetuating"},{"id":"form-47-9","text":"Family noticed the sudden change","bucket":"protective"},{"id":"form-47-10","text":"Good recovery after a past infection","bucket":"protective"},{"id":"form-47-11","text":"Given a sleeping tablet at night by a relative","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Kapoor, 82, presents with delirium: two days of fluctuating confusion, night-time worsening, drowsiness and visual hallucinations. Age, mild cognitive impairment and poor eyesight (predisposing) leave her brain vulnerable; a urinary infection with fever (precipitating) triggered it. A sedative tablet, dehydration and an unfamiliar room (perpetuating) prolong the confusion. A family who spotted the sudden change and her past recovery (protective) support treating the infection, stopping the sedative, fluids, glasses and a calm, familiar setting.","hint":"An 82-year-old suddenly seeing children in her room","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Formulate an acute confusional state","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Delirium due to urinary tract infection"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-48', 'Anil: the colleague who changed after the accident (frontal head injury)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-48-1","text":"Family argue with him as if he chooses to behave badly","bucket":"perpetuating"},{"id":"form-48-2","text":"Impulsive, irritable and socially inappropriate since a bike accident","bucket":"presenting"},{"id":"form-48-3","text":"No prior psychiatric illness","bucket":"predisposing"},{"id":"form-48-4","text":"No structured rehabilitation after discharge","bucket":"perpetuating"},{"id":"form-48-5","text":"Poor planning; lost his job","bucket":"presenting"},{"id":"form-48-6","text":"Wife committed to him","bucket":"protective"},{"id":"form-48-7","text":"No helmet habit; risk-taking as a young man","bucket":"predisposing"},{"id":"form-48-8","text":"His bike was a red model","bucket":"distractor"},{"id":"form-48-9","text":"Retains good practical skills with machines","bucket":"protective"},{"id":"form-48-10","text":"Head injury with frontal contusions in a road accident a year ago","bucket":"precipitating"},{"id":"form-48-11","text":"Drinks at weekends, which worsens control","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anil, 34, presents with personality change due to a frontal brain injury: impulsivity, irritability, social disinhibition and poor planning since a road accident. Risk-taking without a helmet (predisposing) set the stage; the frontal injury (precipitating) caused the change. Family misunderstanding of the behaviour as chosen, weekend drinking and absent rehabilitation (perpetuating) worsen it. A committed wife and preserved practical skills (protective) support neuropsychological rehabilitation, family education, alcohol abstinence and supported work.","hint":"A once-gentle man now crude and impulsive","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Formulate personality change after brain injury","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"brain","diagnosis":"Personality change due to traumatic brain injury (frontal)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-49', 'Mansi: three hours without a text (borderline personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-49-1","text":"Mood shifts within hours triggered by fear of abandonment","bucket":"presenting"},{"id":"form-49-2","text":"Self-harm brings quick relief, which reinforces it","bucket":"perpetuating"},{"id":"form-49-3","text":"Parents'' bitter divorce and an emotionally unavailable mother","bucket":"predisposing"},{"id":"form-49-4","text":"Previously labelled bipolar and given medicines that did not help","bucket":"perpetuating"},{"id":"form-49-5","text":"Keeps attending appointments","bucket":"protective"},{"id":"form-49-6","text":"Binge drinking when distressed","bucket":"perpetuating"},{"id":"form-49-7","text":"She studies at a business school","bucket":"distractor"},{"id":"form-49-8","text":"Strong academic ability","bucket":"protective"},{"id":"form-49-9","text":"Partner was late replying during a fight","bucket":"precipitating"},{"id":"form-49-10","text":"Cuts her thighs and has chronic emptiness","bucket":"presenting"},{"id":"form-49-11","text":"Sensitive, intense temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mansi, 23, presents with borderline personality disorder: rapid mood shifts tied to fears of abandonment, self-harm and chronic emptiness. An invalidating early environment through her parents'' divorce and an intense temperament (predisposing) shaped her emotional sensitivity; a partner''s delayed reply in a fight (precipitating) triggered the latest crisis. Self-harm as fast relief, binge drinking and a past misdiagnosis with ineffective medicines (perpetuating) keep the pattern going. Her engagement and ability (protective) support a safety plan and a structured therapy such as dialectical behaviour therapy.","hint":"A 23-year-old whose moods swing within hours","tags":{"topic":"personality","difficulty":4,"objective":"Formulate a personality disorder with self-harm","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"personality","diagnosis":"Borderline personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-50', 'Shalini: the friend she has never met (avoidant personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-50-1","text":"Avoids meeting her online friend, so never tests her fears","bucket":"perpetuating"},{"id":"form-50-2","text":"Reliable, skilled worker","bucket":"protective"},{"id":"form-50-3","text":"Offered a team-lead promotion, which she refused","bucket":"precipitating"},{"id":"form-50-4","text":"Shy, inhibited temperament","bucket":"predisposing"},{"id":"form-50-5","text":"Lifelong fear of rejection with avoidance of jobs and relationships","bucket":"presenting"},{"id":"form-50-6","text":"A six-year online friendship","bucket":"protective"},{"id":"form-50-7","text":"Critical father who called her useless","bucket":"predisposing"},{"id":"form-50-8","text":"She types at 90 words a minute","bucket":"distractor"},{"id":"form-50-9","text":"Wants friends but believes she is boring","bucket":"presenting"},{"id":"form-50-10","text":"Work-from-home job removes contact","bucket":"perpetuating"},{"id":"form-50-11","text":"Interprets neutral reactions as rejection","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shalini, 32, presents with avoidant personality disorder: lifelong fear of rejection, feelings of inadequacy and avoidance of roles and relationships she wants. A critical father and an inhibited temperament (predisposing) shaped a core belief of being unlikeable; a promotion offer (precipitating) brought the pattern into focus. Isolation through home working, avoidance of testing her fears and reading neutral cues as rejection (perpetuating) maintain it. A long online friendship and her reliability at work (protective) support schema-focused or CBT work with gradual social exposure.","hint":"A transcriptionist who refused promotion","tags":{"topic":"personality","difficulty":3,"objective":"Formulate a lifelong avoidant pattern","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Avoidant personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-51', 'Zoya: twelve hours of sleep and a broken engagement (atypical depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-51-1","text":"Cancels plans when friends reply late, so she grows isolated","bucket":"perpetuating"},{"id":"form-51-2","text":"Agrees with the ''moody'' label and criticises herself","bucket":"perpetuating"},{"id":"form-51-3","text":"Close grandmother","bucket":"protective"},{"id":"form-51-4","text":"Low mood that brightens with good news, oversleeping and eating more","bucket":"presenting"},{"id":"form-51-5","text":"Similar spell after board exams","bucket":"predisposing"},{"id":"form-51-6","text":"Long-standing sensitivity to rejection","bucket":"predisposing"},{"id":"form-51-7","text":"Heavy, leaden limbs","bucket":"presenting"},{"id":"form-51-8","text":"Engagement broken by the groom''s family, who called her ''moody''","bucket":"precipitating"},{"id":"form-51-9","text":"Night-time sweet binges and long sleep worsen energy","bucket":"perpetuating"},{"id":"form-51-10","text":"Work she is good at and gets praise for","bucket":"protective"},{"id":"form-51-11","text":"She lives in a house with a courtyard","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Zoya, 24, presents with a depressive episode with atypical features: mood reactivity, oversleeping, increased appetite, leaden limbs and rejection sensitivity. Long-standing sensitivity to rejection and an earlier episode (predisposing) set the vulnerability; the broken engagement with a hurtful label (precipitating) triggered it. Withdrawal after perceived rejection, night eating and oversleeping and self-criticism (perpetuating) maintain it. Rewarding work and a close grandmother (protective) support treatment that includes activity scheduling, regular sleep and work on rejection sensitivity, with screening for bipolarity.","hint":"A writer whose mood lifts with praise then crashes","tags":{"topic":"depression","difficulty":3,"objective":"Formulate atypical features and rejection sensitivity","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode with atypical features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-52', 'Sanjay: the cardiologist sent him (depression after a heart attack)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-52-1","text":"Low mood, fatigue and poor sleep since a heart attack two months ago","bucket":"presenting"},{"id":"form-52-2","text":"His car is a white sedan","bucket":"distractor"},{"id":"form-52-3","text":"Smoker with diabetes","bucket":"predisposing"},{"id":"form-52-4","text":"Skips medicines on low days","bucket":"perpetuating"},{"id":"form-52-5","text":"Stopped cardiac rehabilitation sessions","bucket":"presenting"},{"id":"form-52-6","text":"Withdrawn from friends who ''treat him like an invalid''","bucket":"perpetuating"},{"id":"form-52-7","text":"Heart attack two months ago","bucket":"precipitating"},{"id":"form-52-8","text":"Wife who attends rehab with him","bucket":"protective"},{"id":"form-52-9","text":"Fear that exercise will cause another attack","bucket":"perpetuating"},{"id":"form-52-10","text":"Previous low spell after his business failed","bucket":"predisposing"},{"id":"form-52-11","text":"Grandchild born last month","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sanjay, 55, presents with a depressive episode two months after a heart attack: low mood, fatigue and poor sleep, with dropping out of cardiac rehabilitation. Vascular risk factors and an earlier depressive spell (predisposing) raised his risk; the heart attack (precipitating) triggered the episode. Fear of exercise, missed medicines and social withdrawal (perpetuating) maintain low mood and threaten his heart health. A supportive wife and a new grandchild (protective) give motivation for treatment that is safe in heart disease, return to rehab and risk-factor work.","hint":"A 55-year-old who stopped cardiac rehab","tags":{"topic":"depression","difficulty":3,"objective":"Formulate depression that worsens a medical outcome","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode after myocardial infarction"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-53', 'Lalitha: ten years on the chemist''s tablet (benzodiazepine dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-53-1","text":"She makes excellent rasam","bucket":"distractor"},{"id":"form-53-2","text":"Dose increased during her daughter''s wedding preparations","bucket":"precipitating"},{"id":"form-53-3","text":"Chemist supplies without prescription","bucket":"perpetuating"},{"id":"form-53-4","text":"Daughters'' scolding increases shame and secrecy","bucket":"perpetuating"},{"id":"form-53-5","text":"Willing to try a slow plan","bucket":"protective"},{"id":"form-53-6","text":"Takes three alprazolam tablets daily for ten years","bucket":"presenting"},{"id":"form-53-7","text":"Started after her mother''s death on a doctor''s prescription","bucket":"predisposing"},{"id":"form-53-8","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-53-9","text":"Anxious and shaky when she misses doses; recent night fall","bucket":"presenting"},{"id":"form-53-10","text":"Withdrawal symptoms feel like proof she needs it","bucket":"perpetuating"},{"id":"form-53-11","text":"Daughters who want her well","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lalitha, 55, presents with benzodiazepine dependence: ten years of alprazolam with dose escalation, withdrawal on missing doses and a fall. An anxious temperament and starting the tablet in grief (predisposing) shaped the pattern; dose increases during wedding stress (precipitating) deepened dependence. Easy chemist supply, withdrawal mistaken for ''needing it'' and shame from family scolding (perpetuating) maintain it. Daughters who care and her willingness (protective) support a slow, supervised taper with psychological treatment for anxiety and fall prevention.","hint":"A homemaker who fell at night","tags":{"topic":"substance","difficulty":3,"objective":"Formulate iatrogenic dependence","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Benzodiazepine dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-54', 'Nikhil: the antidepressant that made him fly (switch to mania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-54-1","text":"Wife who noticed early","bucket":"protective"},{"id":"form-54-2","text":"SSRI started for depression six weeks ago","bucket":"precipitating"},{"id":"form-54-3","text":"Irritable at home","bucket":"presenting"},{"id":"form-54-4","text":"No mood stabiliser; the antidepressant continues","bucket":"perpetuating"},{"id":"form-54-5","text":"Past summer of little sleep and many projects at 24","bucket":"predisposing"},{"id":"form-54-6","text":"Values his job","bucket":"protective"},{"id":"form-54-7","text":"Praise from some staff reinforces him","bucket":"perpetuating"},{"id":"form-54-8","text":"Father with mood problems","bucket":"predisposing"},{"id":"form-54-9","text":"The school has 1,200 pupils","bucket":"distractor"},{"id":"form-54-10","text":"Lack of sleep feeds the high","bucket":"perpetuating"},{"id":"form-54-11","text":"Elated, sleeping three hours, pressured speech and spending for ten days","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nikhil, 35, presents with a manic episode after starting an antidepressant: elation, little sleep, pressured speech and spending. A past unrecognised hypomanic summer and a family history of mood problems (predisposing) point to underlying bipolar disorder; the SSRI (precipitating) triggered the switch. Continuing the antidepressant without a mood stabiliser, praise that rewards the high and ongoing sleep loss (perpetuating) maintain it. An observant wife and his commitment to his job (protective) support urgent review, stopping the antidepressant, mood stabilisation and protecting sleep.","hint":"A vice-principal giving 40-minute assembly speeches","tags":{"topic":"bipolar","difficulty":4,"objective":"Place a missed history and medicine as the drivers of mania","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar I disorder, manic episode after antidepressant"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-55', 'Mrs Pereira: the drilling through the wall (late-onset psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-55-1","text":"Significant hearing loss for years","bucket":"predisposing"},{"id":"form-55-2","text":"Never married; reserved and private","bucket":"predisposing"},{"id":"form-55-3","text":"Hears them plotting at night","bucket":"presenting"},{"id":"form-55-4","text":"Conflict with neighbours confirms her fears","bucket":"perpetuating"},{"id":"form-55-5","text":"Talks to almost no one","bucket":"perpetuating"},{"id":"form-55-6","text":"Sister''s death left her alone in the flat","bucket":"precipitating"},{"id":"form-55-7","text":"Independent and cognitively intact","bucket":"protective"},{"id":"form-55-8","text":"Church community that cares","bucket":"protective"},{"id":"form-55-9","text":"No hearing aid, so sounds are misheard","bucket":"perpetuating"},{"id":"form-55-10","text":"Belief that neighbours drill through the wall and pump gas","bucket":"presenting"},{"id":"form-55-11","text":"She keeps her flat very tidy","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Pereira, 59, presents with a very late-onset schizophrenia-like psychosis: persecutory beliefs about neighbours and voices plotting at night, with intact cognition. Long-standing hearing loss and a reserved personality (predisposing) increase risk; her sister''s death and isolation (precipitating) preceded onset. No hearing aid, social isolation and confirming conflicts with neighbours (perpetuating) maintain it. Her independence and church community (protective) support a plan of hearing assessment, social contact, a low-dose antipsychotic and practical help with the housing society.","hint":"A retired telephone operator who lives alone and cannot hear well","tags":{"topic":"psychosis","difficulty":4,"objective":"Show sensory loss and isolation as formulation factors","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Very late-onset schizophrenia-like psychosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-56', 'Gita: the retired principal who rests too much (late-life depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-56-1","text":"Stopped meeting friends, gardening and answering calls for eight months","bucket":"presenting"},{"id":"form-56-2","text":"Daughter who flew in to help","bucket":"protective"},{"id":"form-56-3","text":"Identity built around her work as a principal","bucket":"predisposing"},{"id":"form-56-4","text":"She owns a collection of cookbooks","bucket":"distractor"},{"id":"form-56-5","text":"Widowed five years ago","bucket":"predisposing"},{"id":"form-56-6","text":"Phone on silent; isolation deepens","bucket":"perpetuating"},{"id":"form-56-7","text":"A doctor called it ''age'' and gave a vitamin injection","bucket":"perpetuating"},{"id":"form-56-8","text":"Weight loss and saying she ''wouldn''t mind'' not waking","bucket":"presenting"},{"id":"form-56-9","text":"Retirement eight months ago","bucket":"precipitating"},{"id":"form-56-10","text":"Believes rest is what she has earned so does not complain","bucket":"perpetuating"},{"id":"form-56-11","text":"Old students who still visit","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gita, 52, presents with a moderate depressive episode: eight months of withdrawal, loss of interest, weight loss and passive death wishes. An identity built on work and widowhood (predisposing) left retirement as a major loss; retirement itself (precipitating) began the slide. Her belief that she has earned rest, isolation with the phone silenced and a doctor''s dismissal as age (perpetuating) delayed help. A daughter who came and old students who visit (protective) support a plan with a risk assessment, treatment and rebuilding meaningful activity.","hint":"A widow whose daughter flew in from Chennai","tags":{"topic":"depression","difficulty":1,"objective":"Sort late-life depression after retirement into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-57', 'Lakshmi: the fits that come at her in-laws'' house (dissociative seizures)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-57-1","text":"Normal video EEG during an episode","bucket":"presenting"},{"id":"form-57-2","text":"Learned early to stay silent about distress","bucket":"predisposing"},{"id":"form-57-3","text":"Close sister she trusts","bucket":"protective"},{"id":"form-57-4","text":"Episodes bring a break from household demands and family concern","bucket":"perpetuating"},{"id":"form-57-5","text":"Mother-in-law''s criticism continues daily","bucket":"perpetuating"},{"id":"form-57-6","text":"Sexual abuse by a relative in childhood, never disclosed","bucket":"predisposing"},{"id":"form-57-7","text":"The wedding was held in a garden venue","bucket":"distractor"},{"id":"form-57-8","text":"Repeated anticonvulsant changes signal ''epilepsy'' to everyone","bucket":"perpetuating"},{"id":"form-57-9","text":"Episodes of falling, shaking with eyes tightly shut and crying, several a week","bucket":"presenting"},{"id":"form-57-10","text":"Married eight months ago and moved to a strict joint family","bucket":"precipitating"},{"id":"form-57-11","text":"Husband who wants to understand","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lakshmi, 22, presents with dissociative seizures: frequent episodes with closed eyes, crying and shaking, with a normal EEG during an attack. Undisclosed childhood sexual abuse and a lifelong habit of silence about distress (predisposing) shaped a tendency to dissociate under overwhelming stress; marriage into a critical joint family (precipitating) came before onset. Relief from demands during episodes, repeated anticonvulsant changes that confirm an epilepsy label and daily criticism (perpetuating) keep them going. A husband who wants to understand and a trusted sister (protective) support a clear, non-blaming explanation, tapering unneeded anticonvulsants, psychological therapy and safe exploration of past trauma.","hint":"A young bride whose ''fits'' have normal EEGs","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate dissociative seizures with family conflict","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Dissociative (functional) seizures"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-58', 'Deepak: the gap in Tuesday (dissociative amnesia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-58-1","text":"He drives a company car","bucket":"distractor"},{"id":"form-58-2","text":"Childhood with a violent father; ''switched off'' during beatings","bucket":"predisposing"},{"id":"form-58-3","text":"Knows who he is but cannot recall the trip","bucket":"presenting"},{"id":"form-58-4","text":"Fear of police makes him reluctant to recall","bucket":"perpetuating"},{"id":"form-58-5","text":"Company accused him of fraud a day before he vanished","bucket":"precipitating"},{"id":"form-58-6","text":"Avoids any discussion of the accusation","bucket":"perpetuating"},{"id":"form-58-7","text":"Avoidant coping style","bucket":"predisposing"},{"id":"form-58-8","text":"Family pressure to ''just remember''","bucket":"perpetuating"},{"id":"form-58-9","text":"Normal brain scan and no alcohol or drugs","bucket":"protective"},{"id":"form-58-10","text":"Wife who stands by him","bucket":"protective"},{"id":"form-58-11","text":"Found in Nagpur with no memory of travelling from Pune two days earlier","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Deepak, 38, presents with dissociative amnesia with fugue: purposeful travel to another city with a two-day memory gap and no organic cause found. A childhood of violence where he learned to switch off (predisposing) shaped a dissociative response to unbearable stress; a fraud accusation the day before (precipitating) triggered it. Avoidance of the accusation, fear of legal consequences and family pressure to remember (perpetuating) keep the gap closed. A normal medical work-up and a supportive wife (protective) allow a safe, unhurried therapy that addresses the stressor first and does not force recall.","hint":"A sales executive found in another city with no memory of the trip","tags":{"topic":"trauma","difficulty":5,"objective":"Formulate dissociative amnesia and rule out organic causes","exams":["md-psychiatry","ugc-net"],"module":"trauma","diagnosis":"Dissociative amnesia with dissociative fugue"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-59', 'Rahul: the white discharge and the weakness (dhat syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-59-1","text":"Avoids talking to anyone about it from shame","bucket":"perpetuating"},{"id":"form-59-2","text":"Guilt about masturbation from his teens","bucket":"predisposing"},{"id":"form-59-3","text":"Checks his urine every morning","bucket":"perpetuating"},{"id":"form-59-4","text":"Spends money on costly herbal tonics","bucket":"perpetuating"},{"id":"form-59-5","text":"Low mood, fatigue and poor concentration","bucket":"presenting"},{"id":"form-59-6","text":"Worry that he loses semen in urine, causing weakness and poor memory","bucket":"presenting"},{"id":"form-59-7","text":"Close friend who encouraged him","bucket":"protective"},{"id":"form-59-8","text":"Came to a general doctor on his own","bucket":"protective"},{"id":"form-59-9","text":"A roadside ''sex clinic'' told him his weakness came from semen loss","bucket":"precipitating"},{"id":"form-59-10","text":"Cultural belief that semen is vital strength","bucket":"predisposing"},{"id":"form-59-11","text":"He is studying for a B.Com degree","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rahul, 22, presents with dhat syndrome: distress about supposed loss of semen in urine, attributed weakness and poor memory, with low mood and anxiety. Cultural beliefs about semen as vital strength and guilt about masturbation (predisposing) made the worry likely; a roadside clinic''s frightening explanation (precipitating) intensified it. Costly tonics, daily urine checking and secrecy (perpetuating) maintain it. His own help-seeking and a supportive friend (protective) allow respectful sex education, correction of myths without ridicule, and treatment of the anxiety and low mood.","hint":"A 22-year-old certain he is losing vital fluid","tags":{"topic":"culture","difficulty":3,"objective":"Formulate a culture-bound distress with depression and anxiety","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"more-disorders","diagnosis":"Dhat syndrome with anxiety and low mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-60', 'Pradeep: performance worry after one bad night (erectile difficulty)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-60-1","text":"Bought online pills without seeing a doctor","bucket":"perpetuating"},{"id":"form-60-2","text":"Little sex education; learned from pornography","bucket":"predisposing"},{"id":"form-60-3","text":"Normal physical health","bucket":"protective"},{"id":"form-60-4","text":"Avoids intimacy, which worries his wife","bucket":"perpetuating"},{"id":"form-60-5","text":"Watches himself anxiously during sex (spectatoring)","bucket":"perpetuating"},{"id":"form-60-6","text":"Loses his erection during intercourse for three months","bucket":"presenting"},{"id":"form-60-7","text":"Wife who is patient and willing to join sessions","bucket":"protective"},{"id":"form-60-8","text":"Failed on the first night after the wedding when both were exhausted","bucket":"precipitating"},{"id":"form-60-9","text":"Their wedding had 900 guests","bucket":"distractor"},{"id":"form-60-10","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-60-11","text":"Normal morning erections","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pradeep, 29, presents with psychogenic erectile disorder: three months of losing erections during intercourse with normal morning erections. An anxious temperament and poor sex education with unrealistic expectations (predisposing) set the ground; a failure on the exhausting wedding night (precipitating) began the worry. Anxious self-monitoring, unsupervised online pills and avoidance of intimacy (perpetuating) maintain the cycle. A patient wife and good physical health (protective) support couple-based sex therapy with sensate focus and accurate education.","hint":"A newly married man afraid of failing again","tags":{"topic":"sexual","difficulty":2,"objective":"Show performance anxiety as a maintaining cycle","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"more-disorders","diagnosis":"Erectile disorder, psychogenic, situational"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-61', 'Kunal: stuck between two hearts (hoarding disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-61-1","text":"Flat filled with newspapers, bags and broken items so rooms cannot be used","bucket":"presenting"},{"id":"form-61-2","text":"Feels each object holds memories of his wife","bucket":"perpetuating"},{"id":"form-61-3","text":"Son who visits weekly","bucket":"protective"},{"id":"form-61-4","text":"Clutter worsened after his wife died and nobody else cleared things","bucket":"precipitating"},{"id":"form-61-5","text":"Indecisive and perfectionistic","bucket":"predisposing"},{"id":"form-61-6","text":"Believes items may be needed one day","bucket":"perpetuating"},{"id":"form-61-7","text":"His building is forty years old","bucket":"distractor"},{"id":"form-61-8","text":"Neighbours'' complaints make him defensive and secretive","bucket":"perpetuating"},{"id":"form-61-9","text":"Severe distress at the thought of discarding","bucket":"presenting"},{"id":"form-61-10","text":"Agrees the clutter is a fire risk","bucket":"protective"},{"id":"form-61-11","text":"Grew up in poverty where nothing was wasted","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kunal, 67, presents with hoarding disorder: a flat so full that rooms cannot be used and great distress about discarding. A childhood of poverty and an indecisive, perfectionistic style (predisposing) shaped strong beliefs about waste; his wife''s death (precipitating) removed the person who cleared things and gave objects new emotional weight. Beliefs about future need, attachment of memories to objects and defensiveness after complaints (perpetuating) maintain it. A visiting son and his recognition of fire risk (protective) support CBT for hoarding with practice in sorting and discarding at his pace, and a safety plan.","hint":"A retired clerk whose flat is full to the ceiling","tags":{"topic":"ocd","difficulty":3,"objective":"Formulate hoarding with its beliefs and family conflict","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Hoarding disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-62', 'Aisha: the nose she can''t stop checking (body dysmorphic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-62-1","text":"Doing well academically when she attends","bucket":"protective"},{"id":"form-62-2","text":"Preoccupied for hours daily with a perceived crooked nose that others cannot see","bucket":"presenting"},{"id":"form-62-3","text":"Mother who notices her distress","bucket":"protective"},{"id":"form-62-4","text":"Avoids college on ''bad face'' days","bucket":"perpetuating"},{"id":"form-62-5","text":"Checks mirrors, takes many selfies, avoids photos","bucket":"presenting"},{"id":"form-62-6","text":"A relative commented on her nose at a wedding","bucket":"precipitating"},{"id":"form-62-7","text":"She studies architecture","bucket":"distractor"},{"id":"form-62-8","text":"Teased about her looks in school","bucket":"predisposing"},{"id":"form-62-9","text":"First rhinoplasty did not relieve the worry and she now wants another","bucket":"perpetuating"},{"id":"form-62-10","text":"Hours of mirror checking and photo filtering","bucket":"perpetuating"},{"id":"form-62-11","text":"Perfectionism and low self-worth","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aisha, 21, presents with body dysmorphic disorder: hours of preoccupation with a perceived nasal flaw invisible to others, mirror checking and avoidance. Childhood teasing and perfectionism with low self-worth (predisposing) set the ground; a relative''s remark (precipitating) focused the concern. An unhelpful first rhinoplasty that now drives a wish for more surgery, checking and filtering, and avoidance (perpetuating) keep it going. A concerned mother and academic strength (protective) support CBT for body dysmorphic disorder and an SSRI, with advice against further cosmetic procedures until treated.","hint":"A student who wants a second rhinoplasty","tags":{"topic":"ocd","difficulty":4,"objective":"Formulate body dysmorphic disorder and the cosmetic-surgery trap","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Body dysmorphic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-63', 'Priya: the bald patch under her dupatta (trichotillomania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-63-1","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-63-2","text":"Shame stops her telling anyone","bucket":"perpetuating"},{"id":"form-63-3","text":"She takes the school bus","bucket":"distractor"},{"id":"form-63-4","text":"Tries to stop but cannot","bucket":"presenting"},{"id":"form-63-5","text":"Happens automatically while reading alone","bucket":"perpetuating"},{"id":"form-63-6","text":"Close friend she can tell","bucket":"protective"},{"id":"form-63-7","text":"Began during board exam preparation","bucket":"precipitating"},{"id":"form-63-8","text":"Wants to stop and accepted help","bucket":"protective"},{"id":"form-63-9","text":"Pulling relieves tension for a moment","bucket":"perpetuating"},{"id":"form-63-10","text":"Aunt who picked her skin","bucket":"predisposing"},{"id":"form-63-11","text":"Pulls hair from her scalp, leaving a bald patch she hides","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Priya, 16, presents with trichotillomania: repeated hair pulling causing a hidden bald patch and failed attempts to stop. An anxious temperament and a family history of skin picking (predisposing) increase risk; board-exam stress (precipitating) began it. Brief tension relief, automatic pulling during solitary reading and shame-driven secrecy (perpetuating) keep it going. Her motivation and a trusted friend (protective) support habit-reversal training with awareness, a competing response and stimulus control while studying.","hint":"A 16-year-old who pulls her hair while studying","tags":{"topic":"ocd","difficulty":2,"objective":"Show tension relief and cues in a body-focused repetitive behaviour","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Trichotillomania (hair-pulling disorder)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-64', 'Mrs Joseph: the old fear of birds (specific phobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-64-1","text":"She teaches mathematics","bucket":"distractor"},{"id":"form-64-2","text":"Anxious child","bucket":"predisposing"},{"id":"form-64-3","text":"Understanding principal","bucket":"protective"},{"id":"form-64-4","text":"Checks windows before entering rooms","bucket":"perpetuating"},{"id":"form-64-5","text":"Colleagues cover her courtyard duty","bucket":"perpetuating"},{"id":"form-64-6","text":"Mother also feared birds","bucket":"predisposing"},{"id":"form-64-7","text":"Motivated because of a new school timetable","bucket":"protective"},{"id":"form-64-8","text":"Intense fear of pigeons and crows, panics if one comes near","bucket":"presenting"},{"id":"form-64-9","text":"Avoids all places with birds","bucket":"perpetuating"},{"id":"form-64-10","text":"A crow swooped at her head when she was seven","bucket":"precipitating"},{"id":"form-64-11","text":"Avoids the school courtyard and open markets","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Joseph, 44, presents with a specific phobia of birds: intense fear and panic near pigeons and crows with avoidance of courtyards and markets. A fearful mother and an anxious temperament (predisposing) made her vulnerable; a crow swooping at her in childhood (precipitating) set the fear. Complete avoidance, colleagues covering for her and window checking (perpetuating) keep the fear untested. A new timetable that requires courtyard duty and an understanding principal (protective) support graded exposure therapy.","hint":"A teacher who will not go to the school courtyard","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a simple phobia into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, animal type (birds)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-65', 'Rehan: the boy who won''t talk at school (selective mutism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-65-1","text":"Started a large English-medium school where he knew no one","bucket":"precipitating"},{"id":"form-65-2","text":"Engaged parents","bucket":"protective"},{"id":"form-65-3","text":"His school bag is red","bucket":"distractor"},{"id":"form-65-4","text":"Teacher and classmates answer for him","bucket":"perpetuating"},{"id":"form-65-5","text":"Speaks to one classmate on the phone","bucket":"protective"},{"id":"form-65-6","text":"Parents excuse him as ''just shy''","bucket":"perpetuating"},{"id":"form-65-7","text":"Not expected to speak, so never practises","bucket":"perpetuating"},{"id":"form-65-8","text":"Mother with social anxiety","bucket":"predisposing"},{"id":"form-65-9","text":"Speaks freely at home but not at all at school for a year","bucket":"presenting"},{"id":"form-65-10","text":"Nods and points instead","bucket":"presenting"},{"id":"form-65-11","text":"Shy, behaviourally inhibited temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rehan, 6, presents with selective mutism: fluent speech at home but none at school for a year. A behaviourally inhibited temperament and a socially anxious mother (predisposing) increase risk; starting a large, unfamiliar English-medium school (precipitating) began it. Others speaking for him, low expectations and excusing it as shyness (perpetuating) remove chances to practise. Speaking to one classmate by phone and engaged parents (protective) support a graded plan that slowly brings speech into school through small steps.","hint":"A 6-year-old chatty at home, silent in class","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Show how others speaking for a child maintains mutism","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Selective mutism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-66', 'Varun: the boy who breaks things (conduct problems)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-66-1","text":"Father left home; family moved to a rented room","bucket":"precipitating"},{"id":"form-66-2","text":"School exclusion increases time with the older boys","bucket":"perpetuating"},{"id":"form-66-3","text":"Suspended from school twice","bucket":"presenting"},{"id":"form-66-4","text":"Joined older boys who steal phones","bucket":"perpetuating"},{"id":"form-66-5","text":"He was born in the monsoon","bucket":"distractor"},{"id":"form-66-6","text":"Witnessed his father hit his mother for years","bucket":"predisposing"},{"id":"form-66-7","text":"Mother wants help and will attend","bucket":"protective"},{"id":"form-66-8","text":"Harsh, inconsistent discipline from an exhausted mother","bucket":"perpetuating"},{"id":"form-66-9","text":"Fights, theft from shops and truancy for a year","bucket":"presenting"},{"id":"form-66-10","text":"Good at cricket and loves the coach","bucket":"protective"},{"id":"form-66-11","text":"Undiagnosed reading difficulty","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Varun, 13, presents with adolescent-onset conduct disorder: fighting, theft and truancy with school suspensions. Exposure to domestic violence and an undiagnosed reading difficulty (predisposing) shaped anger and school failure; his father leaving and the family''s move (precipitating) began the slide. Antisocial peers, harsh inconsistent discipline and school exclusion (perpetuating) maintain it. A cricket coach he admires and a mother who wants help (protective) support parent training, a reading assessment, a school plan and structured sport.","hint":"A 13-year-old suspended for fighting","tags":{"topic":"child-adolescent","difficulty":3,"objective":"Formulate conduct problems with home and peer factors","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Conduct disorder, adolescent onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-67', 'Ayaan: the blinks and the throat noises (Tourette syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-67-1","text":"Father had tics as a boy","bucket":"predisposing"},{"id":"form-67-2","text":"Also restless and inattentive","bucket":"predisposing"},{"id":"form-67-3","text":"Eye blinking, head jerks and throat-clearing noises for over a year","bucket":"presenting"},{"id":"form-67-4","text":"Excellent at chess","bucket":"protective"},{"id":"form-67-5","text":"Teacher willing to educate the class","bucket":"protective"},{"id":"form-67-6","text":"Teasing increases stress","bucket":"perpetuating"},{"id":"form-67-7","text":"Holds tics in at school then releases them at home","bucket":"perpetuating"},{"id":"form-67-8","text":"Teased at school","bucket":"presenting"},{"id":"form-67-9","text":"He likes mango ice cream","bucket":"distractor"},{"id":"form-67-10","text":"Parents tell him to stop, which raises tension and tics","bucket":"perpetuating"},{"id":"form-67-11","text":"Tics worsened when he started a new class","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ayaan, 10, presents with Tourette syndrome: multiple motor tics and a vocal tic for over a year, with teasing. A family history and coexisting attention difficulties (predisposing) fit the usual pattern; starting a new class (precipitating) worsened them. Being told to stop, teasing and suppressing tics then releasing them at home (perpetuating) increase tension and frequency. Chess talent and a willing teacher (protective) support education for family and class, behavioural therapy for tics and assessment of attention.","hint":"A 10-year-old teased for his tics","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate tics with stress and attention factors","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Tourette syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-68', 'Sneha: wet beds at nine (enuresis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-68-1","text":"She has a younger brother","bucket":"distractor"},{"id":"form-68-2","text":"Drinks large amounts in the evening","bucket":"perpetuating"},{"id":"form-68-3","text":"Wears nappies at night, so no motivation to wake","bucket":"perpetuating"},{"id":"form-68-4","text":"Wets the bed most nights at age nine","bucket":"presenting"},{"id":"form-68-5","text":"Scolding and shaming by grandmother","bucket":"perpetuating"},{"id":"form-68-6","text":"Father wet the bed until age ten","bucket":"predisposing"},{"id":"form-68-7","text":"Parents willing to try an alarm","bucket":"protective"},{"id":"form-68-8","text":"No new trigger; always wet; noticed more after a school trip was announced","bucket":"precipitating"},{"id":"form-68-9","text":"Deep sleeper","bucket":"predisposing"},{"id":"form-68-10","text":"Keen to go on the trip","bucket":"protective"},{"id":"form-68-11","text":"Refuses sleepovers and school trips","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sneha, 9, presents with primary nocturnal enuresis: wetting most nights, now causing her to avoid trips. A family history and deep sleep (predisposing) are typical; there is no new trigger, but an upcoming trip made it urgent. Shaming, heavy evening drinking and night nappies (perpetuating) keep the pattern. Her wish to join the trip and willing parents (protective) support a bed-wetting alarm, fluid timing, a reward chart and an end to shaming, with medicine as a short-term option.","hint":"A girl who refuses school trips","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort a common childhood problem into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Nocturnal enuresis (primary)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-69', 'Mr Sinha: the driven boss who can''t delegate (obsessive-compulsive personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-69-1","text":"Works late, so has no time for family","bucket":"perpetuating"},{"id":"form-69-2","text":"Strict father who punished mistakes","bucket":"predisposing"},{"id":"form-69-3","text":"He works in the textile export sector","bucket":"distractor"},{"id":"form-69-4","text":"Highly competent and honest","bucket":"protective"},{"id":"form-69-5","text":"Lifelong perfectionism, rigid rules and inability to delegate","bucket":"presenting"},{"id":"form-69-6","text":"Three team members resigned this year; marriage strained","bucket":"presenting"},{"id":"form-69-7","text":"Promoted to manage a team of twelve","bucket":"precipitating"},{"id":"form-69-8","text":"Sees his standards as correct, not a problem","bucket":"perpetuating"},{"id":"form-69-9","text":"Rewarded at school only for perfect marks","bucket":"predisposing"},{"id":"form-69-10","text":"Believes others'' work is never good enough so redoes it","bucket":"perpetuating"},{"id":"form-69-11","text":"Wife who still wants the marriage to work","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sinha, 47, presents with obsessive-compulsive personality disorder: a lifelong, ego-syntonic pattern of perfectionism, rigidity and need for control, now harming his team and marriage. Unlike OCD, there are no intrusive unwanted thoughts or rituals; he sees his standards as right. A punishing father and reward only for perfection (predisposing) shaped the pattern; promotion to a large team (precipitating) exposed its cost. Redoing others'' work, overwork and lack of insight (perpetuating) maintain it. His competence, honesty and committed wife (protective) support therapy focused on flexibility and values.","hint":"A manager whose team keeps resigning","tags":{"topic":"personality","difficulty":4,"objective":"Tell a rigid personality pattern from OCD in a formulation","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Obsessive-compulsive personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-70', 'Ravi: charming, and always in trouble (antisocial personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-70-1","text":"He supports a football club","bucket":"distractor"},{"id":"form-70-2","text":"Peer group involved in crime","bucket":"perpetuating"},{"id":"form-70-3","text":"Assault after drinking at a bar","bucket":"precipitating"},{"id":"form-70-4","text":"Court-referred after an assault","bucket":"presenting"},{"id":"form-70-5","text":"Repeated fights, cheating and lying since his teens, with little remorse","bucket":"presenting"},{"id":"form-70-6","text":"Blames others and denies responsibility","bucket":"perpetuating"},{"id":"form-70-7","text":"Grew up with neglect and a father in prison","bucket":"predisposing"},{"id":"form-70-8","text":"Heavy alcohol use","bucket":"perpetuating"},{"id":"form-70-9","text":"Conduct problems from age 11","bucket":"predisposing"},{"id":"form-70-10","text":"Holds a driving licence and some work skills","bucket":"protective"},{"id":"form-70-11","text":"Loves his young daughter","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi, 30, presents with antisocial personality disorder with alcohol misuse: a pattern since adolescence of violence, deceit and lack of remorse, now with a court referral after assault. Childhood conduct disorder, neglect and parental criminality (predisposing) laid the foundation; drinking at a bar (precipitating) preceded the assault. Heavy alcohol use, a criminal peer group and externalising blame (perpetuating) maintain risk. Love for his daughter and work skills (protective) are levers, but the plan centres on violence risk assessment, alcohol treatment and structured, realistic goals rather than expecting quick change.","hint":"A 30-year-old referred by a court after assault","tags":{"topic":"personality","difficulty":5,"objective":"Formulate antisocial personality with risk and comorbidity","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Antisocial personality disorder with alcohol misuse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-71', 'Mr Kohli: everyone is against him (paranoid personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-71-1","text":"Humiliated by seniors early in service","bucket":"predisposing"},{"id":"form-71-2","text":"Lifelong suspicion that others exploit or deceive him","bucket":"presenting"},{"id":"form-71-3","text":"Holds grudges and has filed three lawsuits against neighbours","bucket":"presenting"},{"id":"form-71-4","text":"Isolates, so no one corrects his views","bucket":"perpetuating"},{"id":"form-71-5","text":"Still reasonable when facts are put to him directly","bucket":"protective"},{"id":"form-71-6","text":"Retired and lost his status and routine","bucket":"precipitating"},{"id":"form-71-7","text":"Reads hidden insults in neutral remarks","bucket":"perpetuating"},{"id":"form-71-8","text":"Grew up in a hostile, competitive family","bucket":"predisposing"},{"id":"form-71-9","text":"He keeps a tidy rose garden","bucket":"distractor"},{"id":"form-71-10","text":"Wife who is loyal and calm","bucket":"protective"},{"id":"form-71-11","text":"Each conflict confirms that people cannot be trusted","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kohli, 64, presents with paranoid personality disorder: a lifelong pattern of suspicion, grudges and litigation, without fixed false beliefs of delusional intensity. A hostile family and humiliation early in service (predisposing) shaped distrust; retirement and lost status (precipitating) brought conflict to the fore. Misreading neutral remarks, isolation and conflicts that seem to prove his view (perpetuating) maintain it. A loyal wife and his ability to consider facts (protective) support a respectful, transparent therapeutic style and screening for depression.","hint":"A retired officer suing his neighbours for the third time","tags":{"topic":"personality","difficulty":4,"objective":"Separate a paranoid personality pattern from delusional disorder","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Paranoid personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-72', 'Meenakshi: ''I can''t decide without him'' (dependent personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-72-1","text":"Cannot make daily decisions without her husband''s advice","bucket":"presenting"},{"id":"form-72-2","text":"Kind and conscientious; good with children","bucket":"protective"},{"id":"form-72-3","text":"Overprotective parents who decided everything","bucket":"predisposing"},{"id":"form-72-4","text":"Married young straight from her parents'' home","bucket":"predisposing"},{"id":"form-72-5","text":"Avoids tasks alone, so never builds confidence","bucket":"perpetuating"},{"id":"form-72-6","text":"Calls him many times a day for every decision","bucket":"perpetuating"},{"id":"form-72-7","text":"Husband transferred to another state for a year","bucket":"precipitating"},{"id":"form-72-8","text":"Supportive older sister","bucket":"protective"},{"id":"form-72-9","text":"Relatives step in and take over","bucket":"perpetuating"},{"id":"form-72-10","text":"Panic and low mood since he was posted away","bucket":"presenting"},{"id":"form-72-11","text":"Their flat has a balcony garden","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meenakshi, 36, presents with dependent personality disorder: a long-standing need for others to make decisions, with panic and low mood since her husband moved away. Overprotective parenting and marriage straight from her parents'' home (predisposing) left her without independent experience; the transfer (precipitating) exposed the pattern. Constant calls for advice, avoidance and relatives taking over (perpetuating) keep her confidence low. A supportive sister and her conscientiousness (protective) support assertiveness and decision-making skills built step by step.","hint":"A woman frozen after her husband''s transfer","tags":{"topic":"personality","difficulty":3,"objective":"Formulate a dependent pattern exposed by separation","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Dependent personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-73', 'Rohit: the founder who cannot hear criticism (narcissistic personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-73-1","text":"Lifelong grandiosity, need for admiration and rage at criticism","bucket":"presenting"},{"id":"form-73-2","text":"Drinks to numb the shame","bucket":"perpetuating"},{"id":"form-73-3","text":"Withdraws from friends who saw him fail","bucket":"perpetuating"},{"id":"form-73-4","text":"Blames others and avoids feedback","bucket":"perpetuating"},{"id":"form-73-5","text":"Parents who praised him as special but were cold when he failed","bucket":"predisposing"},{"id":"form-73-6","text":"Low mood and shame after his start-up failed","bucket":"presenting"},{"id":"form-73-7","text":"Long-time friend who still calls","bucket":"protective"},{"id":"form-73-8","text":"His office was in a co-working space","bucket":"distractor"},{"id":"form-73-9","text":"Talent that brought early success","bucket":"predisposing"},{"id":"form-73-10","text":"Investors pulled out and co-founders quit","bucket":"precipitating"},{"id":"form-73-11","text":"Real abilities and work ethic","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohit, 33, presents with a depressive episode against the background of narcissistic personality disorder: grandiosity and need for admiration that hide fragile self-esteem. Conditional parental warmth and early success (predisposing) built a self-image that could not tolerate failure; the start-up collapse (precipitating) shattered it. Blaming others, withdrawal from those who saw him fail and drinking (perpetuating) deepen the low mood. A loyal friend and genuine abilities (protective) allow treatment of the depression, a risk check given the shame and drinking, and longer work on self-esteem.","hint":"A start-up founder whose co-founders quit","tags":{"topic":"personality","difficulty":5,"objective":"Formulate a fragile self-esteem pattern with depression","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Narcissistic personality disorder with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-74', 'Swati: the cut on her wrist after the fight (adolescent self-harm)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-74-1","text":"Hides it with long sleeves, so no one helps","bucket":"perpetuating"},{"id":"form-74-2","text":"Parents'' frequent fights and a threat of divorce","bucket":"precipitating"},{"id":"form-74-3","text":"A cousin self-harmed and posted about it online","bucket":"predisposing"},{"id":"form-74-4","text":"Cutting brings fast relief from overwhelming feelings","bucket":"perpetuating"},{"id":"form-74-5","text":"Intense temperament","bucket":"predisposing"},{"id":"form-74-6","text":"Talented at painting","bucket":"protective"},{"id":"form-74-7","text":"Cuts her forearm after arguments, about once a week for four months","bucket":"presenting"},{"id":"form-74-8","text":"Her school is co-educational","bucket":"distractor"},{"id":"form-74-9","text":"Low mood and irritability","bucket":"presenting"},{"id":"form-74-10","text":"Online groups that share self-harm images","bucket":"perpetuating"},{"id":"form-74-11","text":"Close to her grandmother","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Swati, 15, presents with repeated self-harm by cutting after arguments, with low mood and irritability. An intense temperament and exposure to a cousin''s self-harm (predisposing) raised her risk; constant parental conflict and divorce threats (precipitating) began it. Fast relief from cutting, secrecy and online self-harm communities (perpetuating) maintain it. Her grandmother and painting (protective) are strengths for a safety plan, family work on conflict and skills for coping with intense feelings, with careful assessment of suicidal intent.","hint":"A 15-year-old who cuts after arguments with her mother","tags":{"topic":"suicide-risk","difficulty":3,"objective":"Formulate self-harm as emotion regulation with risk factors","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"suicide","diagnosis":"Repeated self-harm in an adolescent with emotional dysregulation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-75', 'Mrs Fernandes: since the fall she stays home (fear of falling)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-75-1","text":"Values independence intensely","bucket":"predisposing"},{"id":"form-75-2","text":"Daughter who visits often","bucket":"protective"},{"id":"form-75-3","text":"Has stopped going to church and the market","bucket":"presenting"},{"id":"form-75-4","text":"Inactivity weakens her legs, raising real fall risk","bucket":"perpetuating"},{"id":"form-75-5","text":"Fell on market steps and bruised her hip","bucket":"precipitating"},{"id":"form-75-6","text":"Knee arthritis and cataract","bucket":"predisposing"},{"id":"form-75-7","text":"Fear that another fall means an old-age home","bucket":"perpetuating"},{"id":"form-75-8","text":"Nursing knowledge and good insight","bucket":"protective"},{"id":"form-75-9","text":"Groceries delivered, so no need to go out","bucket":"perpetuating"},{"id":"form-75-10","text":"She was born in Margao","bucket":"distractor"},{"id":"form-75-11","text":"Will not go out alone since a fall six months ago","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Fernandes, 74, presents with fear of falling with agoraphobic avoidance since a fall. Knee arthritis, cataract and a strong value on independence (predisposing) shape both real risk and fear; the market fall (precipitating) began the avoidance. Inactivity that weakens her, delivery services that remove the need to go out and fear of losing her home (perpetuating) keep it going. Her nursing knowledge and a visiting daughter (protective) support physiotherapy, cataract review and graded return to church and the market.","hint":"A 74-year-old retired nurse","tags":{"topic":"anxiety","difficulty":2,"objective":"Show physical and psychological factors together in late life","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Fear of falling with agoraphobic avoidance"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-76', 'Mr Rathore: the steps he takes in his sleep (REM sleep behaviour disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-76-1","text":"Hit his wife while asleep","bucket":"presenting"},{"id":"form-76-2","text":"Wife who keeps a sleep diary","bucket":"protective"},{"id":"form-76-3","text":"Male, aged 66","bucket":"predisposing"},{"id":"form-76-4","text":"Sleeps in a room with sharp furniture edges","bucket":"perpetuating"},{"id":"form-76-5","text":"Reduced sense of smell for some years","bucket":"predisposing"},{"id":"form-76-6","text":"He retired from the railways","bucket":"distractor"},{"id":"form-76-7","text":"An antidepressant started for low mood may worsen episodes","bucket":"perpetuating"},{"id":"form-76-8","text":"Episodes became frequent over the past year","bucket":"precipitating"},{"id":"form-76-9","text":"Shouts, kicks and punches during vivid dreams of being attacked","bucket":"presenting"},{"id":"form-76-10","text":"Seeks help early","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rathore, 66, presents with REM sleep behaviour disorder: acting out violent dreams with injury to his wife. Older male sex and a reduced sense of smell (predisposing) are notable because this disorder can be an early sign of later conditions such as Parkinson''s disease or Lewy body dementia; episodes have increased over the year (precipitating). An unsafe bedroom and an antidepressant that can worsen REM behaviour (perpetuating) add risk. His wife''s diary and early help-seeking (protective) support sleep study confirmation, bedroom safety, medicine review and long-term neurological follow-up, discussed sensitively.","hint":"A 66-year-old who punched his wife in a dream","tags":{"topic":"sleep","difficulty":5,"objective":"Formulate a sleep disorder that signals future neurological risk","exams":["md-psychiatry"],"module":"neurocognitive","diagnosis":"REM sleep behaviour disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-77', 'Sana: asleep at her desk (narcolepsy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-77-1","text":"Knees buckle when she laughs (cataplexy); vivid dreams on falling asleep","bucket":"presenting"},{"id":"form-77-2","text":"Supportive roommate","bucket":"protective"},{"id":"form-77-3","text":"Labelled lazy by teachers and family","bucket":"perpetuating"},{"id":"form-77-4","text":"Avoids laughing in public out of fear","bucket":"perpetuating"},{"id":"form-77-5","text":"No family history known","bucket":"predisposing"},{"id":"form-77-6","text":"Her favourite subject is constitutional law","bucket":"distractor"},{"id":"form-77-7","text":"Symptoms became disabling with long lecture hours at law school","bucket":"precipitating"},{"id":"form-77-8","text":"Overwhelming daytime sleepiness and sudden sleep attacks","bucket":"presenting"},{"id":"form-77-9","text":"Onset in late teens, typical age","bucket":"predisposing"},{"id":"form-77-10","text":"Drinks many energy drinks, which disturbs night sleep","bucket":"perpetuating"},{"id":"form-77-11","text":"Determined to finish her degree","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sana, 21, presents with narcolepsy with cataplexy: severe daytime sleepiness, sleep attacks, muscle weakness triggered by laughter and vivid dreams at sleep onset. Onset in late adolescence (predisposing) is typical; long lectures (precipitating) made it disabling. Being called lazy, energy drinks that worsen night sleep and avoidance of laughter (perpetuating) add to the burden. A supportive roommate and her determination (protective) support sleep studies, medicine, planned naps and academic adjustments.","hint":"A law student who falls asleep mid-sentence and drops things when she laughs","tags":{"topic":"sleep","difficulty":4,"objective":"Recognise a neurological sleep disorder mislabelled as laziness","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Narcolepsy type 1 (with cataplexy)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-78', 'Harish: the frightening dreams of the flood (nightmare disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-78-1","text":"His boat is painted blue","bucket":"distractor"},{"id":"form-78-2","text":"Works long night shifts on the river","bucket":"predisposing"},{"id":"form-78-3","text":"Wakes from vivid drowning nightmares four nights a week for six months","bucket":"presenting"},{"id":"form-78-4","text":"Afraid to go to sleep","bucket":"presenting"},{"id":"form-78-5","text":"Lost a friend in a river accident as a teen","bucket":"predisposing"},{"id":"form-78-6","text":"Drinks to fall asleep","bucket":"perpetuating"},{"id":"form-78-7","text":"Rehearses the dream on waking","bucket":"perpetuating"},{"id":"form-78-8","text":"Willing to try new techniques","bucket":"protective"},{"id":"form-78-9","text":"Rescued people during a flood last monsoon","bucket":"precipitating"},{"id":"form-78-10","text":"Delays sleep to avoid dreams, causing sleep deprivation","bucket":"perpetuating"},{"id":"form-78-11","text":"Close-knit fishing community","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Harish, 40, presents with nightmare disorder after trauma: frequent, vivid drowning nightmares with fear of sleep; he should also be screened for PTSD. An earlier traumatic loss and long night work (predisposing) increase vulnerability; flood rescue work (precipitating) began the nightmares. Sleep avoidance, drinking to sleep and rehearsing the dream (perpetuating) maintain them. His community and openness (protective) support imagery rehearsal therapy, sleep scheduling and alcohol reduction.","hint":"A boatman who dreams of drowning nightly","tags":{"topic":"trauma","difficulty":2,"objective":"Formulate nightmares with trauma and sleep factors","exams":["mcp-entrance","ma-semester"],"module":"trauma","diagnosis":"Nightmare disorder after trauma (screen for PTSD)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-79', 'Divya: the miscarriage nobody talks about (grief after pregnancy loss)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-79-1","text":"Took two years to conceive","bucket":"predisposing"},{"id":"form-79-2","text":"Family say ''try again quickly'' and do not mention the loss","bucket":"perpetuating"},{"id":"form-79-3","text":"Avoids pregnant friends and baby showers","bucket":"presenting"},{"id":"form-79-4","text":"The hospital had a new maternity wing","bucket":"distractor"},{"id":"form-79-5","text":"Blames herself for lifting a heavy bag","bucket":"perpetuating"},{"id":"form-79-6","text":"Friend who had a similar loss","bucket":"protective"},{"id":"form-79-7","text":"Miscarriage at 14 weeks","bucket":"precipitating"},{"id":"form-79-8","text":"Past anxiety","bucket":"predisposing"},{"id":"form-79-9","text":"Low mood, crying and guilt for three months after a 14-week miscarriage","bucket":"presenting"},{"id":"form-79-10","text":"Husband who grieves with her","bucket":"protective"},{"id":"form-79-11","text":"Avoids all reminders, so grief stays raw","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Divya, 31, presents with a depressive episode after a miscarriage: three months of low mood, guilt and avoidance of pregnancy reminders. Past anxiety and a long time to conceive (predisposing) raised the stakes; the loss at 14 weeks (precipitating) began it. A family that will not acknowledge the loss, self-blame about lifting a bag and avoidance (perpetuating) block grieving. A husband who shares the grief and a friend with a similar loss (protective) support validation of the loss, correction of self-blame, and treatment of the depression before planning another pregnancy.","hint":"A woman low since losing a pregnancy at 14 weeks","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate grief that the family will not acknowledge","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode after pregnancy loss"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-80', 'Mr Mehta: the dementia that came in steps (vascular dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-80-1","text":"Wife and son engaged in care","bucket":"protective"},{"id":"form-80-2","text":"Previous small strokes","bucket":"predisposing"},{"id":"form-80-3","text":"Still enjoys his morning newspaper","bucket":"protective"},{"id":"form-80-4","text":"He owned a sweet shop","bucket":"distractor"},{"id":"form-80-5","text":"Sits at home, inactive","bucket":"perpetuating"},{"id":"form-80-6","text":"Still smokes","bucket":"perpetuating"},{"id":"form-80-7","text":"Each step down followed a ''small attack'' or hospital stay","bucket":"precipitating"},{"id":"form-80-8","text":"Long-standing hypertension, diabetes and smoking","bucket":"predisposing"},{"id":"form-80-9","text":"Low mood and emotional lability","bucket":"presenting"},{"id":"form-80-10","text":"Stepwise decline in planning, slowness and memory over three years","bucket":"presenting"},{"id":"form-80-11","text":"Poorly controlled blood pressure and sugar","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Mehta, 72, presents with vascular neurocognitive disorder: stepwise decline in executive function, speed and memory with emotional lability. Hypertension, diabetes, smoking and earlier strokes (predisposing) caused the brain damage; each small stroke (precipitating) produced a step down. Poor control of risk factors, ongoing smoking and inactivity (perpetuating) risk further decline. An engaged family and his newspaper habit (protective) support tight risk-factor control, stopping smoking, activity and treatment of low mood.","hint":"A 72-year-old with stepwise decline after small strokes","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Show modifiable risk factors in vascular dementia","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Vascular neurocognitive disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-81', 'Mrs Rao: the visitors only she can see (Lewy body dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-81-1","text":"Age 75","bucket":"predisposing"},{"id":"form-81-2","text":"She used to teach Kannada","bucket":"distractor"},{"id":"form-81-3","text":"Became much worse after a sedating antipsychotic was started for the hallucinations","bucket":"precipitating"},{"id":"form-81-4","text":"Falls and acting out dreams","bucket":"presenting"},{"id":"form-81-5","text":"Fluctuating confusion, vivid visual hallucinations of children and stiffness","bucket":"presenting"},{"id":"form-81-6","text":"Years of acting out dreams before memory problems","bucket":"predisposing"},{"id":"form-81-7","text":"Not distressed by the hallucinations when calmly reassured","bucket":"protective"},{"id":"form-81-8","text":"Daughter who keeps a symptom diary","bucket":"protective"},{"id":"form-81-9","text":"Antipsychotic causing severe stiffness and drowsiness","bucket":"perpetuating"},{"id":"form-81-10","text":"Poor lighting in the evening","bucket":"perpetuating"},{"id":"form-81-11","text":"Family argue that the children are not real","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rao, 75, presents with dementia with Lewy bodies: fluctuating cognition, recurrent vivid visual hallucinations, parkinsonism and a history of acting out dreams. Age and years of dream-enactment (predisposing) fit the condition; a sedating antipsychotic (precipitating) caused marked worsening, a known dangerous sensitivity in this illness. Ongoing antipsychotic, family arguing about the hallucinations and poor evening light (perpetuating) add to distress. A careful daughter and her calm response to reassurance (protective) support stopping the antipsychotic under review, considering a cholinesterase inhibitor, better lighting and carer education.","hint":"An 75-year-old whose confusion comes and goes","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Formulate Lewy body dementia and its antipsychotic danger","exams":["md-psychiatry"],"module":"neurocognitive","diagnosis":"Dementia with Lewy bodies"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-82', 'Ashok: the uncle who changed before he forgot (frontotemporal dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-82-1","text":"Memory relatively preserved","bucket":"presenting"},{"id":"form-82-2","text":"Age 58","bucket":"predisposing"},{"id":"form-82-3","text":"He drove a jeep for work","bucket":"distractor"},{"id":"form-82-4","text":"Family thought it was a midlife crisis and argued with him","bucket":"perpetuating"},{"id":"form-82-5","text":"Wife committed to his care","bucket":"protective"},{"id":"form-82-6","text":"Two years of disinhibition, loss of empathy, sweet cravings and shoplifting","bucket":"presenting"},{"id":"form-82-7","text":"Father had ''personality change'' in his fifties","bucket":"predisposing"},{"id":"form-82-8","text":"Behaviour became public when caught stealing sweets","bucket":"precipitating"},{"id":"form-82-9","text":"Brother who helps with finances","bucket":"protective"},{"id":"form-82-10","text":"Lost his job, so lacks structure","bucket":"perpetuating"},{"id":"form-82-11","text":"Easy access to sweets and money","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ashok, 58, presents with behavioural variant frontotemporal dementia: disinhibition, apathy, loss of empathy, food cravings and shoplifting with relatively preserved memory. A family history of similar change in midlife (predisposing) suggests a genetic contribution; being caught shoplifting (precipitating) brought it to attention. Misreading it as a midlife crisis, loss of structure and unrestricted access to money and sweets (perpetuating) worsen harm. A committed wife and helpful brother (protective) support neurological assessment, financial safeguards, structured routines and carer support.","hint":"A 58-year-old who started shoplifting sweets","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Formulate early-onset behavioural change","exams":["md-psychiatry","ugc-net"],"module":"neurocognitive","diagnosis":"Behavioural variant frontotemporal dementia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-83', 'Imran: the thyroid behind the tiredness (hypothyroid low mood)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-83-1","text":"Constipation and dry skin","bucket":"presenting"},{"id":"form-83-2","text":"Had a viral illness with neck pain last year","bucket":"predisposing"},{"id":"form-83-3","text":"Mother has thyroid disease","bucket":"predisposing"},{"id":"form-83-4","text":"Symptoms began a few months after the neck pain","bucket":"precipitating"},{"id":"form-83-5","text":"Treated with an antidepressant without thyroid tests","bucket":"perpetuating"},{"id":"form-83-6","text":"Inactivity and weight gain lower mood further","bucket":"perpetuating"},{"id":"form-83-7","text":"Good relationship with his GP","bucket":"protective"},{"id":"form-83-8","text":"He sells mobile phones","bucket":"distractor"},{"id":"form-83-9","text":"Low mood, slowness, weight gain and feeling cold for six months","bucket":"presenting"},{"id":"form-83-10","text":"Motivated to get better","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Imran, 40, presents with depressive symptoms due to hypothyroidism: low mood, slowness, weight gain, cold intolerance, constipation and dry skin. A family history of thyroid disease and a likely viral thyroiditis (predisposing) explain the vulnerability; onset months after the neck pain (precipitating) fits. Treatment with an antidepressant without checking thyroid function and resulting inactivity (perpetuating) kept the cause hidden. A good GP relationship and his motivation (protective) support thyroid testing and replacement, then reassessing mood.","hint":"A 40-year-old ''depressed'' man who feels cold all the time","tags":{"topic":"depression","difficulty":3,"objective":"Put a medical cause in the right P","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive symptoms due to hypothyroidism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-84', 'Neeta: the HIV result and the silence (adjustment with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-84-1","text":"Few confidants","bucket":"predisposing"},{"id":"form-84-2","text":"Fear of stigma means she tells no one","bucket":"perpetuating"},{"id":"form-84-3","text":"Believes the diagnosis means early death","bucket":"perpetuating"},{"id":"form-84-4","text":"She is a tailoring teacher","bucket":"distractor"},{"id":"form-84-5","text":"HIV diagnosis at an antenatal check","bucket":"precipitating"},{"id":"form-84-6","text":"Counsellor at the ART centre","bucket":"protective"},{"id":"form-84-7","text":"Missing antiretroviral doses","bucket":"presenting"},{"id":"form-84-8","text":"Hides tablets, so misses doses","bucket":"perpetuating"},{"id":"form-84-9","text":"Low mood, insomnia and hopelessness since an HIV diagnosis three months ago","bucket":"presenting"},{"id":"form-84-10","text":"Past low spell after her father''s death","bucket":"predisposing"},{"id":"form-84-11","text":"Wants to protect her unborn child","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neeta, 28, presents with a depressive episode after an HIV diagnosis at an antenatal check: low mood, insomnia, hopelessness and missed antiretroviral doses. A past low spell and few confidants (predisposing) increased risk; the diagnosis (precipitating) began it. Secrecy from fear of stigma, hidden tablets and the false belief that HIV means early death (perpetuating) maintain both mood and poor adherence. A trusted ART counsellor and her wish to protect her baby (protective) support accurate information about treatment and prevention of transmission, treatment of depression and a supported disclosure plan.","hint":"A 28-year-old who has told no one her diagnosis","tags":{"topic":"depression","difficulty":4,"objective":"Formulate stigma and adherence in a chronic illness","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode after HIV diagnosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-85', 'Arun: two years trying for a baby (infertility distress)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-85-1","text":"Loving marriage under the strain","bucket":"protective"},{"id":"form-85-2","text":"Only son expected to continue the family line","bucket":"predisposing"},{"id":"form-85-3","text":"Low mood, irritability and withdrawal since a second failed IVF","bucket":"presenting"},{"id":"form-85-4","text":"Spent savings on treatment","bucket":"perpetuating"},{"id":"form-85-5","text":"They live near a lake","bucket":"distractor"},{"id":"form-85-6","text":"Relatives ask about children at every function","bucket":"perpetuating"},{"id":"form-85-7","text":"Belief that fatherhood proves manhood","bucket":"predisposing"},{"id":"form-85-8","text":"Arguments with his wife","bucket":"presenting"},{"id":"form-85-9","text":"Second failed IVF cycle","bucket":"precipitating"},{"id":"form-85-10","text":"Doctor who offers counselling","bucket":"protective"},{"id":"form-85-11","text":"Avoids talking with his wife about feelings","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arun, 34, presents with an adjustment disorder with low mood after a second failed IVF, with marital strain. Beliefs linking fatherhood to manhood and family pressure as the only son (predisposing) raise the stakes; the second failure (precipitating) triggered it. Relatives'' questions, avoidance of emotional talk and financial strain (perpetuating) maintain it. A loving marriage and an offer of counselling (protective) support couple sessions, sharing decisions about next steps and setting limits with relatives.","hint":"A couple whose IVF failed twice","tags":{"topic":"depression","difficulty":2,"objective":"Formulate distress in a couple, not just one person","exams":["mcp-entrance","ma-semester"],"module":"depression","diagnosis":"Adjustment disorder with low mood (couple stress)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-86', 'Kavya: the counsellor who feels nothing anymore (burnout and depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-86-1","text":"Poor sleep and loss of interest in hobbies","bucket":"presenting"},{"id":"form-86-2","text":"A caller she spoke with died by suicide","bucket":"precipitating"},{"id":"form-86-3","text":"Values her work deeply","bucket":"protective"},{"id":"form-86-4","text":"The helpline uses a cloud phone system","bucket":"distractor"},{"id":"form-86-5","text":"History of a low spell in college","bucket":"predisposing"},{"id":"form-86-6","text":"Strong sense that she must save everyone","bucket":"predisposing"},{"id":"form-86-7","text":"Takes extra shifts to cover staff shortages","bucket":"perpetuating"},{"id":"form-86-8","text":"Emotional numbness at work and low mood at home for four months","bucket":"presenting"},{"id":"form-86-9","text":"No supervision or debriefing at her organisation","bucket":"perpetuating"},{"id":"form-86-10","text":"Close friend from training","bucket":"protective"},{"id":"form-86-11","text":"Stopped her own therapy for lack of time","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kavya, 29, presents with a moderate depressive episode alongside work-related burnout: numbness at work, low mood, poor sleep and anhedonia at home. The spread of symptoms beyond work points to depression, not burnout alone. A rescuer belief and a past low spell (predisposing) shaped vulnerability; a caller''s suicide (precipitating) began it. No supervision, extra shifts and stopping her own therapy (perpetuating) maintain it. A close friend and her values (protective) support treatment, supervision with debriefing, workload limits and grief work about the caller.","hint":"A helpline counsellor after a year of crisis calls","tags":{"topic":"depression","difficulty":4,"objective":"Separate burnout from a depressive episode in a formulation","exams":["mcp-entrance","ma-semester"],"module":"therapies","diagnosis":"Moderate depressive episode with work-related burnout"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-87', 'Prakash: the trembling hand at the chessboard (social anxiety with alcohol)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-87-1","text":"Avoids parent meetings, losing students","bucket":"perpetuating"},{"id":"form-87-2","text":"Shy child with a critical mother","bucket":"predisposing"},{"id":"form-87-3","text":"Lost a televised game after his hand shook visibly","bucket":"precipitating"},{"id":"form-87-4","text":"Hangovers worsen next-day anxiety","bucket":"perpetuating"},{"id":"form-87-5","text":"Brother who supports him","bucket":"protective"},{"id":"form-87-6","text":"Drinks three pegs before any public event","bucket":"presenting"},{"id":"form-87-7","text":"He prefers the Sicilian Defence","bucket":"distractor"},{"id":"form-87-8","text":"Father drank","bucket":"predisposing"},{"id":"form-87-9","text":"Severe fear of being watched at tournaments and parent meetings","bucket":"presenting"},{"id":"form-87-10","text":"Alcohol calms him short-term but stops him learning he can cope","bucket":"perpetuating"},{"id":"form-87-11","text":"Respected for his chess knowledge","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Prakash, 39, presents with social anxiety disorder with harmful alcohol use: intense fear of scrutiny and drinking before public events. Shyness, a critical mother and a drinking father (predisposing) shaped both the fear and the coping; a televised loss with a visible tremor (precipitating) intensified it. Alcohol as a safety behaviour, avoidance of meetings and hangover anxiety (perpetuating) keep it going. His respected expertise and his brother (protective) support CBT for social anxiety with a plan to reduce alcohol, and treatment that does not rely on sedatives.","hint":"A chess coach who drinks before tournaments","tags":{"topic":"anxiety","difficulty":4,"objective":"Show alcohol as a safety behaviour in social anxiety","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Social anxiety disorder with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-88', 'Fiona: the nurse in Dublin who cannot stop checking doses (OCD at work)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-88-1","text":"Mother with anxiety","bucket":"predisposing"},{"id":"form-88-2","text":"Checks medicine doses five or six times, fearing she will kill a patient","bucket":"presenting"},{"id":"form-88-3","text":"She takes the tram to work","bucket":"distractor"},{"id":"form-88-4","text":"Avoids the high-risk ward","bucket":"perpetuating"},{"id":"form-88-5","text":"Late with medication rounds; colleagues complain","bucket":"presenting"},{"id":"form-88-6","text":"Believes thinking about an error makes it more likely","bucket":"perpetuating"},{"id":"form-88-7","text":"Asks colleagues to re-check for reassurance","bucket":"perpetuating"},{"id":"form-88-8","text":"Perfectionism and an inflated sense of responsibility","bucket":"predisposing"},{"id":"form-88-9","text":"Good insight","bucket":"protective"},{"id":"form-88-10","text":"A colleague made a dosing error that harmed a patient","bucket":"precipitating"},{"id":"form-88-11","text":"Supportive ward manager","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Fiona, 30, presents with obsessive-compulsive disorder: intrusive fears of causing a patient''s death with repeated dose checking that slows her work. Perfectionism, inflated responsibility and maternal anxiety (predisposing) made her vulnerable; a colleague''s harmful error (precipitating) gave the fear its focus. Reassurance seeking, avoidance and thought-action fusion beliefs (perpetuating) maintain it. Good insight and a supportive manager (protective) support exposure and response prevention with a safe, agreed single-check routine at work.","hint":"An Indian-origin nurse whose checking slows her shifts","tags":{"topic":"ocd","difficulty":3,"objective":"Formulate OCD in a high-responsibility job","exams":["mcp-entrance","md-psychiatry"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, checking type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-89', 'Venkat: the debt and the gun licence (risk formulation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-89-1","text":"Older male living with chronic pain","bucket":"predisposing"},{"id":"form-89-2","text":"Business collapse with loans called in","bucket":"precipitating"},{"id":"form-89-3","text":"Hopelessness, insomnia and statements that his family would be better off with his insurance","bucket":"presenting"},{"id":"form-89-4","text":"Refuses to tell his wife the extent of the debt","bucket":"perpetuating"},{"id":"form-89-5","text":"Father died by suicide","bucket":"predisposing"},{"id":"form-89-6","text":"Religious beliefs against suicide that he still partly holds","bucket":"protective"},{"id":"form-89-7","text":"Drinking more at night","bucket":"perpetuating"},{"id":"form-89-8","text":"Owns a licensed revolver at home","bucket":"perpetuating"},{"id":"form-89-9","text":"Close bond with his grandson","bucket":"protective"},{"id":"form-89-10","text":"Withdrawn and giving away possessions","bucket":"presenting"},{"id":"form-89-11","text":"His company made steel furniture","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Venkat, 61, presents with a severe depressive episode and high suicide risk: hopelessness, insomnia, insurance-related statements and giving away possessions. Being an older man in chronic pain with a father who died by suicide (predisposing) raises baseline risk; business collapse (precipitating) began the crisis. A firearm at home, increasing alcohol and secrecy about the debt (perpetuating) make risk acute. Bonds with his grandson and his faith (protective) matter, but the immediate plan is removing the firearm, urgent treatment with close supervision or admission, and involving his wife.","hint":"A businessman with a licensed revolver and mounting losses","tags":{"topic":"suicide-risk","difficulty":5,"objective":"Build a risk formulation alongside the 5 Ps","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Severe depressive episode with high suicide risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-90', 'Sister Agnes: the novice who hears God''s punishment (psychotic depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-90-1","text":"Strict, guilt-based upbringing","bucket":"predisposing"},{"id":"form-90-2","text":"Avoids confession because she feels beyond forgiveness","bucket":"perpetuating"},{"id":"form-90-3","text":"Believes she has committed an unforgivable sin and must starve","bucket":"presenting"},{"id":"form-90-4","text":"Not eating worsens her thinking","bucket":"perpetuating"},{"id":"form-90-5","text":"Community reads her fasting as piety","bucket":"perpetuating"},{"id":"form-90-6","text":"Novice mistress who brought her","bucket":"protective"},{"id":"form-90-7","text":"Her mother died while she was in the novitiate and she could not attend the funeral","bucket":"precipitating"},{"id":"form-90-8","text":"The convent has a library of old hymnals","bucket":"distractor"},{"id":"form-90-9","text":"Hears a voice condemning her","bucket":"presenting"},{"id":"form-90-10","text":"Faith that can include accepting care","bucket":"protective"},{"id":"form-90-11","text":"Previous depressive episode at 18","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sister Agnes, 24, presents with a severe depressive episode with mood-congruent psychotic features: a delusion of unforgivable sin, a condemning voice and food refusal. A guilt-based upbringing and a past episode (predisposing) increased risk; her mother''s death and missing the funeral (precipitating) began it. Fasting misread as piety, avoidance of confession and starvation (perpetuating) maintain it. Her novice mistress and a faith that can include accepting care (protective) support urgent medical and psychiatric treatment, involving a spiritual adviser and attention to nutrition.","hint":"A young nun refusing food from guilt","tags":{"topic":"depression","difficulty":5,"objective":"Formulate psychotic depression respectfully in a religious setting","exams":["md-psychiatry"],"module":"depression","diagnosis":"Severe depressive episode with mood-congruent psychotic features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-91', 'Rohini: the night nurse and the sleeping pills (insomnia with shift work)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-91-1","text":"Tired and irritable on days off","bucket":"presenting"},{"id":"form-91-2","text":"Daytime room is bright and noisy","bucket":"perpetuating"},{"id":"form-91-3","text":"Moved to a rota with three nights in a row","bucket":"precipitating"},{"id":"form-91-4","text":"Drinks coffee to get through shifts","bucket":"perpetuating"},{"id":"form-91-5","text":"Manager willing to adjust her rota","bucket":"protective"},{"id":"form-91-6","text":"Knows the medicine is a problem","bucket":"protective"},{"id":"form-91-7","text":"Rotating shifts for ten years","bucket":"predisposing"},{"id":"form-91-8","text":"Cannot sleep after night shifts without zolpidem for a year","bucket":"presenting"},{"id":"form-91-9","text":"Takes zolpidem nightly, with rebound insomnia when she skips","bucket":"perpetuating"},{"id":"form-91-10","text":"Her hospital is a 500-bed trust hospital","bucket":"distractor"},{"id":"form-91-11","text":"Light sleeper","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohini, 38, presents with shift work sleep disorder and hypnotic dependence: inability to sleep after night shifts without zolpidem. A light-sleeping tendency and years of rotating shifts (predisposing) set the ground; a rota with consecutive nights (precipitating) worsened it. A bright, noisy day room, nightly hypnotic with rebound insomnia and caffeine (perpetuating) maintain it. A flexible manager and her insight (protective) support blackout curtains, a stable rota, timed light exposure, caffeine limits and a gradual hypnotic taper with CBT for insomnia.","hint":"A nurse who sleeps only with zolpidem","tags":{"topic":"sleep","difficulty":3,"objective":"Formulate circadian and medication factors in insomnia","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Shift work sleep disorder with hypnotic dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-92', 'Aditi: the silence after the assault (PTSD after sexual violence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-92-1","text":"Flashbacks, nightmares and startle for four months","bucket":"presenting"},{"id":"form-92-2","text":"Sexually assaulted by an acquaintance after a party","bucket":"precipitating"},{"id":"form-92-3","text":"Strong family emphasis on ''honour''","bucket":"predisposing"},{"id":"form-92-4","text":"Friend who believes her","bucket":"protective"},{"id":"form-92-5","text":"Childhood bullying left her feeling unsafe","bucket":"predisposing"},{"id":"form-92-6","text":"Wants to finish her degree","bucket":"protective"},{"id":"form-92-7","text":"Has told no one except one friend","bucket":"perpetuating"},{"id":"form-92-8","text":"Avoids college and men on public transport","bucket":"presenting"},{"id":"form-92-9","text":"She studies economics","bucket":"distractor"},{"id":"form-92-10","text":"Avoidance prevents processing","bucket":"perpetuating"},{"id":"form-92-11","text":"Blames herself for going to the party","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aditi, 23, presents with post-traumatic stress disorder after a sexual assault: flashbacks, nightmares, startle and avoidance of college and travel. Childhood bullying and family emphasis on honour (predisposing) shape shame and fear of disclosure; the assault (precipitating) caused the disorder. Self-blame, secrecy and avoidance (perpetuating) keep the trauma unprocessed. A friend who believes her and her academic goals (protective) support a safety assessment, information about her legal options without pressure, and trauma-focused CBT or EMDR.","hint":"A 23-year-old who stopped going to college","tags":{"topic":"trauma","difficulty":4,"objective":"Formulate trauma with shame and safety needs","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Post-traumatic stress disorder after sexual assault"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-93', 'Mr Krishnan: the year that did not soften (prolonged grief)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-93-1","text":"Wife who grieves differently but stays close","bucket":"protective"},{"id":"form-93-2","text":"Brother who visits","bucket":"protective"},{"id":"form-93-3","text":"Previous unresolved grief for his own father","bucket":"predisposing"},{"id":"form-93-4","text":"Stopped temple and social life","bucket":"perpetuating"},{"id":"form-93-5","text":"His son studied mechanical engineering","bucket":"distractor"},{"id":"form-93-6","text":"Very close relationship with his only son","bucket":"predisposing"},{"id":"form-93-7","text":"Avoids the accident road and all reminders","bucket":"perpetuating"},{"id":"form-93-8","text":"Believes moving on would betray his son","bucket":"perpetuating"},{"id":"form-93-9","text":"Cannot accept the death; avoids the room and still sets his place","bucket":"presenting"},{"id":"form-93-10","text":"Intense yearning and preoccupation with his son 18 months after his death","bucket":"presenting"},{"id":"form-93-11","text":"Son died suddenly in a road accident","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Krishnan, 58, presents with prolonged grief disorder: 18 months of intense yearning, preoccupation, difficulty accepting the death and loss of meaning after his son''s sudden death. A very close bond and earlier unresolved grief (predisposing) heightened vulnerability; the sudden accident (precipitating) caused the loss. Avoidance, beliefs that recovery would betray his son and withdrawal (perpetuating) keep grief stuck. A close wife and visiting brother (protective) support grief-focused therapy that honours the bond while helping him re-engage with life.","hint":"A man who still sets his son''s place at the table","tags":{"topic":"grief","difficulty":3,"objective":"Formulate prolonged grief disorder","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Prolonged grief disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-94', 'Sameer: the episodic ''ADHD'' (bipolar II misread)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-94-1","text":"Spells began at 21 with a demanding internship","bucket":"precipitating"},{"id":"form-94-2","text":"Supportive friends","bucket":"protective"},{"id":"form-94-3","text":"Curious and open to evidence","bucket":"protective"},{"id":"form-94-4","text":"He uses a standing desk","bucket":"distractor"},{"id":"form-94-5","text":"Irregular sleep from late launches","bucket":"perpetuating"},{"id":"form-94-6","text":"Self-labels as ADHD and seeks stimulants","bucket":"perpetuating"},{"id":"form-94-7","text":"Week-long spells of little sleep, racing ideas and productivity","bucket":"presenting"},{"id":"form-94-8","text":"Cannabis on crash days","bucket":"perpetuating"},{"id":"form-94-9","text":"Mother with depression","bucket":"predisposing"},{"id":"form-94-10","text":"Followed by low crashes","bucket":"presenting"},{"id":"form-94-11","text":"Calm, focused child according to school reports","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sameer, 26, presents with bipolar II disorder: episodic week-long hypomanic spells with reduced need for sleep and productivity, followed by low crashes. A maternal history of depression (predisposing) increases risk, while calm school reports argue against lifelong ADHD; a demanding internship (precipitating) marked onset. A self-label that leads him to seek stimulants, irregular sleep and cannabis use (perpetuating) risk destabilising mood. His openness to evidence and supportive friends (protective) support mood charting, sleep regularity, avoiding stimulants and mood-stabilising treatment.","hint":"A product manager asking for stimulants","tags":{"topic":"bipolar","difficulty":4,"objective":"Use the time course in the formulation to correct a self-label","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar II disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-95', 'Anjali: ''I''ll never be a good mother'' (perinatal anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-95-1","text":"Checks the baby''s breathing many times a night","bucket":"presenting"},{"id":"form-95-2","text":"Husband shares night duty","bucket":"protective"},{"id":"form-95-3","text":"Her own mother was critical","bucket":"predisposing"},{"id":"form-95-4","text":"Searches baby health forums at night","bucket":"perpetuating"},{"id":"form-95-5","text":"The baby''s cradle was a family heirloom","bucket":"distractor"},{"id":"form-95-6","text":"Paediatrician who reassures well","bucket":"protective"},{"id":"form-95-7","text":"Mother-in-law criticises her feeding","bucket":"perpetuating"},{"id":"form-95-8","text":"Baby had jaundice and was admitted for two days","bucket":"precipitating"},{"id":"form-95-9","text":"Little sleep from night checking","bucket":"perpetuating"},{"id":"form-95-10","text":"Constant worry about the baby''s health and her own competence for two months","bucket":"presenting"},{"id":"form-95-11","text":"Anxious temperament since school","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anjali, 27, presents with generalised anxiety after her baby''s birth: persistent worry about the baby''s health and her competence, with frequent night checks. An anxious temperament and a critical mother (predisposing) shaped self-doubt; the baby''s admission for jaundice (precipitating) began it. Night forum searching, criticism from her mother-in-law and sleep loss (perpetuating) keep it going. A husband who shares nights and a reassuring paediatrician (protective) support CBT for worry, protected sleep and limits on checking and searching.","hint":"A first-time mother checking the baby''s breathing all night","tags":{"topic":"perinatal","difficulty":2,"objective":"Sort perinatal anxiety into the 5 Ps","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Generalised anxiety in the postnatal period"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-96', 'Mr Ali: the worms only he can see (delusional infestation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-96-1","text":"Fixed belief that worms live under his skin, with scratching and sores","bucket":"presenting"},{"id":"form-96-2","text":"Son who brought him","bucket":"protective"},{"id":"form-96-3","text":"Night-time checking of his skin","bucket":"perpetuating"},{"id":"form-96-4","text":"Belief began after his wife''s death","bucket":"precipitating"},{"id":"form-96-5","text":"Brings skin and lint in a matchbox as proof","bucket":"presenting"},{"id":"form-96-6","text":"Lives alone and is socially isolated","bucket":"predisposing"},{"id":"form-96-7","text":"Diabetes with dry, itchy skin","bucket":"predisposing"},{"id":"form-96-8","text":"Engages if not argued with","bucket":"protective"},{"id":"form-96-9","text":"Dermatologists dismiss him and he moves to the next","bucket":"perpetuating"},{"id":"form-96-10","text":"He drove a government jeep","bucket":"distractor"},{"id":"form-96-11","text":"Uses kerosene and harsh soaps, worsening the skin","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Ali, 63, presents with delusional disorder, somatic type: a fixed belief in skin infestation with scratching, sores and ''specimens''. Diabetic skin dryness and itch and social isolation (predisposing) provide the sensations and the lack of correction; his wife''s death (precipitating) preceded onset. Harsh home treatments, being dismissed by doctors and night checking (perpetuating) maintain it. A son who brought him and his willingness to engage without argument (protective) support joint care with dermatology, treating the skin and itch, screening for medical causes and a low-dose antipsychotic.","hint":"A widower bringing ''specimens'' in a matchbox","tags":{"topic":"psychosis","difficulty":4,"objective":"Include medical contributors in a somatic delusion formulation","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Delusional disorder, somatic type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-97', 'Komal: the lithium and the kidneys (long-term treatment review)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-97-1","text":"Kidney blood test result came back lower than before","bucket":"precipitating"},{"id":"form-97-2","text":"Last lithium level and thyroid test were long ago","bucket":"perpetuating"},{"id":"form-97-3","text":"Ten years on lithium","bucket":"predisposing"},{"id":"form-97-4","text":"Two past manic episodes","bucket":"predisposing"},{"id":"form-97-5","text":"Drinks lots of water, which she thinks is the problem","bucket":"perpetuating"},{"id":"form-97-6","text":"Good relationship with her psychiatrist","bucket":"protective"},{"id":"form-97-7","text":"Thirst, passing large amounts of urine and mildly reduced kidney function","bucket":"presenting"},{"id":"form-97-8","text":"She prefers working from the office","bucket":"distractor"},{"id":"form-97-9","text":"Mood stable for ten years","bucket":"presenting"},{"id":"form-97-10","text":"Excellent adherence and insight","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Komal, 28, presents with lithium-related effects after ten years of stable bipolar I disorder: polyuria, thirst and mildly reduced kidney function. Long-term lithium (predisposing) is the cause of the kidney effects, and her two past manic episodes explain why stopping is risky; the new kidney result (precipitating) brought her in. Lapsed monitoring and misunderstanding the thirst (perpetuating) need correcting. Her adherence, insight and relationship with her psychiatrist (protective) support a shared review of lithium levels, kidney, thyroid and calcium tests and a weighed decision about continuing or switching.","hint":"A stable accountant with rising thirst","tags":{"topic":"bipolar","difficulty":2,"objective":"Use a formulation to plan long-term monitoring","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"stabilisers","diagnosis":"Bipolar I disorder in remission with lithium-related kidney effects"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-98', 'Mehul: the back that ended his factory job (chronic pain with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-98-1","text":"Escalating over-the-counter painkillers that give little relief","bucket":"perpetuating"},{"id":"form-98-2","text":"Rest and avoidance weaken his back and lower his mood","bucket":"perpetuating"},{"id":"form-98-3","text":"Lifting injury at the factory and loss of his job","bucket":"precipitating"},{"id":"form-98-4","text":"His factory made plastic buckets","bucket":"distractor"},{"id":"form-98-5","text":"Daily low back pain for two years after a lifting injury, with low mood and poor sleep","bucket":"presenting"},{"id":"form-98-6","text":"Spends most of the day lying down","bucket":"presenting"},{"id":"form-98-7","text":"Manual job with no other skills or savings","bucket":"predisposing"},{"id":"form-98-8","text":"Interest in teaching his son to repair radios","bucket":"protective"},{"id":"form-98-9","text":"Wife who wants him active again","bucket":"protective"},{"id":"form-98-10","text":"Belief that hurt always means harm","bucket":"predisposing"},{"id":"form-98-11","text":"Compensation dispute keeps attention on the injury","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mehul, 44, presents with chronic low back pain and a moderate depressive episode: two years of daily pain, low mood, poor sleep and inactivity. A manual job with no fallback and a belief that pain always signals damage (predisposing) shaped fear and loss; the lifting injury and job loss (precipitating) began the cycle. Rest and avoidance, rising painkillers and a drawn-out compensation dispute (perpetuating) keep pain and mood linked. A supportive wife and his radio-repair skill (protective) support a pain-management approach with graded activity, review of painkillers, antidepressant treatment that also helps pain and a plan for meaningful work.","hint":"A machine operator on daily painkillers who has stopped going out","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate the pain, mood and activity cycle","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Chronic low back pain with a moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-99', 'Chhotu: the whitener and the platform (child inhalant use)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-99-1","text":"Bright and resourceful","bucket":"protective"},{"id":"form-99-2","text":"Ran away at ten","bucket":"predisposing"},{"id":"form-99-3","text":"Headaches, memory problems and falls","bucket":"presenting"},{"id":"form-99-4","text":"No safe shelter at night","bucket":"perpetuating"},{"id":"form-99-5","text":"Sniffing takes away hunger and cold","bucket":"perpetuating"},{"id":"form-99-6","text":"Violent stepfather at home in Bihar","bucket":"predisposing"},{"id":"form-99-7","text":"Trusts an NGO outreach worker","bucket":"protective"},{"id":"form-99-8","text":"Sniffs correction fluid daily","bucket":"presenting"},{"id":"form-99-9","text":"Joined older boys at the station who sniff","bucket":"precipitating"},{"id":"form-99-10","text":"He collects plastic bottles to sell","bucket":"distractor"},{"id":"form-99-11","text":"Older boys exploit him","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chhotu, 13, presents with inhalant use disorder with neurotoxic effects and urgent safeguarding needs. A violent stepfather and running away at ten (predisposing) left him unprotected; joining older boys who sniff (precipitating) began use. Relief from hunger and cold, exploitation by older boys and no safe shelter (perpetuating) maintain it. Trust in an NGO worker and his resourcefulness (protective) support child welfare referral, shelter, medical review and a gradual, trust-based plan to stop.","hint":"A 13-year-old runaway at a railway station","tags":{"topic":"substance","difficulty":4,"objective":"Formulate substance use in a child with safeguarding needs","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Inhalant use disorder in a street-connected child"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-100', 'Dr Banerjee: the theatre lights are watching (stimulant-linked psychosis in a doctor)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-100-1","text":"Months of 100-hour weeks with modafinil to stay awake","bucket":"precipitating"},{"id":"form-100-2","text":"A friend who supports him","bucket":"protective"},{"id":"form-100-3","text":"Perfectionistic and competitive","bucket":"predisposing"},{"id":"form-100-4","text":"Strong motivation to keep practising","bucket":"protective"},{"id":"form-100-5","text":"Fear of career damage stops him accepting help","bucket":"perpetuating"},{"id":"form-100-6","text":"Cousin with schizophrenia","bucket":"predisposing"},{"id":"form-100-7","text":"Believes the head of department watches him through theatre lights","bucket":"presenting"},{"id":"form-100-8","text":"He trained in general surgery","bucket":"distractor"},{"id":"form-100-9","text":"Ongoing sleep deprivation and stimulant use","bucket":"perpetuating"},{"id":"form-100-10","text":"Department conflict feeds suspicion","bucket":"perpetuating"},{"id":"form-100-11","text":"Wrote about being watched in a patient''s chart","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dr Banerjee, 34, presents with a psychotic episode with persecutory beliefs about his department, linked to stimulant use and severe sleep deprivation, with a family history that keeps a primary psychosis in view. Perfectionism and a family history (predisposing) increased vulnerability; months of extreme hours on modafinil (precipitating) preceded onset. Ongoing sleep loss and stimulants, fear for his career and workplace conflict (perpetuating) maintain it. A supportive friend and his wish to practise (protective) support stopping stimulants, restoring sleep, treatment and a confidential occupational health route that protects patients and him.","hint":"A surgical resident on modafinil and three hours of sleep","tags":{"topic":"psychosis","difficulty":5,"objective":"Formulate psychosis with occupational and safety dimensions","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Psychotic episode linked to stimulant use and sleep deprivation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-101', 'Mrs Gupta: the daughter-in-law and the empty kitchen (late-life depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-101-1","text":"No interest in grandchildren","bucket":"presenting"},{"id":"form-101-2","text":"Long friendship with a neighbour","bucket":"protective"},{"id":"form-101-3","text":"Identity built around running the family kitchen","bucket":"predisposing"},{"id":"form-101-4","text":"Grandchildren who love her","bucket":"protective"},{"id":"form-101-5","text":"Osteoarthritis","bucket":"predisposing"},{"id":"form-101-6","text":"Son''s marriage; the daughter-in-law took over the kitchen","bucket":"precipitating"},{"id":"form-101-7","text":"Feels she has no role","bucket":"perpetuating"},{"id":"form-101-8","text":"Painkillers treat the pain but no one asks about mood","bucket":"perpetuating"},{"id":"form-101-9","text":"Stopped going to her bhajan group","bucket":"perpetuating"},{"id":"form-101-10","text":"The house has a terrace","bucket":"distractor"},{"id":"form-101-11","text":"Knee and back pain with low mood, poor sleep and tearfulness for a year","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Gupta, 63, presents with a moderate depressive episode expressed through body pain: a year of pain, low mood, poor sleep, tearfulness and loss of interest. Osteoarthritis and an identity centred on running the kitchen (predisposing) made role change painful; the daughter-in-law taking over (precipitating) began it. Withdrawal from her bhajan group, pain-only treatment and loss of role (perpetuating) keep it going. Grandchildren and a long friendship (protective) support treating mood and pain together and rebuilding a valued role in the family.","hint":"A 63-year-old who says her knees hurt","tags":{"topic":"depression","difficulty":1,"objective":"Sort a somatic late-life depression into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode with somatic presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
